Axiom thm_NSUM_BOUND_GEN : forall {A : Type'}, forall s : A -> Prop, forall f : A -> nat, forall b : nat, ((@finite_set A s) /\ ((~ (s = (@set0 A))) /\ (forall x : A, (@IN A x s) -> leqn (f x) (divn b (@CARD A s))))) -> leqn (@nsum A s f) b.
