Axiom thm_ABELIAN_GROUP_PRODUCT_ITERATE : forall {A K : Type'}, forall G : hol_Group A, forall ltle : K -> K -> Prop, forall x : K -> A, forall k : K -> Prop, ((@woset K ltle) /\ (((@fld K ltle) = (@setT K)) /\ ((@abelian_group A G) /\ (forall i : K, (@IN K i k) -> @IN A (x i) (@gcar A G))))) -> (@group_product K A G ltle k x) = (@iterate K A (@group_add A G) k x).
