Axiom thm_ABELIAN_GROUP_ITERATE : forall {A K : Type'}, forall G : hol_Group A, forall x : K -> A, forall k : K -> Prop, ((@abelian_group A G) /\ (forall i : K, (@IN K i k) -> @IN A (x i) (@gcar A G))) -> @IN A (@iterate K A (@group_add A G) k x) (@gcar A G).
Axiom thm_group_conjugation : forall {_265792 : Type'}, forall x : _265792, forall G : hol_Group _265792, forall a : _265792, (@group_conjugation _265792 G a x) = (@gop _265792 G a (@gop _265792 G x (@ginv _265792 G a))).
Axiom thm_GROUP_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> @IN A (@group_conjugation A G x y) (@gcar A G).
Axiom thm_GROUP_CONJUGATION_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall b : A, forall x : A, ((@IN A a (@gcar A G)) /\ ((@IN A b (@gcar A G)) /\ (@IN A x (@gcar A G)))) -> (@group_conjugation A G a (@group_conjugation A G b x)) = (@group_conjugation A G (@gop A G a b) x).
Axiom thm_GROUP_CONJUGATION_EQ : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall x : A, forall y : A, ((@IN A a (@gcar A G)) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> ((@group_conjugation A G a x) = (@group_conjugation A G a y)) = (x = y).
Axiom thm_GROUP_CONJUGATION_EQ_SELF : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> ((@group_conjugation A G x y) = y) = ((@gop A G x y) = (@gop A G y x)).
Axiom thm_GROUP_CONJUGATION_EQ_ID : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall x : A, ((@IN A a (@gcar A G)) /\ (@IN A x (@gcar A G))) -> ((@group_conjugation A G a x) = (@g0 A G)) = (x = (@g0 A G)).
Axiom thm_GROUP_CONJUGATION_BY_ID : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> (@group_conjugation A G (@g0 A G) x) = x.
Axiom thm_GROUP_CONJUGATION_LINV : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall x : A, ((@IN A a (@gcar A G)) /\ (@IN A x (@gcar A G))) -> (@group_conjugation A G (@ginv A G a) (@group_conjugation A G a x)) = x.
Axiom thm_GROUP_CONJUGATION_RINV : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall x : A, ((@IN A a (@gcar A G)) /\ (@IN A x (@gcar A G))) -> (@group_conjugation A G a (@group_conjugation A G (@ginv A G a) x)) = x.
Axiom thm_IN_IMAGE_GROUP_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (@subset A s (@gcar A G)))) -> (@IN A x (@IMAGE A A (@group_conjugation A G y) s)) = (@IN A (@group_conjugation A G (@ginv A G y) x) s).
Axiom thm_IMAGE_GROUP_CONJUGATION_SUBSET : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, ((@IN A a (@gcar A G)) /\ (@subset A s (@gcar A G))) -> @subset A (@IMAGE A A (@group_conjugation A G a) s) (@gcar A G).
Axiom thm_IMAGE_GROUP_CONJUGATION_BY_ID : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A s (@gcar A G)) -> (@IMAGE A A (@group_conjugation A G (@g0 A G)) s) = s.
Axiom thm_IMAGE_GROUP_CONJUGATION_BY_MUL : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall a : A, forall b : A, ((@IN A a (@gcar A G)) /\ ((@IN A b (@gcar A G)) /\ (@subset A s (@gcar A G)))) -> (@IMAGE A A (@group_conjugation A G (@gop A G a b)) s) = (@IMAGE A A (@group_conjugation A G a) (@IMAGE A A (@group_conjugation A G b) s)).
Axiom thm_IMAGE_GROUP_CONJUGATION_BY_INV : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, forall t : A -> Prop, ((@IN A a (@gcar A G)) /\ ((@subset A s (@gcar A G)) /\ (@subset A t (@gcar A G)))) -> ((@IMAGE A A (@group_conjugation A G (@ginv A G a)) s) = t) = ((@IMAGE A A (@group_conjugation A G a) t) = s).
Axiom thm_IMAGE_GROUP_CONJUGATION_EQ_SWAP : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, forall t : A -> Prop, ((@IN A a (@gcar A G)) /\ ((@subset A s (@gcar A G)) /\ ((@subset A t (@gcar A G)) /\ ((@IMAGE A A (@group_conjugation A G (@ginv A G a)) s) = t)))) -> (@IMAGE A A (@group_conjugation A G a) t) = s.
Axiom thm_IMAGE_GROUP_CONJUGATION_EQ_PREIMAGE : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, forall t : A -> Prop, ((@IN A a (@gcar A G)) /\ ((@subset A s (@gcar A G)) /\ (@subset A t (@gcar A G)))) -> ((@IMAGE A A (@group_conjugation A G a) s) = t) = ((@GSPEC A (fun GEN_PVAR_805 : A => exists x : A, @SETSPEC A GEN_PVAR_805 ((@IN A x (@gcar A G)) /\ (@IN A (@group_conjugation A G a x) t)) x)) = s).
Axiom thm_subgroup_of : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subgroup_of A s G) = ((@subset A s (@gcar A G)) /\ ((@IN A (@g0 A G) s) /\ ((forall x : A, (@IN A x s) -> @IN A (@ginv A G x) s) /\ (forall x : A, forall y : A, ((@IN A x s) /\ (@IN A y s)) -> @IN A (@gop A G x y) s)))).
Axiom thm_IN_SUBGROUP_ID : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h G) -> @IN A (@g0 A G) h.
Axiom thm_IN_SUBGROUP_INV : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, ((@subgroup_of A h G) /\ (@IN A x h)) -> @IN A (@ginv A G x) h.
Axiom thm_IN_SUBGROUP_MUL : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@subgroup_of A h G) /\ ((@IN A x h) /\ (@IN A y h))) -> @IN A (@gop A G x y) h.
Axiom thm_IN_SUBGROUP_DIV : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@subgroup_of A h G) /\ ((@IN A x h) /\ (@IN A y h))) -> @IN A (@group_div A G x y) h.
Axiom thm_IN_SUBGROUP_POW : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall n : nat, ((@subgroup_of A h G) /\ (@IN A x h)) -> @IN A (@group_pow A G x n) h.
Axiom thm_IN_SUBGROUP_ZPOW : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall n : int, ((@subgroup_of A h G) /\ (@IN A x h)) -> @IN A (@group_zpow A G x n) h.
Axiom thm_IN_SUBGROUP_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A, forall x : A, ((@subgroup_of A h G) /\ ((@IN A a h) /\ (@IN A x h))) -> @IN A (@group_conjugation A G a x) h.
Axiom thm_IN_SUBGROUP_PRODUCT : forall {A K : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall ltle : K -> K -> Prop, forall k : K -> Prop, forall f : K -> A, ((@subgroup_of A h G) /\ (forall i : K, ((@IN K i k) /\ (@IN A (f i) (@gcar A G))) -> @IN A (f i) h)) -> @IN A (@group_product K A G ltle k f) h.
Axiom thm_IN_SUBGROUP_SUM : forall {A K : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall k : K -> Prop, forall f : K -> A, ((@subgroup_of A h G) /\ (forall i : K, ((@IN K i k) /\ (@IN A (f i) (@gcar A G))) -> @IN A (f i) h)) -> @IN A (@group_sum A K G k f) h.
Axiom thm_IMAGE_GROUP_CONJUGATION_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A, ((@subgroup_of A h G) /\ (@IN A a h)) -> (@IMAGE A A (@group_conjugation A G a) h) = h.
Axiom thm_SUBGROUP_OF_INTERS : forall {A : Type'}, forall G : hol_Group A, forall gs : (A -> Prop) -> Prop, ((forall g : A -> Prop, (@IN (A -> Prop) g gs) -> @subgroup_of A g G) /\ (~ (gs = (@set0 (A -> Prop))))) -> @subgroup_of A (@INTERS A gs) G.
Axiom thm_SUBGROUP_OF_INTER : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ (@subgroup_of A h G)) -> @subgroup_of A (@setI A g h) G.
Axiom thm_SUBGROUP_OF_UNIONS : forall {A : Type'}, forall G : hol_Group A, forall u : (A -> Prop) -> Prop, ((~ (u = (@set0 (A -> Prop)))) /\ ((forall h : A -> Prop, (@IN (A -> Prop) h u) -> @subgroup_of A h G) /\ (forall g : A -> Prop, forall h : A -> Prop, ((@IN (A -> Prop) g u) /\ (@IN (A -> Prop) h u)) -> (@subset A g h) \/ (@subset A h g)))) -> @subgroup_of A (@UNIONS A u) G.
Axiom thm_SUBGROUP_OF_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h (@opposite_group A G)) = (@subgroup_of A h G).
Axiom thm_SUBGROUP_OF_IMP_SUBSET : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subgroup_of A s G) -> @subset A s (@gcar A G).
Axiom thm_SUBGROUP_OF_IMP_NONEMPTY : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subgroup_of A s G) -> ~ (s = (@set0 A)).
Axiom thm_TRIVIAL_SUBGROUP_OF : forall {A : Type'}, forall G : hol_Group A, @subgroup_of A (@INSERT A (@g0 A G) (@set0 A)) G.
Axiom thm_CARRIER_SUBGROUP_OF : forall {A : Type'}, forall G : hol_Group A, @subgroup_of A (@gcar A G) G.
Axiom thm_FINITE_SUBGROUPS : forall {A : Type'}, forall G : hol_Group A, (@finite_set A (@gcar A G)) -> @finite_set (A -> Prop) (@GSPEC (A -> Prop) (fun GEN_PVAR_807 : A -> Prop => exists h : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_807 (@subgroup_of A h G) h)).
Axiom thm_FINITE_RESTRICTED_SUBGROUPS : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall G : hol_Group A, (@finite_set A (@gcar A G)) -> @finite_set (A -> Prop) (@GSPEC (A -> Prop) (fun GEN_PVAR_809 : A -> Prop => exists h : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_809 ((@subgroup_of A h G) /\ (P h)) h)).
Axiom thm_subgroup_generated : forall {A : Type'}, forall s : A -> Prop, forall G : hol_Group A, (@subgroup_generated A G s) = (@group A (@pair (A -> Prop) (prod A (prod (A -> A) (A -> A -> A))) (@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_810 : A -> Prop => exists h : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_810 ((@subgroup_of A h G) /\ (@subset A (@setI A (@gcar A G) s) h)) h))) (@pair A (prod (A -> A) (A -> A -> A)) (@g0 A G) (@pair (A -> A) (A -> A -> A) (@ginv A G) (@gop A G))))).
Axiom thm_SUBGROUP_GENERATED : forall {A : Type'}, (forall G : hol_Group A, forall s : A -> Prop, (@gcar A (@subgroup_generated A G s)) = (@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_811 : A -> Prop => exists h : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_811 ((@subgroup_of A h G) /\ (@subset A (@setI A (@gcar A G) s) h)) h)))) /\ ((forall G : hol_Group A, forall s : A -> Prop, (@g0 A (@subgroup_generated A G s)) = (@g0 A G)) /\ ((forall G : hol_Group A, forall s : A -> Prop, (@ginv A (@subgroup_generated A G s)) = (@ginv A G)) /\ (forall G : hol_Group A, forall s : A -> Prop, (@gop A (@subgroup_generated A G s)) = (@gop A G)))).
Axiom thm_SUBGROUP_GENERATED_EQ : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, ((@subgroup_generated A G s) = G) = ((@gcar A (@subgroup_generated A G s)) = (@gcar A G)).
Axiom thm_GROUP_ID_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, @IN A (@g0 A G) (@gcar A (@subgroup_generated A G s)).
Axiom thm_GROUP_INV_SUBGROUP : forall {_267812 : Type'} (G : hol_Group _267812) (s : _267812 -> Prop), forall x : _267812, (@IN _267812 x (@gcar _267812 (@subgroup_generated _267812 G s))) -> @IN _267812 (@ginv _267812 G x) (@gcar _267812 (@subgroup_generated _267812 G s)).
Axiom thm_GROUP_MUL_SUBGROUP : forall {_267853 : Type'} (G : hol_Group _267853) (s : _267853 -> Prop), forall x : _267853, forall y : _267853, ((@IN _267853 x (@gcar _267853 (@subgroup_generated _267853 G s))) /\ (@IN _267853 y (@gcar _267853 (@subgroup_generated _267853 G s)))) -> @IN _267853 (@gop _267853 G x y) (@gcar _267853 (@subgroup_generated _267853 G s)).
Axiom thm_ABELIAN_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@abelian_group A G) -> @abelian_group A (@subgroup_generated A G h).
Axiom thm_GROUP_DIV_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_div A (@subgroup_generated A G s)) = (@group_div A G).
Axiom thm_GROUP_POW_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_pow A (@subgroup_generated A G s)) = (@group_pow A G).
Axiom thm_GROUP_ZPOW_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_zpow A (@subgroup_generated A G s)) = (@group_zpow A G).
Axiom thm_GROUP_CONJUGATION_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_conjugation A (@subgroup_generated A G s)) = (@group_conjugation A G).
Axiom thm_SUBGROUP_GENERATED_RESTRICT : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subgroup_generated A G s) = (@subgroup_generated A G (@setI A (@gcar A G) s)).
Axiom thm_SUBGROUP_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, @subgroup_of A (@gcar A (@subgroup_generated A G s)) G.
Axiom thm_SUBGROUP_GENERATED_MONO : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, (@subset A s t) -> @subset A (@gcar A (@subgroup_generated A G s)) (@gcar A (@subgroup_generated A G t)).
Axiom thm_SUBGROUP_GENERATED_MINIMAL : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, ((@subset A s h) /\ (@subgroup_of A h G)) -> @subset A (@gcar A (@subgroup_generated A G s)) h.
Axiom thm_SUBGROUPS_GENERATED_EQ : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@gcar A (@subgroup_generated A G t))) /\ (@subset A t (@gcar A (@subgroup_generated A G s)))) -> (@subgroup_generated A G s) = (@subgroup_generated A G t).
Axiom thm_SUBGROUP_GENERATED_INDUCT : forall {A : Type'}, forall G : hol_Group A, forall P : A -> Prop, forall s : A -> Prop, ((forall x : A, ((@IN A x (@gcar A G)) /\ (@IN A x s)) -> P x) /\ ((P (@g0 A G)) /\ ((forall x : A, (P x) -> P (@ginv A G x)) /\ (forall x : A, forall y : A, ((P x) /\ (P y)) -> P (@gop A G x y))))) -> forall x : A, (@IN A x (@gcar A (@subgroup_generated A G s))) -> P x.
Axiom thm_GROUP_CARRIER_SUBGROUP_GENERATED_SUBSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, @subset A (@gcar A (@subgroup_generated A G h)) (@gcar A G).
Axiom thm_SUBGROUP_GENERATED_SUPERSET : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, ((@subgroup_generated A G s) = G) = (@subset A (@gcar A G) (@gcar A (@subgroup_generated A G s))).
Axiom thm_SUBGROUP_OF_SUBGROUP_GENERATED_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall k : A -> Prop, (@subgroup_of A h (@subgroup_generated A G k)) = ((@subgroup_of A h G) /\ (@subset A h (@gcar A (@subgroup_generated A G k)))).
Axiom thm_SUBGROUP_GENERATED_INDUCT_STRONG : forall {A : Type'}, forall G : hol_Group A, forall P : A -> Prop, forall s : A -> Prop, ((forall x : A, ((@IN A x (@gcar A G)) /\ (@IN A x s)) -> P x) /\ ((P (@g0 A G)) /\ ((forall x : A, ((@IN A x (@gcar A G)) /\ (P x)) -> P (@ginv A G x)) /\ (forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((P x) /\ (P y)))) -> P (@gop A G x y))))) -> forall x : A, (@IN A x (@gcar A (@subgroup_generated A G s))) -> P x.
Axiom thm_SUBGROUP_GENERATED_INDUCT_ALT : forall {A : Type'}, forall G : hol_Group A, forall P : A -> Prop, forall s : A -> Prop, ((P (@g0 A G)) /\ ((forall x : A, ((@IN A x (@gcar A G)) /\ (@IN A x s)) -> (P x) /\ (P (@ginv A G x))) /\ (forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((P x) /\ (P y)))) -> P (@gop A G x y)))) -> forall x : A, (@IN A x (@gcar A (@subgroup_generated A G s))) -> P x.
Axiom thm_SUBGROUP_GENERATED_INDUCT_LEFT : forall {A : Type'}, forall G : hol_Group A, forall P : A -> Prop, forall s : A -> Prop, ((P (@g0 A G)) /\ (forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A x s) /\ ((@IN A y (@gcar A G)) /\ (P y)))) -> (P (@gop A G x y)) /\ (P (@gop A G (@ginv A G x) y)))) -> forall x : A, (@IN A x (@gcar A (@subgroup_generated A G s))) -> P x.
Axiom thm_FINITE_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@finite_set A (@gcar A G)) -> @finite_set A (@gcar A (@subgroup_generated A G s)).
Axiom thm_CARD_LE_SUBGROUP_GENERATED : forall {A K : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall k : K -> Prop, ((@INFINITE K k) /\ (@le_c A K s k)) -> @le_c A K (@gcar A (@subgroup_generated A G s)) k.
Axiom thm_COUNTABLE_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, ((@COUNTABLE A (@gcar A G)) \/ (@COUNTABLE A s)) -> @COUNTABLE A (@gcar A (@subgroup_generated A G s)).
Axiom thm_SUBGROUP_GENERATED_SUBSET_CARRIER : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, @subset A (@setI A (@gcar A G) h) (@gcar A (@subgroup_generated A G h)).
Axiom thm_SUBSET_CARRIER_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@gcar A G)) /\ (@subset A s t)) -> @subset A s (@gcar A (@subgroup_generated A G t)).
Axiom thm_SUBGROUP_GENERATED_MINIMAL_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, (@subgroup_of A h G) -> (@subset A (@gcar A (@subgroup_generated A G s)) h) = (@subset A (@setI A (@gcar A G) s) h).
Axiom thm_CARRIER_SUBGROUP_GENERATED_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h G) -> (@gcar A (@subgroup_generated A G h)) = h.
Axiom thm_SUBGROUP_OF_SUBGROUP_GENERATED_SUBGROUP_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall k : A -> Prop, (@subgroup_of A k G) -> (@subgroup_of A h (@subgroup_generated A G k)) = ((@subgroup_of A h G) /\ (@subset A h k)).
Axiom thm_SUBGROUP_GENERATED_GROUP_CARRIER : forall {A : Type'}, forall G : hol_Group A, (@subgroup_generated A G (@gcar A G)) = G.
Axiom thm_SUBGROUP_OF_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ (@subset A g h)) -> @subgroup_of A g (@subgroup_generated A G h).
Axiom thm_SUBGROUP_GENERATED_SUBSET_CARRIER_SUBSET : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A s (@gcar A G)) -> @subset A s (@gcar A (@subgroup_generated A G s)).
Axiom thm_SUBGROUP_GENERATED_REFL : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A (@gcar A G) s) -> (@subgroup_generated A G s) = G.
Axiom thm_SUBGROUP_GENERATED_INC : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall x : A, ((@subset A s (@gcar A G)) /\ (@IN A x s)) -> @IN A x (@gcar A (@subgroup_generated A G s)).
Axiom thm_SUBGROUP_GENERATED_INC_GEN : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ (@IN A x s)) -> @IN A x (@gcar A (@subgroup_generated A G s)).
Axiom thm_SUBGROUP_OF_SUBGROUP_GENERATED_REV : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, (@subgroup_of A g (@subgroup_generated A G h)) -> @subgroup_of A g G.
Axiom thm_TRIVIAL_GROUP_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@trivial_group A G) -> @trivial_group A (@subgroup_generated A G s).
Axiom thm_TRIVIAL_GROUP_SUBGROUP_GENERATED_TRIVIAL : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A s (@INSERT A (@g0 A G) (@set0 A))) -> @trivial_group A (@subgroup_generated A G s).
Axiom thm_TRIVIAL_GROUP_SUBGROUP_GENERATED_EQ : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@trivial_group A (@subgroup_generated A G s)) = (@subset A (@setI A (@gcar A G) s) (@INSERT A (@g0 A G) (@set0 A))).
Axiom thm_TRIVIAL_GROUP_GENERATED_BY_ANYTHING : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@trivial_group A G) -> (@subgroup_generated A G s) = G.
