Axiom thm_prod_group : forall {A B : Type'}, forall G : hol_Group A, forall G' : hol_Group B, (@prod_group A B G G') = (@group (prod A B) (@pair ((prod A B) -> Prop) (prod (prod A B) (prod ((prod A B) -> prod A B) ((prod A B) -> (prod A B) -> prod A B))) (@CROSS A B (@gcar A G) (@gcar B G')) (@pair (prod A B) (prod ((prod A B) -> prod A B) ((prod A B) -> (prod A B) -> prod A B)) (@pair A B (@g0 A G) (@g0 B G')) (@pair ((prod A B) -> prod A B) ((prod A B) -> (prod A B) -> prod A B) (@ε ((prod A B) -> prod A B) (fun f : (prod A B) -> prod A B => forall x : A, forall x' : B, @eq (prod A B) (f (@pair A B x x')) (@pair A B (@ginv A G x) (@ginv B G' x')))) (@ε ((prod A B) -> (prod A B) -> prod A B) (fun f : (prod A B) -> (prod A B) -> prod A B => forall x : A, forall x' : B, @eq ((prod A B) -> prod A B) (f (@pair A B x x')) (@ε ((prod A B) -> prod A B) (fun f' : (prod A B) -> prod A B => forall y : A, forall y' : B, @eq (prod A B) (f' (@pair A B y y')) (@pair A B (@gop A G x y) (@gop B G' x' y')))))))))).
