Axiom thm_product_group : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, (@product_group A K k G) = (@group (K -> A) (@pair ((K -> A) -> Prop) (prod (K -> A) (prod ((K -> A) -> K -> A) ((K -> A) -> (K -> A) -> K -> A))) (@cartesian_product A K k (fun i : K => @gcar A (G i))) (@pair (K -> A) (prod ((K -> A) -> K -> A) ((K -> A) -> (K -> A) -> K -> A)) (@RESTRICTION K A k (fun i : K => @g0 A (G i))) (@pair ((K -> A) -> K -> A) ((K -> A) -> (K -> A) -> K -> A) (fun x : K -> A => @RESTRICTION K A k (fun i : K => @ginv A (G i) (x i))) (fun x : K -> A => fun y : K -> A => @RESTRICTION K A k (fun i : K => @gop A (G i) (x i) (y i))))))).
