Axiom thm_GROUP_POW_PRODUCT_GROUP : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K -> Prop, forall x : K -> A, forall n : nat, (@group_pow (K -> A) (@product_group A K k G) x n) = (@RESTRICTION K A k (fun i : K => @group_pow A (G i) (x i) n)).
Axiom thm_GROUP_ZPOW_PRODUCT_GROUP : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K -> Prop, forall x : K -> A, forall n : int, (@group_zpow (K -> A) (@product_group A K k G) x n) = (@RESTRICTION K A k (fun i : K => @group_zpow A (G i) (x i) n)).
