Axiom thm_FINITE_PRODUCT_GROUP : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, (@finite_set (K -> A) (@gcar (K -> A) (@product_group A K k G))) = ((@finite_set K (@GSPEC K (fun GEN_PVAR_818 : K => exists i : K, @SETSPEC K GEN_PVAR_818 ((@IN K i k) /\ (~ (@trivial_group A (G i)))) i))) /\ (forall i : K, (@IN K i k) -> @finite_set A (@gcar A (G i)))).
Axiom thm_ABELIAN_PRODUCT_GROUP : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, (@abelian_group (K -> A) (@product_group A K k G)) = (forall i : K, (@IN K i k) -> @abelian_group A (G i)).
Axiom thm_sum_group : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, (@sum_group A K k G) = (@subgroup_generated (K -> A) (@product_group A K k G) (@GSPEC (K -> A) (fun GEN_PVAR_820 : K -> A => exists x : K -> A, @SETSPEC (K -> A) GEN_PVAR_820 ((@IN (K -> A) x (@cartesian_product A K k (fun i : K => @gcar A (G i)))) /\ (@finite_set K (@GSPEC K (fun GEN_PVAR_819 : K => exists i : K, @SETSPEC K GEN_PVAR_819 ((@IN K i k) /\ (~ ((x i) = (@g0 A (G i))))) i)))) x))).
