Axiom thm_GROUP_SUM_INJECTION : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, forall a : A, forall i : K, (@IN (K -> A) (@RESTRICTION K A k (fun j : K => @COND A (j = i) a (@g0 A (G j)))) (@gcar (K -> A) (@sum_group A K k G))) = ((@IN K i k) -> @IN A a (@gcar A (G i))).
Axiom thm_TRIVIAL_SUM_GROUP : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, (@trivial_group (K -> A) (@sum_group A K k G)) = (forall i : K, (@IN K i k) -> @trivial_group A (G i)).
Axiom thm_CARTESIAN_PRODUCT_SUBGROUP_OF_SUM_GROUP : forall {A K : Type'}, forall k : K -> Prop, forall h : K -> A -> Prop, forall G : K -> hol_Group A, (@subgroup_of (K -> A) (@cartesian_product A K k h) (@sum_group A K k G)) = ((forall i : K, (@IN K i k) -> @subgroup_of A (h i) (G i)) /\ (forall z : K -> A, (@IN (K -> A) z (@cartesian_product A K k h)) -> @finite_set K (@GSPEC K (fun GEN_PVAR_827 : K => exists i : K, @SETSPEC K GEN_PVAR_827 ((@IN K i k) /\ (~ ((z i) = (@g0 A (G i))))) i)))).
