Axiom thm_group_homomorphism : forall {A B : Type'}, forall G : hol_Group A, forall G' : hol_Group B, forall f : A -> B, (@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@subset B (@IMAGE A B f (@gcar A G)) (@gcar B G')) /\ (((f (@g0 A G)) = (@g0 B G')) /\ ((forall x : A, (@IN A x (@gcar A G)) -> (f (@ginv A G x)) = (@ginv B G' (f x))) /\ (forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> (f (@gop A G x y)) = (@gop B G' (f x) (f y)))))).
Axiom thm_group_monomorphism : forall {A B : Type'}, forall G' : hol_Group B, forall G : hol_Group A, forall f : A -> B, (@group_monomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ (forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((f x) = (f y)))) -> x = y)).
Axiom thm_group_epimorphism : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall G' : hol_Group B, (@group_epimorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ ((@IMAGE A B f (@gcar A G)) = (@gcar B G'))).
Axiom thm_group_endomorphism : forall {A : Type'}, forall G : hol_Group A, forall f : A -> A, (@group_endomorphism A G f) = (@group_homomorphism A A (@pair (hol_Group A) (hol_Group A) G G) f).
Axiom thm_group_isomorphisms : forall {A B : Type'}, forall G : hol_Group A, forall G' : hol_Group B, forall f : A -> B, forall g : B -> A, (@group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G G') (@pair (A -> B) (B -> A) f g)) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ ((@group_homomorphism B A (@pair (hol_Group B) (hol_Group A) G' G) g) /\ ((forall x : A, (@IN A x (@gcar A G)) -> (g (f x)) = x) /\ (forall y : B, (@IN B y (@gcar B G')) -> (f (g y)) = y)))).
Axiom thm_group_isomorphism : forall {A B : Type'}, forall G : hol_Group A, forall G' : hol_Group B, forall f : A -> B, (@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = (exists g : B -> A, @group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G G') (@pair (A -> B) (B -> A) f g)).
