Axiom thm_GROUP_ISOMORPHISM_EQ_MONOMORPHISM_FINITE : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall f : A -> B, ((@finite_set A (@gcar A G)) /\ ((@finite_set B (@gcar B H)) /\ ((@CARD A (@gcar A G)) = (@CARD B (@gcar B H))))) -> (@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) = (@group_monomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f).
