Axiom thm_GROUP_ISOMORPHISMS_BETWEEN_SUBGROUPS : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall g : A -> Prop, forall h : B -> Prop, forall f : A -> B, forall f' : B -> A, ((@group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G H) (@pair (A -> B) (B -> A) f f')) /\ ((@subset B (@IMAGE A B f g) h) /\ (@subset A (@IMAGE B A f' h) g))) -> @group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) (@subgroup_generated A G g) (@subgroup_generated B H h)) (@pair (A -> B) (B -> A) f f').
