Axiom thm_GROUP_ISOMORPHISMS_COMPOSE : forall {A B C : Type'}, forall G1 : hol_Group A, forall G2 : hol_Group B, forall G3 : hol_Group C, forall f1 : A -> B, forall f2 : B -> C, forall g1 : B -> A, forall g2 : C -> B, ((@group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G1 G2) (@pair (A -> B) (B -> A) f1 g1)) /\ (@group_isomorphisms B C (@pair (hol_Group B) (hol_Group C) G2 G3) (@pair (B -> C) (C -> B) f2 g2))) -> @group_isomorphisms A C (@pair (hol_Group A) (hol_Group C) G1 G3) (@pair (A -> C) (C -> A) (@o A B C f2 f1) (@o C B A g1 g2)).
