Axiom thm_GROUP_ISOMORPHISM_COMPOSE_REV : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ ((@group_homomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g) /\ (@group_isomorphism A C (@pair (hol_Group A) (hol_Group C) A' C') (@o A B C g f)))) -> (@group_monomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ (@group_epimorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g).
