Axiom thm_GROUP_ISOMORPHISM_INVERSE : forall {A B : Type'}, forall f : A -> B, forall g : B -> A, forall G : hol_Group A, forall H : hol_Group B, ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) /\ (forall x : A, (@IN A x (@gcar A G)) -> (g (f x)) = x)) -> @group_isomorphism B A (@pair (hol_Group B) (hol_Group A) H G) g.
Axiom thm_GROUP_ISOMORPHISMS_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, @group_isomorphisms A A (@pair (hol_Group A) (hol_Group A) G (@opposite_group A G)) (@pair (A -> A) (A -> A) (@ginv A G) (@ginv A G)).
Axiom thm_GROUP_ISOMORPHISM_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, @group_isomorphism A A (@pair (hol_Group A) (hol_Group A) G (@opposite_group A G)) (@ginv A G).
Axiom thm_GROUP_HOMOMORPHISM_FROM_TRIVIAL_GROUP : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall H : hol_Group B, (@trivial_group A G) -> (@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) = ((f (@g0 A G)) = (@g0 B H)).
