Axiom thm_GROUP_HOMOMORPHISM_PAIRWISE : forall {A B C : Type'}, forall f : A -> prod B C, forall G : hol_Group A, forall H : hol_Group B, forall K : hol_Group C, (@group_homomorphism A (prod B C) (@pair (hol_Group A) (hol_Group (prod B C)) G (@prod_group B C H K)) f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G H) (@o A (prod B C) B (@fst B C) f)) /\ (@group_homomorphism A C (@pair (hol_Group A) (hol_Group C) G K) (@o A (prod B C) C (@snd B C) f))).
Axiom thm_GROUP_HOMOMORPHISM_PAIRED : forall {A B C : Type'}, forall f : A -> B, forall g : A -> C, forall G : hol_Group A, forall H : hol_Group B, forall K : hol_Group C, (@group_homomorphism A (prod B C) (@pair (hol_Group A) (hol_Group (prod B C)) G (@prod_group B C H K)) (fun x : A => @pair B C (f x) (g x))) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) /\ (@group_homomorphism A C (@pair (hol_Group A) (hol_Group C) G K) g)).
Axiom thm_GROUP_HOMOMORPHISM_PAIRED2 : forall {A B C D : Type'}, forall f : A -> B, forall g : C -> D, forall G : hol_Group A, forall H : hol_Group C, forall G' : hol_Group B, forall H' : hol_Group D, (@group_homomorphism (prod A C) (prod B D) (@pair (hol_Group (prod A C)) (hol_Group (prod B D)) (@prod_group A C G H) (@prod_group B D G' H')) (@ε ((prod A C) -> prod B D) (fun f' : (prod A C) -> prod B D => forall x : A, forall y : C, @eq (prod B D) (f' (@pair A C x y)) (@pair B D (f x) (g y))))) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ (@group_homomorphism C D (@pair (hol_Group C) (hol_Group D) H H') g)).
Axiom thm_GROUP_ISOMORPHISMS_PAIRED2 : forall {A B C D : Type'}, forall f : A -> B, forall g : C -> D, forall f' : B -> A, forall g' : D -> C, forall G : hol_Group A, forall H : hol_Group C, forall G' : hol_Group B, forall H' : hol_Group D, (@group_isomorphisms (prod A C) (prod B D) (@pair (hol_Group (prod A C)) (hol_Group (prod B D)) (@prod_group A C G H) (@prod_group B D G' H')) (@pair ((prod A C) -> prod B D) ((prod B D) -> prod A C) (@ε ((prod A C) -> prod B D) (fun f'' : (prod A C) -> prod B D => forall x : A, forall y : C, @eq (prod B D) (f'' (@pair A C x y)) (@pair B D (f x) (g y)))) (@ε ((prod B D) -> prod A C) (fun f'' : (prod B D) -> prod A C => forall x : B, forall y : D, @eq (prod A C) (f'' (@pair B D x y)) (@pair A C (f' x) (g' y)))))) = ((@group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G G') (@pair (A -> B) (B -> A) f f')) /\ (@group_isomorphisms C D (@pair (hol_Group C) (hol_Group D) H H') (@pair (C -> D) (D -> C) g g'))).
Axiom thm_GROUP_ISOMORPHISM_PAIRED2 : forall {A B C D : Type'}, forall f : A -> B, forall g : C -> D, forall G : hol_Group A, forall H : hol_Group C, forall G' : hol_Group B, forall H' : hol_Group D, (@group_isomorphism (prod A C) (prod B D) (@pair (hol_Group (prod A C)) (hol_Group (prod B D)) (@prod_group A C G H) (@prod_group B D G' H')) (@ε ((prod A C) -> prod B D) (fun f' : (prod A C) -> prod B D => forall x : A, forall y : C, @eq (prod B D) (f' (@pair A C x y)) (@pair B D (f x) (g y))))) = ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ (@group_isomorphism C D (@pair (hol_Group C) (hol_Group D) H H') g)).
Axiom thm_GROUP_HOMOMORPHISM_OF_FST : forall {A B C : Type'}, forall f : A -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, (@group_homomorphism (prod A B) C (@pair (hol_Group (prod A B)) (hol_Group C) (@prod_group A B A' B') C') (@o (prod A B) A C f (@fst A B))) = (@group_homomorphism A C (@pair (hol_Group A) (hol_Group C) A' C') f).
Axiom thm_GROUP_HOMOMORPHISM_OF_SND : forall {A B C : Type'}, forall f : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, (@group_homomorphism (prod A B) C (@pair (hol_Group (prod A B)) (hol_Group C) (@prod_group A B A' B') C') (@o (prod A B) B C f (@snd A B))) = (@group_homomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') f).
Axiom thm_GROUP_EPIMORPHISM_OF_FST : forall {A B C : Type'}, forall f : A -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, (@group_epimorphism (prod A B) C (@pair (hol_Group (prod A B)) (hol_Group C) (@prod_group A B A' B') C') (@o (prod A B) A C f (@fst A B))) = (@group_epimorphism A C (@pair (hol_Group A) (hol_Group C) A' C') f).
Axiom thm_GROUP_EPIMORPHISM_OF_SND : forall {A B C : Type'}, forall f : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, (@group_epimorphism (prod A B) C (@pair (hol_Group (prod A B)) (hol_Group C) (@prod_group A B A' B') C') (@o (prod A B) B C f (@snd A B))) = (@group_epimorphism B C (@pair (hol_Group B) (hol_Group C) B' C') f).
Axiom thm_GROUP_HOMOMORPHISM_FST : forall {A B : Type'}, forall A' : hol_Group A, forall B' : hol_Group B, @group_homomorphism (prod A B) A (@pair (hol_Group (prod A B)) (hol_Group A) (@prod_group A B A' B') A') (@fst A B).
