Axiom thm_GROUP_ISOMORPHISMS_PROD_GROUP_SWAP : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, @group_isomorphisms (prod A B) (prod B A) (@pair (hol_Group (prod A B)) (hol_Group (prod B A)) (@prod_group A B G H) (@prod_group B A H G)) (@pair ((prod A B) -> prod B A) ((prod B A) -> prod A B) (@ε ((prod A B) -> prod B A) (fun f : (prod A B) -> prod B A => forall x : A, forall y : B, @eq (prod B A) (f (@pair A B x y)) (@pair B A y x))) (@ε ((prod B A) -> prod A B) (fun f : (prod B A) -> prod A B => forall y : B, forall x : A, @eq (prod A B) (f (@pair B A y x)) (@pair A B x y)))).
Axiom thm_GROUP_HOMOMORPHISM_COMPONENTWISE : forall {A B K : Type'}, forall G : hol_Group A, forall k : K -> Prop, forall H : K -> hol_Group B, forall f : A -> K -> B, (@group_homomorphism A (K -> B) (@pair (hol_Group A) (hol_Group (K -> B)) G (@product_group B K k H)) f) = ((@subset (K -> B) (@IMAGE A (K -> B) f (@gcar A G)) (@EXTENSIONAL K B k)) /\ (forall i : K, (@IN K i k) -> @group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G (H i)) (fun x : A => f x i))).
Axiom thm_GROUP_HOMOMORPHISM_COMPONENTWISE_UNIV : forall {A B K : Type'}, forall G : hol_Group A, forall H : K -> hol_Group B, forall f : A -> K -> B, (@group_homomorphism A (K -> B) (@pair (hol_Group A) (hol_Group (K -> B)) G (@product_group B K (@setT K) H)) f) = (forall i : K, @group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G (H i)) (fun x : A => f x i)).
