Axiom thm_GROUP_HOMOMORPHISM_PRODUCT_INJECTION : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, forall i : K, @group_homomorphism A (K -> A) (@pair (hol_Group A) (hol_Group (K -> A)) (G i) (@product_group A K k G)) (fun a : A => @RESTRICTION K A k (fun j : K => @COND A (j = i) a (@g0 A (G j)))).
Axiom thm_GROUP_HOMOMORPHISM_SUM_INJECTION : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, forall i : K, @group_homomorphism A (K -> A) (@pair (hol_Group A) (hol_Group (K -> A)) (G i) (@sum_group A K k G)) (fun a : A => @RESTRICTION K A k (fun j : K => @COND A (j = i) a (@g0 A (G j)))).
Axiom thm_GROUP_HOMOMORPHISM_PRODUCT : forall {A B K : Type'}, forall f : K -> A -> B, forall k : K -> Prop, forall G : K -> hol_Group A, forall H : K -> hol_Group B, (@group_homomorphism (K -> A) (K -> B) (@pair (hol_Group (K -> A)) (hol_Group (K -> B)) (@product_group A K k G) (@product_group B K k H)) (fun x : K -> A => @RESTRICTION K B k (fun i : K => f i (x i)))) = (forall i : K, (@IN K i k) -> @group_homomorphism A B (@pair (hol_Group A) (hol_Group B) (G i) (H i)) (f i)).
Axiom thm_GROUP_HOMOMORPHISM_SUM : forall {A B K : Type'}, forall f : K -> A -> B, forall k : K -> Prop, forall G : K -> hol_Group A, forall H : K -> hol_Group B, (@group_homomorphism (K -> A) (K -> B) (@pair (hol_Group (K -> A)) (hol_Group (K -> B)) (@sum_group A K k G) (@sum_group B K k H)) (fun x : K -> A => @RESTRICTION K B k (fun i : K => f i (x i)))) = (forall i : K, (@IN K i k) -> @group_homomorphism A B (@pair (hol_Group A) (hol_Group B) (G i) (H i)) (f i)).
Axiom thm_GROUP_EPIMORPHISM_PRODUCT_PROJECTION : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K -> Prop, forall i : K, (@IN K i k) -> @group_epimorphism (K -> A) A (@pair (hol_Group (K -> A)) (hol_Group A) (@product_group A K k G) (G i)) (fun x : K -> A => x i).
