Axiom thm_GROUP_EPIMORPHISM_SUM_PROJECTION : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K -> Prop, forall i : K, (@IN K i k) -> @group_epimorphism (K -> A) A (@pair (hol_Group (K -> A)) (hol_Group A) (@sum_group A K k G) (G i)) (fun x : K -> A => x i).
Axiom thm_GROUP_ISOMORPHISM_SUM_PROJECTION : forall {_278429 _278431 : Type'}, forall G : _278431 -> hol_Group _278429, forall k : _278431, @group_isomorphism (_278431 -> _278429) _278429 (@pair (hol_Group (_278431 -> _278429)) (hol_Group _278429) (@sum_group _278429 _278431 (@INSERT _278431 k (@set0 _278431)) G) (G k)) (fun x : _278431 -> _278429 => x k).
Axiom thm_ABELIAN_GROUP_EPIMORPHIC_IMAGE : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall f : A -> B, ((@group_epimorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) /\ (@abelian_group A G)) -> @abelian_group B H.
Axiom thm_ABELIAN_GROUP_HOMOMORPHISM_GROUP_MUL : forall {A B : Type'}, forall f : A -> B, forall g : A -> B, forall A' : hol_Group A, forall B' : hol_Group B, ((@abelian_group B B') /\ ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ (@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') g))) -> @group_homomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') (fun x : A => @gop B B' (f x) (g x)).
Axiom thm_ABELIAN_GROUP_HOMOMORPHISM_INVERSION : forall {A : Type'}, forall G : hol_Group A, (@group_homomorphism A A (@pair (hol_Group A) (hol_Group A) G G) (@ginv A G)) = (@abelian_group A G).
Axiom thm_ABELIAN_GROUP_ISOMORPHISMS_INVERSION : forall {A : Type'}, forall G : hol_Group A, (@group_isomorphisms A A (@pair (hol_Group A) (hol_Group A) G G) (@pair (A -> A) (A -> A) (@ginv A G) (@ginv A G))) = (@abelian_group A G).
Axiom thm_ABELIAN_GROUP_ISOMORPHISM_INVERSION : forall {A : Type'}, forall G : hol_Group A, (@group_isomorphism A A (@pair (hol_Group A) (hol_Group A) G G) (@ginv A G)) = (@abelian_group A G).
Axiom thm_ABELIAN_GROUP_MONOMORPHISM_INVERSION : forall {A : Type'}, forall G : hol_Group A, (@group_monomorphism A A (@pair (hol_Group A) (hol_Group A) G G) (@ginv A G)) = (@abelian_group A G).
Axiom thm_ABELIAN_GROUP_EPIMORPHISM_INVERSION : forall {A : Type'}, forall G : hol_Group A, (@group_epimorphism A A (@pair (hol_Group A) (hol_Group A) G G) (@ginv A G)) = (@abelian_group A G).
Axiom thm_ABELIAN_GROUP_HOMOMORPHISM_POWERING : forall {A : Type'}, forall G : hol_Group A, forall n : nat, (@abelian_group A G) -> @group_homomorphism A A (@pair (hol_Group A) (hol_Group A) G G) (fun x : A => @group_pow A G x n).
Axiom thm_ABELIAN_GROUP_HOMOMORPHISM_ZPOWERING : forall {A : Type'}, forall G : hol_Group A, forall n : int, (@abelian_group A G) -> @group_homomorphism A A (@pair (hol_Group A) (hol_Group A) G G) (fun x : A => @group_zpow A G x n).
Axiom thm_isomorphic_group : forall {A B : Type'}, forall G : hol_Group A, forall G' : hol_Group B, (@isomorphic_group A B G G') = (exists f : A -> B, @group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f).
Axiom thm_GROUP_ISOMORPHISM_IMP_ISOMORPHIC : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall f : A -> B, (@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) -> @isomorphic_group A B G H.
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_SING : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K, @isomorphic_group (K -> A) A (@product_group A K (@INSERT K k (@set0 K)) G) (G k).
Axiom thm_ISOMORPHIC_SUM_GROUP_SING : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K, @isomorphic_group (K -> A) A (@sum_group A K (@INSERT K k (@set0 K)) G) (G k).
Axiom thm_ISOMORPHIC_GROUP_REFL : forall {A : Type'}, forall G : hol_Group A, @isomorphic_group A A G G.
Axiom thm_ISOMORPHIC_GROUP_SYM : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) = (@isomorphic_group B A H G).
Axiom thm_ISOMORPHIC_GROUP_TRANS : forall {A B C : Type'}, forall G1 : hol_Group A, forall G2 : hol_Group B, forall G3 : hol_Group C, ((@isomorphic_group A B G1 G2) /\ (@isomorphic_group B C G2 G3)) -> @isomorphic_group A C G1 G3.
Axiom thm_ISOMORPHIC_GROUP_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, @isomorphic_group A A (@opposite_group A G) G.
Axiom thm_ISOMORPHIC_GROUP_TRIVIALITY : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> (@trivial_group A G) = (@trivial_group B H).
Axiom thm_ISOMORPHIC_TO_TRIVIAL_GROUP : forall {A B : Type'}, (forall G : hol_Group A, forall H : hol_Group B, (@trivial_group A G) -> (@isomorphic_group A B G H) = (@trivial_group B H)) /\ (forall G : hol_Group A, forall H : hol_Group B, (@trivial_group B H) -> (@isomorphic_group A B G H) = (@trivial_group A G)).
Axiom thm_ISOMORPHIC_TRIVIAL_GROUPS : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, ((@trivial_group A G) /\ (@trivial_group B H)) -> @isomorphic_group A B G H.
Axiom thm_ISOMORPHIC_GROUP_SINGLETON_GROUP : forall {A B : Type'}, (forall G : hol_Group A, forall b : B, (@isomorphic_group A B G (@singleton_group B b)) = (@trivial_group A G)) /\ (forall a : A, forall G : hol_Group B, (@isomorphic_group A B (@singleton_group A a) G) = (@trivial_group B G)).
Axiom thm_ISOMORPHIC_GROUP_PROD_GROUPS : forall {A B C D : Type'}, forall G : hol_Group A, forall G' : hol_Group B, forall H : hol_Group C, forall H' : hol_Group D, ((@isomorphic_group A B G G') /\ (@isomorphic_group C D H H')) -> @isomorphic_group (prod A C) (prod B D) (@prod_group A C G H) (@prod_group B D G' H').
Axiom thm_ISOMORPHIC_GROUP_PROD_GROUP_SYM : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, @isomorphic_group (prod A B) (prod B A) (@prod_group A B G H) (@prod_group B A H G).
Axiom thm_ISOMORPHIC_GROUP_PROD_GROUP_SWAP_LEFT : forall {A B C : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall K : hol_Group C, (@isomorphic_group (prod A B) C (@prod_group A B G H) K) = (@isomorphic_group (prod B A) C (@prod_group B A H G) K).
Axiom thm_ISOMORPHIC_GROUP_PROD_GROUP_SWAP_RIGHT : forall {A B C : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall K : hol_Group C, (@isomorphic_group A (prod B C) G (@prod_group B C H K)) = (@isomorphic_group A (prod C B) G (@prod_group C B K H)).
Axiom thm_ISOMORPHIC_PROD_TRIVIAL_GROUP : forall {A B : Type'}, (forall G : hol_Group A, forall H : hol_Group B, (@trivial_group A G) -> @isomorphic_group (prod A B) B (@prod_group A B G H) H) /\ ((forall G : hol_Group A, forall H : hol_Group B, (@trivial_group B H) -> @isomorphic_group (prod A B) A (@prod_group A B G H) G) /\ ((forall G : hol_Group A, forall H : hol_Group B, (@trivial_group A G) -> @isomorphic_group B (prod A B) H (@prod_group A B G H)) /\ (forall G : hol_Group A, forall H : hol_Group B, (@trivial_group B H) -> @isomorphic_group A (prod A B) G (@prod_group A B G H)))).
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_SUPPORT : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, @isomorphic_group (K -> A) (K -> A) (@product_group A K (@GSPEC K (fun GEN_PVAR_832 : K => exists i : K, @SETSPEC K GEN_PVAR_832 ((@IN K i k) /\ (~ (@trivial_group A (G i)))) i)) G) (@product_group A K k G).
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_SYMDIFF : forall {A K : Type'}, forall k : K -> Prop, forall l : K -> Prop, forall G : K -> hol_Group A, (forall i : K, (@IN K i (@setU K (@setD K k l) (@setD K l k))) -> @trivial_group A (G i)) -> @isomorphic_group (K -> A) (K -> A) (@product_group A K k G) (@product_group A K l G).
Axiom thm_ISOMORPHIC_SUM_GROUP_SUPPORT : forall {A K : Type'}, forall k : K -> Prop, forall G : K -> hol_Group A, @isomorphic_group (K -> A) (K -> A) (@sum_group A K (@GSPEC K (fun GEN_PVAR_834 : K => exists i : K, @SETSPEC K GEN_PVAR_834 ((@IN K i k) /\ (~ (@trivial_group A (G i)))) i)) G) (@sum_group A K k G).
Axiom thm_ISOMORPHIC_SUM_GROUP_SYMDIFF : forall {A K : Type'}, forall k : K -> Prop, forall l : K -> Prop, forall G : K -> hol_Group A, (forall i : K, (@IN K i (@setU K (@setD K k l) (@setD K l k))) -> @trivial_group A (G i)) -> @isomorphic_group (K -> A) (K -> A) (@sum_group A K k G) (@sum_group A K l G).
Axiom thm_ISOMORPHIC_SUM_GROUP_BIJECTIONS : forall {A B K L : Type'}, forall s : K -> Prop, forall G : K -> hol_Group A, forall t : L -> Prop, forall H : L -> hol_Group B, forall f : K -> L, forall g : L -> K, ((forall x : K, (@IN K x s) -> (@IN L (f x) t) /\ ((g (f x)) = x)) /\ ((forall y : L, (@IN L y t) -> (@IN K (g y) s) /\ ((f (g y)) = y)) /\ (forall i : K, (@IN K i s) -> @isomorphic_group A B (G i) (H (f i))))) -> @isomorphic_group (K -> A) (L -> B) (@sum_group A K s G) (@sum_group B L t H).
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_BIJECTIONS : forall {A B K L : Type'}, forall s : K -> Prop, forall G : K -> hol_Group A, forall t : L -> Prop, forall H : L -> hol_Group B, forall f : K -> L, forall g : L -> K, ((forall x : K, (@IN K x s) -> (@IN L (f x) t) /\ ((g (f x)) = x)) /\ ((forall y : L, (@IN L y t) -> (@IN K (g y) s) /\ ((f (g y)) = y)) /\ (forall i : K, (@IN K i s) -> @isomorphic_group A B (G i) (H (f i))))) -> @isomorphic_group (K -> A) (L -> B) (@product_group A K s G) (@product_group B L t H).
Axiom thm_ISOMORPHIC_GROUP_PRODUCT_GROUP : forall {A B K : Type'}, forall G : K -> hol_Group A, forall H : K -> hol_Group B, forall k : K -> Prop, (forall i : K, (@IN K i k) -> @isomorphic_group A B (G i) (H i)) -> @isomorphic_group (K -> A) (K -> B) (@product_group A K k G) (@product_group B K k H).
Axiom thm_ISOMORPHIC_GROUP_SUM_GROUP : forall {A B K : Type'}, forall G : K -> hol_Group A, forall H : K -> hol_Group B, forall k : K -> Prop, (forall i : K, (@IN K i k) -> @isomorphic_group A B (G i) (H i)) -> @isomorphic_group (K -> A) (K -> B) (@sum_group A K k G) (@sum_group B K k H).
Axiom thm_GROUP_ISOMORPHISMS_PRODUCT_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @group_isomorphisms (K -> A) (prod (K -> A) (K -> A)) (@pair (hol_Group (K -> A)) (hol_Group (prod (K -> A) (K -> A))) (@product_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@product_group A K k f) (@product_group A K l f))) (@pair ((K -> A) -> prod (K -> A) (K -> A)) ((prod (K -> A) (K -> A)) -> K -> A) (fun f' : K -> A => @pair (K -> A) (K -> A) (@RESTRICTION K A k f') (@RESTRICTION K A l f')) (@ε ((prod (K -> A) (K -> A)) -> K -> A) (fun f' : (prod (K -> A) (K -> A)) -> K -> A => forall f'' : K -> A, forall g : K -> A, @eq (K -> A) (f' (@pair (K -> A) (K -> A) f'' g)) (fun x : K => @COND A (@IN K x k) (f'' x) (g x))))).
Axiom thm_GROUP_ISOMORPHISMS_SUM_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @group_isomorphisms (K -> A) (prod (K -> A) (K -> A)) (@pair (hol_Group (K -> A)) (hol_Group (prod (K -> A) (K -> A))) (@sum_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@sum_group A K k f) (@sum_group A K l f))) (@pair ((K -> A) -> prod (K -> A) (K -> A)) ((prod (K -> A) (K -> A)) -> K -> A) (fun f' : K -> A => @pair (K -> A) (K -> A) (@RESTRICTION K A k f') (@RESTRICTION K A l f')) (@ε ((prod (K -> A) (K -> A)) -> K -> A) (fun f' : (prod (K -> A) (K -> A)) -> K -> A => forall f'' : K -> A, forall g : K -> A, @eq (K -> A) (f' (@pair (K -> A) (K -> A) f'' g)) (fun x : K => @COND A (@IN K x k) (f'' x) (g x))))).
Axiom thm_GROUP_ISOMORPHISM_PRODUCT_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @group_isomorphism (K -> A) (prod (K -> A) (K -> A)) (@pair (hol_Group (K -> A)) (hol_Group (prod (K -> A) (K -> A))) (@product_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@product_group A K k f) (@product_group A K l f))) (fun f' : K -> A => @pair (K -> A) (K -> A) (@RESTRICTION K A k f') (@RESTRICTION K A l f')).
Axiom thm_GROUP_ISOMORPHISM_SUM_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @group_isomorphism (K -> A) (prod (K -> A) (K -> A)) (@pair (hol_Group (K -> A)) (hol_Group (prod (K -> A) (K -> A))) (@sum_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@sum_group A K k f) (@sum_group A K l f))) (fun f' : K -> A => @pair (K -> A) (K -> A) (@RESTRICTION K A k f') (@RESTRICTION K A l f')).
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @isomorphic_group (K -> A) (prod (K -> A) (K -> A)) (@product_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@product_group A K k f) (@product_group A K l f)).
Axiom thm_ISOMORPHIC_SUM_GROUP_DISJOINT_UNION : forall {A K : Type'}, forall f : K -> hol_Group A, forall k : K -> Prop, forall l : K -> Prop, (@DISJOINT K k l) -> @isomorphic_group (K -> A) (prod (K -> A) (K -> A)) (@sum_group A K (@setU K k l) f) (@prod_group (K -> A) (K -> A) (@sum_group A K k f) (@sum_group A K l f)).
Axiom thm_ISOMORPHIC_PRODUCT_GROUP_INSERT : forall {A K : Type'}, forall f : K -> hol_Group A, forall i : K, forall k : K -> Prop, (~ (@IN K i k)) -> @isomorphic_group (K -> A) (prod A (K -> A)) (@product_group A K (@INSERT K i k) f) (@prod_group A (K -> A) (f i) (@product_group A K k f)).
Axiom thm_ISOMORPHIC_SUM_GROUP_INSERT : forall {A K : Type'}, forall f : K -> hol_Group A, forall i : K, forall k : K -> Prop, (~ (@IN K i k)) -> @isomorphic_group (K -> A) (prod A (K -> A)) (@sum_group A K (@INSERT K i k) f) (@prod_group A (K -> A) (f i) (@sum_group A K k f)).
Axiom thm_ISOMORPHIC_GROUP_CARD_EQ : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> @eq_c A B (@gcar A G) (@gcar B H).
Axiom thm_ISOMORPHIC_GROUP_FINITENESS : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> (@finite_set A (@gcar A G)) = (@finite_set B (@gcar B H)).
Axiom thm_ISOMORPHIC_GROUP_INFINITENESS : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> (@INFINITE A (@gcar A G)) = (@INFINITE B (@gcar B H)).
Axiom thm_ISOMORPHIC_GROUP_HAS_ORDER : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall n : nat, (@isomorphic_group A B G H) -> (@HAS_SIZE A (@gcar A G) n) = (@HAS_SIZE B (@gcar B H) n).
Axiom thm_ISOMORPHIC_GROUP_ORDER : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, ((@isomorphic_group A B G H) /\ ((@finite_set A (@gcar A G)) \/ (@finite_set B (@gcar B H)))) -> (@CARD A (@gcar A G)) = (@CARD B (@gcar B H)).
Axiom thm_ISOMORPHIC_GROUP_ABELIANNESS : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> (@abelian_group A G) = (@abelian_group B H).
Axiom thm_CREATE_ISOMORPHIC_COPY_OF_GROUP : forall {A B : Type'}, forall f : A -> B, forall g : B -> A, forall G : hol_Group A, forall s : B -> Prop, forall z : B, forall i : B -> B, forall m : B -> B -> B, ((@IN B z s) /\ ((forall x : A, (@IN A x (@gcar A G)) -> (@IN B (f x) s) /\ ((g (f x)) = x)) /\ ((forall y : B, (@IN B y s) -> (@IN A (g y) (@gcar A G)) /\ ((f (g y)) = y)) /\ (((g z) = (@g0 A G)) /\ ((forall x : B, (@IN B x s) -> (i x) = (f (@ginv A G (g x)))) /\ (forall x : B, forall y : B, ((@IN B x s) /\ (@IN B y s)) -> (m x y) = (f (@gop A G (g x) (g y))))))))) -> (@group_isomorphisms A B (@pair (hol_Group A) (hol_Group B) G (@group B (@pair (B -> Prop) (prod B (prod (B -> B) (B -> B -> B))) s (@pair B (prod (B -> B) (B -> B -> B)) z (@pair (B -> B) (B -> B -> B) i m))))) (@pair (A -> B) (B -> A) f g)) /\ (((@gcar B (@group B (@pair (B -> Prop) (prod B (prod (B -> B) (B -> B -> B))) s (@pair B (prod (B -> B) (B -> B -> B)) z (@pair (B -> B) (B -> B -> B) i m))))) = s) /\ (((@g0 B (@group B (@pair (B -> Prop) (prod B (prod (B -> B) (B -> B -> B))) s (@pair B (prod (B -> B) (B -> B -> B)) z (@pair (B -> B) (B -> B -> B) i m))))) = z) /\ (((@ginv B (@group B (@pair (B -> Prop) (prod B (prod (B -> B) (B -> B -> B))) s (@pair B (prod (B -> B) (B -> B -> B)) z (@pair (B -> B) (B -> B -> B) i m))))) = i) /\ ((@gop B (@group B (@pair (B -> Prop) (prod B (prod (B -> B) (B -> B -> B))) s (@pair B (prod (B -> B) (B -> B -> B)) z (@pair (B -> B) (B -> B -> B) i m))))) = m)))).
Axiom thm_ISOMORPHIC_COPY_OF_GROUP : forall {A B : Type'}, forall G : hol_Group A, forall s : B -> Prop, (exists G' : hol_Group B, ((@gcar B G') = s) /\ (@isomorphic_group A B G G')) = (@eq_c A B (@gcar A G) s).
Axiom thm_GROUP_DIRECT_LIMIT : forall {A : Type'}, forall c : (hol_Group A) -> Prop, ((~ (c = (@set0 (hol_Group A)))) /\ (forall g : hol_Group A, forall g' : hol_Group A, ((@IN (hol_Group A) g c) /\ (@IN (hol_Group A) g' c)) -> exists G : hol_Group A, (@IN (hol_Group A) G c) /\ ((@group_monomorphism A A (@pair (hol_Group A) (hol_Group A) g G) (@I A)) /\ (@group_monomorphism A A (@pair (hol_Group A) (hol_Group A) g' G) (@I A))))) -> exists G : hol_Group A, ((@gcar A G) = (@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_841 : A -> Prop => exists g : hol_Group A, @SETSPEC (A -> Prop) GEN_PVAR_841 (@IN (hol_Group A) g c) (@gcar A g))))) /\ (forall g : hol_Group A, (@IN (hol_Group A) g c) -> @group_monomorphism A A (@pair (hol_Group A) (hol_Group A) g G) (@I A)).
Axiom thm_group_setinv : forall {_281415 : Type'}, forall g : _281415 -> Prop, forall G : hol_Group _281415, (@group_setinv _281415 G g) = (@GSPEC _281415 (fun GEN_PVAR_842 : _281415 => exists x : _281415, @SETSPEC _281415 GEN_PVAR_842 (@IN _281415 x g) (@ginv _281415 G x))).
Axiom thm_group_setmul : forall {_281444 : Type'}, forall g : _281444 -> Prop, forall h : _281444 -> Prop, forall G : hol_Group _281444, (@group_setmul _281444 G g h) = (@GSPEC _281444 (fun GEN_PVAR_843 : _281444 => exists x : _281444, exists y : _281444, @SETSPEC _281444 GEN_PVAR_843 ((@IN _281444 x g) /\ (@IN _281444 y h)) (@gop _281444 G x y))).
Axiom thm_GROUP_SETINV_AS_IMAGE : forall {A : Type'}, forall G : hol_Group A, (@group_setinv A G) = (@IMAGE A A (@ginv A G)).
Axiom thm_SUBGROUP_OF_SETWISE : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subgroup_of A s G) = ((@subset A s (@gcar A G)) /\ ((@IN A (@g0 A G) s) /\ ((@subset A (@group_setinv A G s) s) /\ (@subset A (@group_setmul A G s s) s)))).
Axiom thm_FINITE_SUBGROUP_OF_SETWISE : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@finite_set A s) -> (@subgroup_of A s G) = ((@subset A s (@gcar A G)) /\ ((~ (s = (@set0 A))) /\ (@subset A (@group_setmul A G s s) s))).
Axiom thm_OPPOSITE_GROUP_SETINV : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_setinv A (@opposite_group A G) s) = (@group_setinv A G s).
Axiom thm_OPPOSITE_GROUP_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, (@group_setmul A (@opposite_group A G) s t) = (@group_setmul A G t s).
Axiom thm_GROUP_SETINV_EQ_EMPTY : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, ((@group_setinv A G g) = (@set0 A)) = (g = (@set0 A)).
Axiom thm_GROUP_SETMUL_EQ_EMPTY : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@group_setmul A G g h) = (@set0 A)) = ((g = (@set0 A)) \/ (h = (@set0 A))).
Axiom thm_GROUP_SETMUL_EMPTY : forall {A : Type'}, (forall G : hol_Group A, forall s : A -> Prop, (@group_setmul A G s (@set0 A)) = (@set0 A)) /\ (forall G : hol_Group A, forall t : A -> Prop, (@group_setmul A G (@set0 A) t) = (@set0 A)).
Axiom thm_GROUP_SETINV_MONO : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall s' : A -> Prop, (@subset A s s') -> @subset A (@group_setinv A G s) (@group_setinv A G s').
Axiom thm_GROUP_SETMUL_MONO : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, forall s' : A -> Prop, forall t' : A -> Prop, ((@subset A s s') /\ (@subset A t t')) -> @subset A (@group_setmul A G s t) (@group_setmul A G s' t').
Axiom thm_GROUP_SETMUL_INC_GEN : forall {A : Type'}, (forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@IN A (@g0 A G) s) /\ (@subset A t (@gcar A G))) -> @subset A t (@group_setmul A G s t)) /\ (forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@gcar A G)) /\ (@IN A (@g0 A G) t)) -> @subset A s (@group_setmul A G s t)).
Axiom thm_GROUP_SETMUL_INC : forall {A : Type'}, (forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@subgroup_of A s G) /\ (@subgroup_of A t G)) -> @subset A t (@group_setmul A G s t)) /\ (forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@subgroup_of A s G) /\ (@subgroup_of A t G)) -> @subset A s (@group_setmul A G s t)).
Axiom thm_FINITE_GROUP_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, ((@finite_set A s) /\ (@finite_set A t)) -> @finite_set A (@group_setmul A G s t).
Axiom thm_GROUP_SETMUL_SYM_ELEMENTWISE : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, forall t : A -> Prop, forall u : A -> Prop, (forall a : A, (@IN A a s) -> (@group_setmul A G (@INSERT A a (@set0 A)) t) = (@group_setmul A G u (@INSERT A a (@set0 A)))) -> (@group_setmul A G s t) = (@group_setmul A G u s).
Axiom thm_GROUP_SETINV_SING : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@group_setinv A G (@INSERT A x (@set0 A))) = (@INSERT A (@ginv A G x) (@set0 A)).
Axiom thm_GROUP_SETMUL_SING : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, (@group_setmul A G (@INSERT A x (@set0 A)) (@INSERT A y (@set0 A))) = (@INSERT A (@gop A G x y) (@set0 A)).
Axiom thm_GROUP_SETINV : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, (@subset A g (@gcar A G)) -> @subset A (@group_setinv A G g) (@gcar A G).
Axiom thm_GROUP_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subset A g (@gcar A G)) /\ (@subset A h (@gcar A G))) -> @subset A (@group_setmul A G g h) (@gcar A G).
Axiom thm_GROUP_SETMUL_LID : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, (@subset A g (@gcar A G)) -> (@group_setmul A G (@INSERT A (@g0 A G) (@set0 A)) g) = g.
Axiom thm_GROUP_SETMUL_RID : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, (@subset A g (@gcar A G)) -> (@group_setmul A G g (@INSERT A (@g0 A G) (@set0 A))) = g.
Axiom thm_GROUP_SETMUL_ASSOC : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, forall i : A -> Prop, ((@subset A g (@gcar A G)) /\ ((@subset A h (@gcar A G)) /\ (@subset A i (@gcar A G)))) -> (@group_setmul A G g (@group_setmul A G h i)) = (@group_setmul A G (@group_setmul A G g h) i).
Axiom thm_GROUP_SETMUL_SYM : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@abelian_group A G) /\ ((@subset A g (@gcar A G)) /\ (@subset A h (@gcar A G)))) -> (@group_setmul A G g h) = (@group_setmul A G h g).
Axiom thm_GROUP_SETINV_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h G) -> (@group_setinv A G h) = h.
Axiom thm_GROUP_SETMUL_LSUBSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, ((@subgroup_of A h G) /\ ((@subset A s h) /\ (~ (s = (@set0 A))))) -> (@group_setmul A G s h) = h.
Axiom thm_GROUP_SETMUL_RSUBSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, ((@subgroup_of A h G) /\ ((@subset A s h) /\ (~ (s = (@set0 A))))) -> (@group_setmul A G h s) = h.
Axiom thm_GROUP_SETMUL_LSUBSET_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, ((@subgroup_of A h G) /\ (@subset A s (@gcar A G))) -> ((@group_setmul A G s h) = h) = ((@subset A s h) /\ (~ (s = (@set0 A)))).
Axiom thm_GROUP_SETMUL_RSUBSET_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, ((@subgroup_of A h G) /\ (@subset A s (@gcar A G))) -> ((@group_setmul A G h s) = h) = ((@subset A s h) /\ (~ (s = (@set0 A)))).
Axiom thm_IMAGE_GROUP_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, (@IMAGE A A (@group_conjugation A G a) s) = (@group_setmul A G (@INSERT A a (@set0 A)) (@group_setmul A G s (@INSERT A (@ginv A G a) (@set0 A)))).
Axiom thm_IMAGE_GROUP_CONJUGATION_EQ : forall {A : Type'}, forall G : hol_Group A, forall a : A, forall s : A -> Prop, forall t : A -> Prop, ((@IN A a (@gcar A G)) /\ ((@subset A s (@gcar A G)) /\ (@subset A t (@gcar A G)))) -> ((@IMAGE A A (@group_conjugation A G a) s) = t) = ((@group_setmul A G (@INSERT A a (@set0 A)) s) = (@group_setmul A G t (@INSERT A a (@set0 A)))).
Axiom thm_GROUP_SETMUL_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h G) -> (@group_setmul A G h h) = h.
Axiom thm_GROUP_SETMUL_LCANCEL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ ((@subset A g (@gcar A G)) /\ (@subset A h (@gcar A G)))) -> ((@group_setmul A G (@INSERT A x (@set0 A)) g) = (@group_setmul A G (@INSERT A x (@set0 A)) h)) = (g = h).
Axiom thm_GROUP_SETMUL_RCANCEL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ ((@subset A g (@gcar A G)) /\ (@subset A h (@gcar A G)))) -> ((@group_setmul A G g (@INSERT A x (@set0 A))) = (@group_setmul A G h (@INSERT A x (@set0 A)))) = (g = h).
Axiom thm_GROUP_SETMUL_LCANCEL_SET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (@subgroup_of A h G))) -> ((@group_setmul A G h (@INSERT A x (@set0 A))) = (@group_setmul A G h (@INSERT A y (@set0 A)))) = (@IN A (@group_div A G x y) h).
Axiom thm_GROUP_SETMUL_RCANCEL_SET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (@subgroup_of A h G))) -> ((@group_setmul A G (@INSERT A x (@set0 A)) h) = (@group_setmul A G (@INSERT A y (@set0 A)) h)) = (@IN A (@gop A G (@ginv A G x) y) h).
Axiom thm_SUBGROUP_SETMUL_EQ : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ (@subgroup_of A h G)) -> (@subgroup_of A (@group_setmul A G g h) G) = ((@group_setmul A G g h) = (@group_setmul A G h g)).
Axiom thm_SUBGROUP_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@abelian_group A G) /\ ((@subgroup_of A g G) /\ (@subgroup_of A h G))) -> @subgroup_of A (@group_setmul A G g h) G.
Axiom thm_SUBGROUP_GENERATED_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ (@subgroup_of A h G)) -> (@subgroup_generated A G (@group_setmul A G g h)) = (@subgroup_generated A G (@setU A g h)).
Axiom thm_CARRIER_SUBGROUP_GENERATED_UNION : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ ((@subgroup_of A h G) /\ ((@group_setmul A G g h) = (@group_setmul A G h g)))) -> (@gcar A (@subgroup_generated A G (@setU A g h))) = (@group_setmul A G g h).
Axiom thm_group_action : forall {A X : Type'}, forall s : X -> Prop, forall G : hol_Group A, forall a : A -> X -> X, (@group_action A X G s a) = ((forall g : A, forall x : X, ((@IN A g (@gcar A G)) /\ (@IN X x s)) -> @IN X (a g x) s) /\ ((forall x : X, (@IN X x s) -> (a (@g0 A G) x) = x) /\ (forall g : A, forall h : A, forall x : X, ((@IN A g (@gcar A G)) /\ ((@IN A h (@gcar A G)) /\ (@IN X x s))) -> (a (@gop A G g h) x) = (a g (a h x))))).
Axiom thm_GROUP_ACTION_ALT : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, (@group_action A X G s a) = ((forall g : A, forall x : X, ((@IN A g (@gcar A G)) /\ (@IN X x s)) -> @IN X (a g x) s) /\ ((forall x : X, (@IN X x s) -> (a (@g0 A G) x) = x) /\ (forall g : A, forall h : A, forall x : X, ((@IN A g (@gcar A G)) /\ ((@IN A h (@gcar A G)) /\ (@IN X x s))) -> (a g (a h x)) = (a (@gop A G g h) x)))).
Axiom thm_GROUP_ACTION_MUL : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, forall h : A, forall x : X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ ((@IN A h (@gcar A G)) /\ (@IN X x s)))) -> (a g (a h x)) = (a (@gop A G g h) x).
Axiom thm_GROUP_ACTION_LINV : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, forall x : X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ (@IN X x s))) -> (a (@ginv A G g) (a g x)) = x.
Axiom thm_GROUP_ACTION_RINV : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, forall x : X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ (@IN X x s))) -> (a g (a (@ginv A G g) x)) = x.
Axiom thm_GROUP_ACTION_BIJECTIVE : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, ((@group_action A X G s a) /\ (@IN A g (@gcar A G))) -> forall y : X, (@IN X y s) -> @ex1 X (fun x : X => (@IN X x s) /\ ((a g x) = y)).
Axiom thm_GROUP_ACTION_SURJECTIVE : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, forall y : X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ (@IN X y s))) -> exists x : X, (a g x) = y.
Axiom thm_GROUP_ACTION_INJECTIVE : forall {A X : Type'} (g : A) (x : X) (y : X), forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ ((@IN X x s) /\ (@IN X y s)))) -> ((a g x) = (a g y)) = (x = y).
Axiom thm_GROUP_ACTION_ON_SUBSET : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall t : X -> Prop, forall a : A -> X -> X, ((@group_action A X G s a) /\ ((@subset X t s) /\ (forall g : A, forall x : X, ((@IN A g (@gcar A G)) /\ (@IN X x t)) -> @IN X (a g x) t))) -> @group_action A X G t a.
Axiom thm_GROUP_ACTION_FROM_SUBGROUP : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall h : A -> Prop, forall a : A -> X -> X, (@group_action A X G s a) -> @group_action A X (@subgroup_generated A G h) s a.
Axiom thm_GROUP_ACTION_IMAGE : forall {A X : Type'}, forall G : hol_Group A, forall u : (X -> Prop) -> Prop, forall s : X -> Prop, forall a : A -> X -> X, ((@group_action A X G s a) /\ ((forall t : X -> Prop, (@IN (X -> Prop) t u) -> @subset X t s) /\ (forall g : A, forall t : X -> Prop, ((@IN A g (@gcar A G)) /\ (@IN (X -> Prop) t u)) -> @IN (X -> Prop) (@IMAGE X X (a g) t) u))) -> @group_action A (X -> Prop) G u (@o A (X -> X) ((X -> Prop) -> X -> Prop) (@IMAGE X X) a).
Axiom thm_GROUP_ACTION_IMAGE_SIZED : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall k : nat, forall a : A -> X -> X, (@group_action A X G s a) -> @group_action A (X -> Prop) G (@GSPEC (X -> Prop) (fun GEN_PVAR_854 : X -> Prop => exists t : X -> Prop, @SETSPEC (X -> Prop) GEN_PVAR_854 ((@subset X t s) /\ (@HAS_SIZE X t k)) t)) (@o A (X -> X) ((X -> Prop) -> X -> Prop) (@IMAGE X X) a).
Axiom thm_group_stabilizer : forall {A X : Type'}, forall G : hol_Group A, forall a : A -> X -> X, forall x : X, (@group_stabilizer A X G a x) = (@GSPEC A (fun GEN_PVAR_855 : A => exists g : A, @SETSPEC A GEN_PVAR_855 ((@IN A g (@gcar A G)) /\ ((a g x) = x)) g)).
Axiom thm_GROUP_STABILIZER_SUBSET_CARRIER : forall {_284608 _284614 : Type'}, forall G : hol_Group _284614, forall a : _284614 -> _284608 -> _284608, forall x : _284608, @subset _284614 (@group_stabilizer _284614 _284608 G a x) (@gcar _284614 G).
Axiom thm_FINITE_GROUP_STABILIZER : forall {A X : Type'}, forall G : hol_Group A, forall a : A -> X -> X, forall x : X, (@finite_set A (@gcar A G)) -> @finite_set A (@group_stabilizer A X G a x).
Axiom thm_SUBGROUP_OF_GROUP_STABILIZER : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@group_action A X G s a) /\ (@IN X x s)) -> @subgroup_of A (@group_stabilizer A X G a x) G.
Axiom thm_GROUP_STABILIZER_NONEMPTY : forall {A X : Type'}, forall G : hol_Group A, forall a : A -> X -> X, forall s : X -> Prop, forall x : X, ((@group_action A X G s a) /\ (@IN X x s)) -> ~ ((@group_stabilizer A X G a x) = (@set0 A)).
Axiom thm_GROUP_STABILIZER_SUBGROUP_GENERATED : forall {A X : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A -> X -> X, forall x : X, (@group_stabilizer A X (@subgroup_generated A G h) a x) = (@setI A (@gcar A (@subgroup_generated A G h)) (@group_stabilizer A X G a x)).
Axiom thm_GROUP_STABILIZER_ON_SUBGROUP : forall {A X : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A -> X -> X, forall x : X, (@subgroup_of A h G) -> (@group_stabilizer A X (@subgroup_generated A G h) a x) = (@setI A h (@group_stabilizer A X G a x)).
Axiom thm_GROUP_ACTION_KERNEL_POINTWISE : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, (@GSPEC A (fun GEN_PVAR_856 : A => exists g : A, @SETSPEC A GEN_PVAR_856 ((@IN A g (@gcar A G)) /\ (forall x : X, (@IN X x s) -> (a g x) = x)) g)) = (@COND (A -> Prop) (s = (@set0 X)) (@gcar A G) (@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_857 : A -> Prop => exists x : X, @SETSPEC (A -> Prop) GEN_PVAR_857 (@IN X x s) (@group_stabilizer A X G a x))))).
Axiom thm_GROUP_ACTION_EQ : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall g : A, forall h : A, forall x : X, ((@group_action A X G s a) /\ ((@IN A g (@gcar A G)) /\ ((@IN A h (@gcar A G)) /\ (@IN X x s)))) -> ((a g x) = (a h x)) = (@IN A (@gop A G (@ginv A G g) h) (@group_stabilizer A X G a x)).
