Axiom thm_GROUP_ORBIT_REFL_EQ : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, (@group_action A X G s a) -> (@group_orbit A X G s a x x) = (@IN X x s).
Axiom thm_GROUP_ORBIT_REFL : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@group_action A X G s a) /\ (@IN X x s)) -> @group_orbit A X G s a x x.
Axiom thm_IN_GROUP_ORBIT_SELF : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@group_action A X G s a) /\ (@IN X x s)) -> @IN X x (@group_orbit A X G s a x).
Axiom thm_GROUP_ORBIT_EMPTY : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, (~ (@IN X x s)) -> (@group_orbit A X G s a x) = (@set0 X).
