Axiom thm_GROUP_ORBIT_SYM_EQ : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, forall y : X, (@group_action A X G s a) -> (@group_orbit A X G s a x y) = (@group_orbit A X G s a y x).
