Axiom thm_GROUP_ORBIT_EQ_SING_SELF : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, (@group_action A X G s a) -> ((@group_orbit A X G s a x) = (@INSERT X x (@set0 X))) = ((@IN X x s) /\ (forall g : A, (@IN A g (@gcar A G)) -> (a g x) = x)).
