Axiom thm_UNIONS_GROUP_ORBITS_CLOSED : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall t : X -> Prop, ((@group_action A X G s a) /\ ((@subset X t s) /\ (forall g : A, (@IN A g (@gcar A G)) -> @subset X (@IMAGE X X (a g) t) t))) -> (@UNIONS X (@GSPEC (X -> Prop) (fun GEN_PVAR_863 : X -> Prop => exists x : X, @SETSPEC (X -> Prop) GEN_PVAR_863 (@IN X x t) (@group_orbit A X G s a x)))) = t.
Axiom thm_UNIONS_GROUP_ORBITS_INVARIANT : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall t : X -> Prop, ((@group_action A X G s a) /\ ((@subset X t s) /\ (forall g : A, (@IN A g (@gcar A G)) -> (@IMAGE X X (a g) t) = t))) -> (@UNIONS X (@GSPEC (X -> Prop) (fun GEN_PVAR_864 : X -> Prop => exists x : X, @SETSPEC (X -> Prop) GEN_PVAR_864 (@IN X x t) (@group_orbit A X G s a x)))) = t.
Axiom thm_UNIONS_GROUP_ORBITS : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, (@group_action A X G s a) -> (@UNIONS X (@GSPEC (X -> Prop) (fun GEN_PVAR_865 : X -> Prop => exists x : X, @SETSPEC (X -> Prop) GEN_PVAR_865 (@IN X x s) (@group_orbit A X G s a x)))) = s.
Axiom thm_NSUM_CARD_GROUP_ORBITS : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, ((@group_action A X G s a) /\ (@finite_set X s)) -> (@nsum (X -> Prop) (@GSPEC (X -> Prop) (fun GEN_PVAR_866 : X -> Prop => exists x : X, @SETSPEC (X -> Prop) GEN_PVAR_866 (@IN X x s) (@group_orbit A X G s a x))) (@CARD X)) = (@CARD X s).
Axiom thm_ORBIT_STABILIZER_MUL_GEN : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@group_action A X G s a) /\ (@IN X x s)) -> @eq_c (prod X A) A (@mul_c A X (@group_orbit A X G s a x) (@group_stabilizer A X G a x)) (@gcar A G).
Axiom thm_ORBIT_STABILIZER_MUL : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@finite_set A (@gcar A G)) /\ ((@group_action A X G s a) /\ (@IN X x s))) -> (muln (@CARD X (@group_orbit A X G s a x)) (@CARD A (@group_stabilizer A X G a x))) = (@CARD A (@gcar A G)).
Axiom thm_CARD_GROUP_ORBIT_DIVIDES : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@finite_set A (@gcar A G)) /\ ((@group_action A X G s a) /\ (@IN X x s))) -> num_divides (@CARD X (@group_orbit A X G s a x)) (@CARD A (@gcar A G)).
Axiom thm_CARD_GROUP_STABILIZER_DIVIDES : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall x : X, ((@finite_set A (@gcar A G)) /\ ((@group_action A X G s a) /\ (@IN X x s))) -> num_divides (@CARD A (@group_stabilizer A X G a x)) (@CARD A (@gcar A G)).
