Axiom thm_GROUP_ACTION_SUBSET_TRANSLATION : forall {A : Type'}, forall G : hol_Group A, forall u : (A -> Prop) -> Prop, ((forall s : A -> Prop, (@IN (A -> Prop) s u) -> @subset A s (@gcar A G)) /\ (forall a : A, forall s : A -> Prop, ((@IN A a (@gcar A G)) /\ (@IN (A -> Prop) s u)) -> @IN (A -> Prop) (@IMAGE A A (@gop A G a) s) u)) -> @group_action A (A -> Prop) G u (@o A (A -> A) ((A -> Prop) -> A -> Prop) (@IMAGE A A) (@gop A G)).
Axiom thm_GROUP_ACTION_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, @group_action A A G (@gcar A G) (@group_conjugation A G).
Axiom thm_CARD_GROUP_SETMUL_GEN : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@subgroup_of A g G) /\ (@subgroup_of A h G)) -> @eq_c (prod A A) (prod A A) (@mul_c A A (@group_setmul A G g h) (@setI A g h)) (@mul_c A A g h).
Axiom thm_CARD_GROUP_SETMUL_MUL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@finite_set A g) /\ ((@finite_set A h) /\ ((@subgroup_of A g G) /\ (@subgroup_of A h G)))) -> (muln (@CARD A (@group_setmul A G g h)) (@CARD A (@setI A g h))) = (muln (@CARD A g) (@CARD A h)).
Axiom thm_CARD_GROUP_SETMUL : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@finite_set A g) /\ ((@finite_set A h) /\ ((@subgroup_of A g G) /\ (@subgroup_of A h G)))) -> (@CARD A (@group_setmul A G g h)) = (divn (muln (@CARD A g) (@CARD A h)) (@CARD A (@setI A g h))).
Axiom thm_CARD_GROUP_SETMUL_DIVIDES : forall {A : Type'}, forall G : hol_Group A, forall g : A -> Prop, forall h : A -> Prop, ((@finite_set A g) /\ ((@finite_set A h) /\ ((@subgroup_of A g G) /\ (@subgroup_of A h G)))) -> num_divides (@CARD A (@group_setmul A G g h)) (muln (@CARD A g) (@CARD A h)).
Axiom thm_GROUP_ORBIT_COMMON_DIVISOR : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall n : nat, ((@group_action A X G s a) /\ ((@finite_set X s) /\ (forall x : X, (@IN X x s) -> num_divides n (@CARD X (@group_orbit A X G s a x))))) -> num_divides n (@CARD X s).
Axiom thm_GROUP_ORBIT_COMMON_INDEX : forall {A X : Type'}, forall G : hol_Group A, forall s : X -> Prop, forall a : A -> X -> X, forall p : nat, forall k : nat, ((@group_action A X G s a) /\ ((@finite_set X s) /\ (((s = (@set0 X)) -> k = (NUMERAL O)) /\ (forall x : X, (@IN X x s) -> leqn k (index p (@CARD X (@group_orbit A X G s a x))))))) -> leqn k (index p (@CARD X s)).
Axiom thm_right_coset : forall {_288210 : Type'}, forall G : hol_Group _288210, forall h : _288210 -> Prop, forall x : _288210, (@right_coset _288210 G h x) = (@group_setmul _288210 G h (@INSERT _288210 x (@set0 _288210))).
Axiom thm_left_coset : forall {_288225 : Type'}, forall G : hol_Group _288225, forall x : _288225, forall h : _288225 -> Prop, (@left_coset _288225 G x h) = (@group_setmul _288225 G (@INSERT _288225 x (@set0 _288225)) h).
Axiom thm_LEFT_COSET_AS_IMAGE : forall {A : Type'} (G : hol_Group A), forall x : A, forall h : A -> Prop, (@left_coset A G x h) = (@IMAGE A A (@gop A G x) h).
Axiom thm_RIGHT_COSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ (@subset A h (@gcar A G))) -> @subset A (@right_coset A G h x) (@gcar A G).
Axiom thm_LEFT_COSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ (@subset A h (@gcar A G))) -> @subset A (@left_coset A G x h) (@gcar A G).
Axiom thm_IN_RIGHT_COSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall a : A, ((@subset A h (@gcar A G)) /\ ((@IN A a (@gcar A G)) /\ (@IN A x (@gcar A G)))) -> (@IN A x (@right_coset A G h a)) = (@IN A (@gop A G x (@ginv A G a)) h).
Axiom thm_IN_LEFT_COSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall a : A, ((@subset A h (@gcar A G)) /\ ((@IN A a (@gcar A G)) /\ (@IN A x (@gcar A G)))) -> (@IN A x (@left_coset A G a h)) = (@IN A (@gop A G (@ginv A G a) x) h).
Axiom thm_IN_RIGHT_COSET_INV : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@subset A h (@gcar A G)) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> (@IN A x (@right_coset A G h (@ginv A G y))) = (@IN A (@gop A G x y) h).
Axiom thm_IN_LEFT_COSET_INV : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, forall y : A, ((@subset A h (@gcar A G)) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> (@IN A x (@left_coset A G (@ginv A G y) h)) = (@IN A (@gop A G y x) h).
Axiom thm_GROUP_SETINV_RIGHT_COSET_GEN : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A, ((@subgroup_of A h G) /\ (@IN A a (@gcar A G))) -> (@group_setinv A G (@right_coset A G h a)) = (@left_coset A G (@ginv A G a) h).
Axiom thm_GROUP_SETINV_LEFT_COSET_GEN : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall a : A, ((@subgroup_of A h G) /\ (@IN A a (@gcar A G))) -> (@group_setinv A G (@left_coset A G a h)) = (@right_coset A G h (@ginv A G a)).
Axiom thm_RIGHT_COSET_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, (@right_coset A G h x) = (@left_coset A (@opposite_group A G) x h).
Axiom thm_LEFT_COSET_OPPOSITE_GROUP : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, (@left_coset A G x h) = (@right_coset A (@opposite_group A G) h x).
Axiom thm_GROUP_CONJUGATION_RIGHT_COSET : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, ((@IN A x (@gcar A G)) /\ (@subset A h (@gcar A G))) -> (@IMAGE A A (@group_conjugation A G x) (@right_coset A G h x)) = (@left_coset A G x h).
