Axiom thm_SCHREIER_TRANSVERSAL_LEMMA : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall s : A -> Prop, forall t : A -> Prop, ((@subgroup_of A h G) /\ ((@subset A s (@gcar A G)) /\ (((@subgroup_generated A G s) = G) /\ ((forall x : A, (@IN A x s) -> @IN A (@ginv A G x) s) /\ ((@subset A t (@gcar A G)) /\ (((@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_916 : A -> Prop => exists x : A, @SETSPEC (A -> Prop) GEN_PVAR_916 (@IN A x t) (@right_coset A G h x)))) = (@gcar A G)) /\ (@subset A (@setI A t h) (@INSERT A (@g0 A G) (@set0 A))))))))) -> (@gcar A (@subgroup_generated A G (@setI A h (@group_setmul A G t (@group_setmul A G s (@group_setinv A G t)))))) = h.
