Axiom thm_group_normalizer : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_normalizer A G s) = (@GSPEC A (fun GEN_PVAR_945 : A => exists x : A, @SETSPEC A GEN_PVAR_945 ((@IN A x (@gcar A G)) /\ ((@group_setmul A G (@INSERT A x (@set0 A)) (@setI A (@gcar A G) s)) = (@group_setmul A G (@setI A (@gcar A G) s) (@INSERT A x (@set0 A))))) x)).
