Axiom thm_GROUP_NORMALIZER : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A s (@gcar A G)) -> (@group_normalizer A G s) = (@GSPEC A (fun GEN_PVAR_947 : A => exists x : A, @SETSPEC A GEN_PVAR_947 ((@IN A x (@gcar A G)) /\ ((@group_setmul A G (@INSERT A x (@set0 A)) s) = (@group_setmul A G s (@INSERT A x (@set0 A))))) x)).
Axiom thm_GROUP_NORMALIZER_CONJUGATION_EQ : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_normalizer A G s) = (@GSPEC A (fun GEN_PVAR_948 : A => exists x : A, @SETSPEC A GEN_PVAR_948 ((@IN A x (@gcar A G)) /\ ((@IMAGE A A (@group_conjugation A G x) (@setI A (@gcar A G) s)) = (@setI A (@gcar A G) s))) x)).
Axiom thm_GROUP_NORMALIZER_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@subset A s (@gcar A G)) -> (@group_normalizer A G s) = (@GSPEC A (fun GEN_PVAR_949 : A => exists x : A, @SETSPEC A GEN_PVAR_949 ((@IN A x (@gcar A G)) /\ ((@IMAGE A A (@group_conjugation A G x) s) = s)) x)).
Axiom thm_GROUP_NORMALIZER_FINITE : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, ((@subset A s (@gcar A G)) /\ (@finite_set A s)) -> (@group_normalizer A G s) = (@GSPEC A (fun GEN_PVAR_950 : A => exists x : A, @SETSPEC A GEN_PVAR_950 ((@IN A x (@gcar A G)) /\ (@subset A (@IMAGE A A (@group_conjugation A G x) s) s)) x)).
Axiom thm_GROUP_CENTRALIZER_RESTRICT : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, (@group_centralizer A G s) = (@group_centralizer A G (@setI A (@gcar A G) s)).
