Axiom thm_IN_GROUP_CENTRALIZER_ID : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, @IN A (@g0 A G) (@group_centralizer A G s).
Axiom thm_IN_GROUP_NORMALIZER_ID : forall {A : Type'}, forall G : hol_Group A, forall s : A -> Prop, @IN A (@g0 A G) (@group_normalizer A G s).
