Axiom thm_GROUP_CENTRALIZER_SUBSET_EQ : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, (@subgroup_of A h G) -> (@subset A h (@group_centralizer A G h)) = (@abelian_group A (@subgroup_generated A G h)).
