Axiom thm_GROUP_NORMALIZER_MAXIMAL_GEN : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall n : A -> Prop, (@normal_subgroup_of A h (@subgroup_generated A G n)) = ((@subgroup_of A h (@subgroup_generated A G n)) /\ (@subset A (@setI A (@gcar A G) n) (@group_normalizer A G h))).
