Axiom thm_MAXIMAL_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall n : A -> Prop, (@normal_subgroup_of A n G) -> (forall h : A -> Prop, ((@subgroup_of A h G) /\ (@proper A n h)) -> h = (@gcar A G)) = (forall k : (A -> Prop) -> Prop, (@subgroup_of (A -> Prop) k (@quotient_group A G n)) -> (k = (@INSERT (A -> Prop) (@g0 (A -> Prop) (@quotient_group A G n)) (@set0 (A -> Prop)))) \/ (k = (@gcar (A -> Prop) (@quotient_group A G n)))).
Axiom thm_MAXIMAL_NORMAL_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall n : A -> Prop, (@normal_subgroup_of A n G) -> (forall h : A -> Prop, ((@normal_subgroup_of A h G) /\ (@proper A n h)) -> h = (@gcar A G)) = (forall k : (A -> Prop) -> Prop, (@normal_subgroup_of (A -> Prop) k (@quotient_group A G n)) -> (k = (@INSERT (A -> Prop) (@g0 (A -> Prop) (@quotient_group A G n)) (@set0 (A -> Prop)))) \/ (k = (@gcar (A -> Prop) (@quotient_group A G n)))).
Axiom thm_trivial_homomorphism : forall {A B : Type'}, forall G : hol_Group A, forall f : A -> B, forall G' : hol_Group B, (@trivial_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ (forall x : A, (@IN A x (@gcar A G)) -> (f x) = (@g0 B G'))).
Axiom thm_GROUP_KERNEL_IMAGE_TRIVIAL : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall G' : hol_Group B, (@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) -> ((@group_kernel A B (@pair (hol_Group A) (hol_Group B) G G') f) = (@gcar A G)) = ((@group_image A B (@pair (hol_Group A) (hol_Group B) G G') f) = (@INSERT B (@g0 B G') (@set0 B))).
Axiom thm_TRIVIAL_HOMOMORPHISM_GROUP_KERNEL : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall G' : hol_Group B, (@trivial_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ ((@group_kernel A B (@pair (hol_Group A) (hol_Group B) G G') f) = (@gcar A G))).
Axiom thm_TRIVIAL_HOMOMORPHISM_GROUP_IMAGE : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall G' : hol_Group B, (@trivial_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) = ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G G') f) /\ ((@group_image A B (@pair (hol_Group A) (hol_Group B) G G') f) = (@INSERT B (@g0 B G') (@set0 B)))).
Axiom thm_TRIVIAL_HOMOMORPHISM_TRIVIAL : forall {_303755 _303756 : Type'}, forall G : hol_Group _303756, forall H : hol_Group _303755, @trivial_homomorphism _303756 _303755 (@pair (hol_Group _303756) (hol_Group _303755) G H) (fun x : _303756 => @g0 _303755 H).
Axiom thm_GROUP_MONOMORPHISM_TRIVIAL : forall {_303778 _303779 : Type'}, forall G : hol_Group _303779, forall H : hol_Group _303778, (@group_monomorphism _303779 _303778 (@pair (hol_Group _303779) (hol_Group _303778) G H) (fun x : _303779 => @g0 _303778 H)) = (@trivial_group _303779 G).
Axiom thm_GROUP_EPIMORPHISM_TRIVIAL : forall {_303824 _303825 : Type'}, forall G : hol_Group _303825, forall H : hol_Group _303824, (@group_epimorphism _303825 _303824 (@pair (hol_Group _303825) (hol_Group _303824) G H) (fun x : _303825 => @g0 _303824 H)) = (@trivial_group _303824 H).
Axiom thm_GROUP_ISOMORPHISM_TRIVIAL : forall {_303849 _303850 : Type'}, forall G : hol_Group _303850, forall H : hol_Group _303849, (@group_isomorphism _303850 _303849 (@pair (hol_Group _303850) (hol_Group _303849) G H) (fun x : _303850 => @g0 _303849 H)) = ((@trivial_group _303850 G) /\ (@trivial_group _303849 H)).
Axiom thm_group_element_order : forall {A : Type'}, forall x : A, forall G : hol_Group A, (@group_element_order A G x) = (@ε nat (fun d : nat => forall n : nat, ((@group_pow A G x n) = (@g0 A G)) = (num_divides d n))).
Axiom thm_GROUP_POW_EQ_ID : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : nat, (@IN A x (@gcar A G)) -> ((@group_pow A G x n) = (@g0 A G)) = (num_divides (@group_element_order A G x) n).
Axiom thm_GROUP_POW_EQ_ID_DIVISOR : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : nat, forall n : nat, ((@IN A x (@gcar A G)) /\ (((@group_pow A G x m) = (@g0 A G)) /\ (num_divides m n))) -> (@group_pow A G x n) = (@g0 A G).
Axiom thm_GROUP_POW_ELEMENT_ORDER : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> (@group_pow A G x (@group_element_order A G x)) = (@g0 A G).
Axiom thm_GROUP_ZPOW_EQ_ID : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : int, (@IN A x (@gcar A G)) -> ((@group_zpow A G x n) = (@g0 A G)) = (dividez (int_of_nat (@group_element_order A G x)) n).
Axiom thm_GROUP_ZPOW_EQ_ID_DIVISOR : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : int, forall n : int, ((@IN A x (@gcar A G)) /\ (((@group_zpow A G x m) = (@g0 A G)) /\ (dividez m n))) -> (@group_zpow A G x n) = (@g0 A G).
Axiom thm_GROUP_ZPOW_EQ_ALT : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : int, forall n : int, (@IN A x (@gcar A G)) -> ((@group_zpow A G x m) = (@group_zpow A G x n)) = (dividez (int_of_nat (@group_element_order A G x)) (subz n m)).
Axiom thm_GROUP_ZPOW_EQ : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : int, forall n : int, (@IN A x (@gcar A G)) -> ((@group_zpow A G x m) = (@group_zpow A G x n)) = (@eq2 int m n (int_mod (int_of_nat (@group_element_order A G x)))).
Axiom thm_GROUP_POW_EQ : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : nat, forall n : nat, (@IN A x (@gcar A G)) -> ((@group_pow A G x m) = (@group_pow A G x n)) = (@eq2 nat m n (num_mod (@group_element_order A G x))).
Axiom thm_GROUP_ZPOW_REM_ELEMENT_ORDER : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : int, (@IN A x (@gcar A G)) -> (@group_zpow A G x (modz n (int_of_nat (@group_element_order A G x)))) = (@group_zpow A G x n).
Axiom thm_GROUP_POW_MOD_ELEMENT_ORDER : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : nat, (@IN A x (@gcar A G)) -> (@group_pow A G x (modn n (@group_element_order A G x))) = (@group_pow A G x n).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_0 : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> ((@group_element_order A G x) = (NUMERAL O)) = (forall n : nat, (~ (n = (NUMERAL O))) -> ~ ((@group_pow A G x n) = (@g0 A G))).
Axiom thm_GROUP_ELEMENT_ORDER_UNIQUE : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall d : nat, (@IN A x (@gcar A G)) -> ((@group_element_order A G x) = d) = (forall n : nat, ((@group_pow A G x n) = (@g0 A G)) = (num_divides d n)).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_1 : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> ((@group_element_order A G x) = (NUMERAL (BIT1 O))) = (x = (@g0 A G)).
Axiom thm_GROUP_ELEMENT_ORDER_UNIQUE_PRIME : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall p : nat, ((@IN A x (@gcar A G)) /\ (prime p)) -> ((@group_element_order A G x) = p) = ((~ (x = (@g0 A G))) /\ ((@group_pow A G x p) = (@g0 A G))).
Axiom thm_GROUP_ELEMENT_ORDER_ID : forall {A : Type'}, forall G : hol_Group A, (@group_element_order A G (@g0 A G)) = (NUMERAL (BIT1 O)).
Axiom thm_GROUP_ELEMENT_ORDER_INV : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> (@group_element_order A G (@ginv A G x)) = (@group_element_order A G x).
Axiom thm_GROUP_POW_GCD_EQ_ID : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : nat, forall n : nat, (@IN A x (@gcar A G)) -> ((@group_pow A G x (num_gcd (@pair nat nat m n))) = (@g0 A G)) = (((@group_pow A G x m) = (@g0 A G)) /\ ((@group_pow A G x n) = (@g0 A G))).
Axiom thm_GROUP_POW_COPRIME_EQ_ID : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall m : nat, forall n : nat, ((@IN A x (@gcar A G)) /\ (num_coprime (@pair nat nat m n))) -> (((@group_pow A G x m) = (@g0 A G)) /\ ((@group_pow A G x n) = (@g0 A G))) = (x = (@g0 A G)).
Axiom thm_FINITE_GROUP_ELEMENT_ORDER_NONZERO : forall {A : Type'}, forall G : hol_Group A, forall x : A, ((@finite_set A (@gcar A G)) /\ (@IN A x (@gcar A G))) -> ~ ((@group_element_order A G x) = (NUMERAL O)).
Axiom thm_GROUP_ELEMENT_ORDER_POW : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall k : nat, ((@IN A x (@gcar A G)) /\ ((~ (k = (NUMERAL O))) /\ (num_divides k (@group_element_order A G x)))) -> (@group_element_order A G (@group_pow A G x k)) = (divn (@group_element_order A G x) k).
Axiom thm_GROUP_ELEMENT_ORDER_POW_GEN : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall k : nat, (@IN A x (@gcar A G)) -> (@group_element_order A G (@group_pow A G x k)) = (@COND nat (k = (NUMERAL O)) (NUMERAL (BIT1 O)) (divn (@group_element_order A G x) (num_gcd (@pair nat nat (@group_element_order A G x) k)))).
Axiom thm_GROUP_ELEMENT_ORDER_MUL_DIVIDES_GEN : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, forall n : nat, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (((@gop A G x y) = (@gop A G y x)) /\ ((num_divides (@group_element_order A G x) n) /\ (num_divides (@group_element_order A G y) n))))) -> num_divides (@group_element_order A G (@gop A G x y)) n.
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_MUL_DIVIDES_GEN : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, forall n : nat, ((@abelian_group A G) /\ ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((num_divides (@group_element_order A G x) n) /\ (num_divides (@group_element_order A G y) n))))) -> num_divides (@group_element_order A G (@gop A G x y)) n.
Axiom thm_GROUP_ELEMENT_ORDER_MUL_DIVIDES_LCM : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((@gop A G x y) = (@gop A G y x)))) -> num_divides (@group_element_order A G (@gop A G x y)) (num_lcm (@pair nat nat (@group_element_order A G x) (@group_element_order A G y))).
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_MUL_DIVIDES_LCM : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@abelian_group A G) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> num_divides (@group_element_order A G (@gop A G x y)) (num_lcm (@pair nat nat (@group_element_order A G x) (@group_element_order A G y))).
Axiom thm_GROUP_ELEMENT_ORDER_HOMOMORPHIC_IMAGE : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall f : A -> B, forall x : A, ((@group_homomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) /\ (@IN A x (@gcar A G))) -> num_divides (@group_element_order B H (f x)) (@group_element_order A G x).
Axiom thm_GROUP_ELEMENT_ORDER_MONOMORPHIC_IMAGE : forall {A B : Type'}, forall f : A -> B, forall G : hol_Group A, forall H : hol_Group B, forall x : A, ((@group_monomorphism A B (@pair (hol_Group A) (hol_Group B) G H) f) /\ (@IN A x (@gcar A G))) -> (@group_element_order B H (f x)) = (@group_element_order A G x).
Axiom thm_ISOMORPHIC_GROUP_TORSION : forall {A B : Type'}, forall P : nat -> Prop, forall G : hol_Group A, forall H : hol_Group B, (@isomorphic_group A B G H) -> (forall x : A, (@IN A x (@gcar A G)) -> P (@group_element_order A G x)) = (forall y : B, (@IN B y (@gcar B H)) -> P (@group_element_order B H y)).
Axiom thm_GROUP_ELEMENT_ORDER_CONJUGATION : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> (@group_element_order A G (@group_conjugation A G x y)) = (@group_element_order A G y).
Axiom thm_GROUP_ELEMENT_ORDER_MUL_DIVIDES : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((@gop A G x y) = (@gop A G y x)))) -> num_divides (@group_element_order A G (@gop A G x y)) (muln (@group_element_order A G x) (@group_element_order A G y)).
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_MUL_DIVIDES : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@abelian_group A G) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> num_divides (@group_element_order A G (@gop A G x y)) (muln (@group_element_order A G x) (@group_element_order A G y)).
Axiom thm_GROUP_POW_MUL_EQ_ID_SYM : forall {A : Type'}, forall G : hol_Group A, forall n : nat, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> ((@group_pow A G (@gop A G x y) n) = (@g0 A G)) = ((@group_pow A G (@gop A G y x) n) = (@g0 A G)).
Axiom thm_GROUP_ELEMENT_ORDER_MUL_SYM : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G))) -> (@group_element_order A G (@gop A G x y)) = (@group_element_order A G (@gop A G y x)).
Axiom thm_GROUP_ELEMENT_ORDER_UNIQUE_ALT : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : nat, ((@IN A x (@gcar A G)) /\ (~ (n = (NUMERAL O)))) -> ((@group_element_order A G x) = n) = (((@group_pow A G x n) = (@g0 A G)) /\ (forall m : nat, ((ltn (NUMERAL O) m) /\ (ltn m n)) -> ~ ((@group_pow A G x m) = (@g0 A G)))).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_2 : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> ((@group_element_order A G x) = (NUMERAL (BIT0 (BIT1 O)))) = ((~ (x = (@g0 A G))) /\ ((@group_pow A G x (NUMERAL (BIT0 (BIT1 O)))) = (@g0 A G))).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_2_ALT : forall {A : Type'}, forall G : hol_Group A, forall x : A, (@IN A x (@gcar A G)) -> ((@group_element_order A G x) = (NUMERAL (BIT0 (BIT1 O)))) = ((~ (x = (@g0 A G))) /\ ((@ginv A G x) = x)).
Axiom thm_GROUP_ELEMENT_ORDER_POW_DIVIDES : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall n : nat, (@IN A x (@gcar A G)) -> num_divides (@group_element_order A G (@group_pow A G x n)) (@group_element_order A G x).
Axiom thm_GROUP_ELEMENT_ORDER_MUL_EQ : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (((@gop A G x y) = (@gop A G y x)) /\ (num_coprime (@pair nat nat (@group_element_order A G x) (@group_element_order A G y)))))) -> (@group_element_order A G (@gop A G x y)) = (muln (@group_element_order A G x) (@group_element_order A G y)).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_MUL_GEN : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall k : nat, forall n : nat, ((@IN A x (@gcar A G)) /\ (~ (k = (NUMERAL O)))) -> ((@group_element_order A G x) = (muln k n)) = ((num_divides k (@group_element_order A G x)) /\ ((@group_element_order A G (@group_pow A G x k)) = n)).
Axiom thm_GROUP_ELEMENT_ORDER_EQ_MUL : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall k : nat, forall n : nat, ((@IN A x (@gcar A G)) /\ ((~ (k = (NUMERAL O))) /\ (num_divides k n))) -> ((@group_element_order A G x) = (muln k n)) = ((@group_element_order A G (@group_pow A G x k)) = n).
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_MUL_EQ : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@abelian_group A G) /\ ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ (num_coprime (@pair nat nat (@group_element_order A G x) (@group_element_order A G y)))))) -> (@group_element_order A G (@gop A G x y)) = (muln (@group_element_order A G x) (@group_element_order A G y)).
Axiom thm_GROUP_ELEMENT_ORDER_LCM_EXISTS : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@IN A x (@gcar A G)) /\ ((@IN A y (@gcar A G)) /\ ((@gop A G x y) = (@gop A G y x)))) -> exists z : A, (@IN A z (@gcar A G)) /\ ((@group_element_order A G z) = (num_lcm (@pair nat nat (@group_element_order A G x) (@group_element_order A G y)))).
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_LCM_EXISTS : forall {A : Type'}, forall G : hol_Group A, forall x : A, forall y : A, ((@abelian_group A G) /\ ((@IN A x (@gcar A G)) /\ (@IN A y (@gcar A G)))) -> exists z : A, (@IN A z (@gcar A G)) /\ ((@group_element_order A G z) = (num_lcm (@pair nat nat (@group_element_order A G x) (@group_element_order A G y)))).
Axiom thm_ABELIAN_GROUP_ORDER_DIVIDES_MAXIMAL : forall {A : Type'}, forall G : hol_Group A, ((@abelian_group A G) /\ (@finite_set A (@gcar A G))) -> exists x : A, (@IN A x (@gcar A G)) /\ (forall y : A, (@IN A y (@gcar A G)) -> num_divides (@group_element_order A G y) (@group_element_order A G x)).
Axiom thm_ABELIAN_GROUP_ELEMENT_ORDER_DIVIDES_MAXIMAL_ALT : forall {A : Type'}, forall G : hol_Group A, ((@abelian_group A G) /\ (@finite_set A (@gcar A G))) -> exists x : A, (@IN A x (@gcar A G)) /\ (forall y : A, (@IN A y (@gcar A G)) -> (@group_pow A G y (@group_element_order A G x)) = (@g0 A G)).
Axiom thm_GROUP_ELEMENT_ORDER_SUBGROUP_GENERATED : forall {A : Type'}, forall G : hol_Group A, forall h : A -> Prop, forall x : A, (@group_element_order A (@subgroup_generated A G h) x) = (@group_element_order A G x).
Axiom thm_GROUP_ELEMENT_ORDER_PROD_GROUP : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall x : A, forall y : B, ((@IN A x (@gcar A G)) /\ (@IN B y (@gcar B H))) -> (@group_element_order (prod A B) (@prod_group A B G H) (@pair A B x y)) = (num_lcm (@pair nat nat (@group_element_order A G x) (@group_element_order B H y))).
Axiom thm_GROUP_ELEMENT_ORDER_PROD_GROUP_ALT : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, forall z : prod A B, (@IN (prod A B) z (@gcar (prod A B) (@prod_group A B G H))) -> (@group_element_order (prod A B) (@prod_group A B G H) z) = (num_lcm (@pair nat nat (@group_element_order A G (@fst A B z)) (@group_element_order B H (@snd A B z)))).
Axiom thm_GROUP_ELEMENT_ORDER_SUM_GROUP : forall {A K : Type'}, forall G : K -> hol_Group A, forall k : K -> Prop, forall x : K -> A, (@IN (K -> A) x (@gcar (K -> A) (@sum_group A K k G))) -> (@group_element_order (K -> A) (@sum_group A K k G) x) = (@iterate K nat (fun m : nat => fun n : nat => num_lcm (@pair nat nat m n)) k (fun i : K => @group_element_order A (G i) (x i))).
