Axiom thm_EXTREMELY_SHORT_EXACT_SEQUENCE : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@trivial_group A A') /\ (@trivial_group C C'))) -> @trivial_group B B'.
Axiom thm_GROUP_EXACTNESS_EPIMORPHISM_EQ_TRIVIALITY : forall {A B C D : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ (@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h))) -> (@group_epimorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) = (@trivial_homomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g).
Axiom thm_GROUP_EXACTNESS_MONOMORPHISM_EQ_TRIVIALITY : forall {A B C D : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ (@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h))) -> (@group_monomorphism C D (@pair (hol_Group C) (hol_Group D) C' D') h) = (@trivial_homomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g).
Axiom thm_VERY_SHORT_EXACT_SEQUENCE : forall {A B C D : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ ((@trivial_group A A') /\ (@trivial_group D D')))) -> @group_isomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g.
Axiom thm_GROUP_EXACTNESS_EQ_TRIVIALITY : forall {A B C D E : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall k : D -> E, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall E' : hol_Group E, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ (@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h k)))) -> (@trivial_group C C') = ((@group_epimorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ (@group_monomorphism D E (@pair (hol_Group D) (hol_Group E) D' E') k)).
Axiom thm_GROUP_EXACTNESS_IMP_TRIVIALITY : forall {A B C D E : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall k : D -> E, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall E' : hol_Group E, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h k)) /\ ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ (@group_isomorphism D E (@pair (hol_Group D) (hol_Group E) D' E') k))))) -> @trivial_group C C'.
Axiom thm_GROUP_EXACTNESS_ISOMORPHISM_EQ_TRIVIALITY : forall {A B C D E G : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall j : D -> E, forall k : E -> G, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall E' : hol_Group E, forall G' : hol_Group G, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h j)) /\ (@group_exactness D E G (@pair (hol_Group D) (prod (hol_Group E) (hol_Group G)) D' (@pair (hol_Group E) (hol_Group G) E' G')) (@pair (D -> E) (E -> G) j k))))) -> (@group_isomorphism C D (@pair (hol_Group C) (hol_Group D) C' D') h) = ((@trivial_homomorphism B C (@pair (hol_Group B) (hol_Group C) B' C') g) /\ (@trivial_homomorphism D E (@pair (hol_Group D) (hol_Group E) D' E') j)).
Axiom thm_GROUP_EXACTNESS_ISOMORPHISM_EQ_MONO_EPI : forall {A B C D E G : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall j : D -> E, forall k : E -> G, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall E' : hol_Group E, forall G' : hol_Group G, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h j)) /\ (@group_exactness D E G (@pair (hol_Group D) (prod (hol_Group E) (hol_Group G)) D' (@pair (hol_Group E) (hol_Group G) E' G')) (@pair (D -> E) (E -> G) j k))))) -> (@group_isomorphism C D (@pair (hol_Group C) (hol_Group D) C' D') h) = ((@group_epimorphism A B (@pair (hol_Group A) (hol_Group B) A' B') f) /\ (@group_monomorphism E G (@pair (hol_Group E) (hol_Group G) E' G') k)).
Axiom thm_SHORT_EXACT_SEQUENCE_NORMAL_SUBGROUP : forall {A : Type'}, forall G : hol_Group A, forall n : A -> Prop, (@normal_subgroup_of A n G) -> @short_exact_sequence A A (A -> Prop) (@pair (hol_Group A) (prod (hol_Group A) (hol_Group (A -> Prop))) (@subgroup_generated A G n) (@pair (hol_Group A) (hol_Group (A -> Prop)) G (@quotient_group A G n))) (@pair (A -> A) (A -> A -> Prop) (fun x : A => x) (@right_coset A G n)).
Axiom thm_SHORT_EXACT_SEQUENCE_PROD_GROUP : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, @short_exact_sequence A (prod A B) B (@pair (hol_Group A) (prod (hol_Group (prod A B)) (hol_Group B)) G (@pair (hol_Group (prod A B)) (hol_Group B) (@prod_group A B G H) H)) (@pair (A -> prod A B) ((prod A B) -> B) (fun x : A => @pair A B x (@g0 B H)) (@snd A B)).
Axiom thm_SHORT_EXACT_SEQUENCE_PROD_GROUP_ALT : forall {A B : Type'}, forall G : hol_Group A, forall H : hol_Group B, @short_exact_sequence B (prod A B) A (@pair (hol_Group B) (prod (hol_Group (prod A B)) (hol_Group A)) H (@pair (hol_Group (prod A B)) (hol_Group A) (@prod_group A B G H) G)) (@pair (B -> prod A B) ((prod A B) -> A) (fun x : B => @pair A B (@g0 A G) x) (@fst A B)).
Axiom thm_EXACT_SEQUENCE_SUM_LEMMA : forall {A B C D X : Type'}, forall f : X -> C, forall g : X -> D, forall h : A -> C, forall i : A -> X, forall j : B -> X, forall k : B -> D, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall X' : hol_Group X, ((@abelian_group X X') /\ ((@group_isomorphism A C (@pair (hol_Group A) (hol_Group C) A' C') h) /\ ((@group_isomorphism B D (@pair (hol_Group B) (hol_Group D) B' D') k) /\ ((@group_exactness A X D (@pair (hol_Group A) (prod (hol_Group X) (hol_Group D)) A' (@pair (hol_Group X) (hol_Group D) X' D')) (@pair (A -> X) (X -> D) i g)) /\ ((@group_exactness B X C (@pair (hol_Group B) (prod (hol_Group X) (hol_Group C)) B' (@pair (hol_Group X) (hol_Group C) X' C')) (@pair (B -> X) (X -> C) j f)) /\ ((forall x : A, (@IN A x (@gcar A A')) -> (f (i x)) = (h x)) /\ (forall x : B, (@IN B x (@gcar B B')) -> (g (j x)) = (k x)))))))) -> (@group_isomorphism (prod A B) X (@pair (hol_Group (prod A B)) (hol_Group X) (@prod_group A B A' B') X') (@ε ((prod A B) -> X) (fun f' : (prod A B) -> X => forall x : A, forall y : B, @eq X (f' (@pair A B x y)) (@gop X X' (i x) (j y))))) /\ (@group_isomorphism X (prod C D) (@pair (hol_Group X) (hol_Group (prod C D)) X' (@prod_group C D C' D')) (fun z : X => @pair C D (f z) (g z))).
Axiom thm_SHORT_EXACT_SEQUENCE_QUOTIENT : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, (@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) -> (@isomorphic_group B A (@subgroup_generated B B' (@group_image A B (@pair (hol_Group A) (hol_Group B) A' B') f)) A') /\ (@isomorphic_group (B -> Prop) C (@quotient_group B B' (@group_image A B (@pair (hol_Group A) (hol_Group B) A' B') f)) C').
Axiom thm_TRIVIAL_GROUPS_IMP_SHORT_EXACT_SEQUENCE : forall {A B C D E : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall k : D -> E, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall E' : hol_Group E, ((@trivial_group A A') /\ ((@trivial_group E E') /\ ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ (@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h k)))))) -> @short_exact_sequence B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h).
Axiom thm_SHORT_EXACT_SEQUENCE_TRIVIAL_GROUPS : forall {A B C D E : Type'}, forall g : B -> C, forall h : C -> D, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, (@short_exact_sequence B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) = (exists f : A -> B, exists k : D -> E, exists A' : hol_Group A, exists E' : hol_Group E, (@trivial_group A A') /\ ((@trivial_group E E') /\ ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B' (@pair (hol_Group C) (hol_Group D) C' D')) (@pair (B -> C) (C -> D) g h)) /\ (@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C' (@pair (hol_Group D) (hol_Group E) D' E')) (@pair (C -> D) (D -> E) h k)))))).
Axiom thm_SPLITTING_SUBLEMMA_GEN : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall h : B -> Prop, forall k : B -> Prop, ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ (((@group_image A B (@pair (hol_Group A) (hol_Group B) A' B') f) = h) /\ ((@subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ ((@group_setmul B B' h k) = (@gcar B B')))))) -> @group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) (@subgroup_generated C C' (@group_image B C (@pair (hol_Group B) (hol_Group C) B' C') g))) g.
Axiom thm_SPLITTING_SUBLEMMA : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall h : B -> Prop, forall k : B -> Prop, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ (((@group_image A B (@pair (hol_Group A) (hol_Group B) A' B') f) = h) /\ ((@subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ ((@group_setmul B B' h k) = (@gcar B B')))))) -> (@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' (@subgroup_generated B B' h)) f) /\ (@group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) C') g).
Axiom thm_SPLITTING_LEMMA_LEFT_GEN : forall {A B C : Type'}, forall f : A -> B, forall f' : B -> A, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_homomorphism B A (@pair (hol_Group B) (hol_Group A) B' A') f') /\ (@group_isomorphism A A (@pair (hol_Group A) (hol_Group A) A' A') (@o A B A f' f)))) -> exists h : B -> Prop, exists k : B -> Prop, (@normal_subgroup_of B h B') /\ ((@normal_subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ (((@group_setmul B B' h k) = (@gcar B B')) /\ ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' (@subgroup_generated B B' h)) f) /\ (@group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) C') g))))).
Axiom thm_SPLITTING_LEMMA_LEFT : forall {A B C : Type'}, forall f : A -> B, forall f' : B -> A, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_homomorphism B A (@pair (hol_Group B) (hol_Group A) B' A') f') /\ (forall x : A, (@IN A x (@gcar A A')) -> (f' (f x)) = x))) -> exists h : B -> Prop, exists k : B -> Prop, (@normal_subgroup_of B h B') /\ ((@normal_subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ (((@group_setmul B B' h k) = (@gcar B B')) /\ ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' (@subgroup_generated B B' h)) f) /\ (@group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) C') g))))).
Axiom thm_SPLITTING_LEMMA_LEFT_PROD_GROUP : forall {A B C : Type'}, forall f : A -> B, forall f' : B -> A, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@abelian_group B B') /\ ((@group_homomorphism B A (@pair (hol_Group B) (hol_Group A) B' A') f') /\ (forall x : A, (@IN A x (@gcar A A')) -> (f' (f x)) = x)))) -> @isomorphic_group B (prod A C) B' (@prod_group A C A' C').
Axiom thm_SPLITTING_LEMMA_RIGHT_GEN : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall g' : C -> B, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_homomorphism C B (@pair (hol_Group C) (hol_Group B) C' B') g') /\ (@group_isomorphism C C (@pair (hol_Group C) (hol_Group C) C' C') (@o C B C g g')))) -> exists h : B -> Prop, exists k : B -> Prop, (@normal_subgroup_of B h B') /\ ((@subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ (((@group_setmul B B' h k) = (@gcar B B')) /\ ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' (@subgroup_generated B B' h)) f) /\ (@group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) C') g))))).
Axiom thm_SPLITTING_LEMMA_RIGHT : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall g' : C -> B, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_homomorphism C B (@pair (hol_Group C) (hol_Group B) C' B') g') /\ (forall z : C, (@IN C z (@gcar C C')) -> (g (g' z)) = z))) -> exists h : B -> Prop, exists k : B -> Prop, (@normal_subgroup_of B h B') /\ ((@subgroup_of B k B') /\ ((@subset B (@setI B h k) (@INSERT B (@g0 B B') (@set0 B))) /\ (((@group_setmul B B' h k) = (@gcar B B')) /\ ((@group_isomorphism A B (@pair (hol_Group A) (hol_Group B) A' (@subgroup_generated B B' h)) f) /\ (@group_isomorphism B C (@pair (hol_Group B) (hol_Group C) (@subgroup_generated B B' k) C') g))))).
Axiom thm_SPLITTING_LEMMA_RIGHT_PROD_GROUP : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall g' : C -> B, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@abelian_group B B') /\ ((@group_homomorphism C B (@pair (hol_Group C) (hol_Group B) C' B') g') /\ (forall z : C, (@IN C z (@gcar C C')) -> (g (g' z)) = z)))) -> @isomorphic_group B (prod A C) B' (@prod_group A C A' C').
Axiom thm_SPLITTING_LEMMA_FREE_ABELIAN_GROUP : forall {A B C D : Type'}, forall f : A -> B, forall g : B -> C, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall s : D -> Prop, ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A' (@pair (hol_Group B) (hol_Group C) B' C')) (@pair (A -> B) (B -> C) f g)) /\ ((@abelian_group B B') /\ (@isomorphic_group C (frag D) C' (@free_abelian_group D s)))) -> @isomorphic_group B (prod A C) B' (@prod_group A C A' C').
Axiom thm_FOUR_LEMMA_MONO : forall {A A' B B' C C' D D' : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall f' : A' -> B', forall g' : B' -> C', forall h' : C' -> D', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall d : D -> D', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall D'' : hol_Group D, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', forall D''' : hol_Group D', ((@group_epimorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_monomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_homomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@group_monomorphism D D' (@pair (hol_Group D) (hol_Group D') D'' D''') d) /\ ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B'' (@pair (hol_Group C) (hol_Group D) C'' D'')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((@group_exactness B' C' D' (@pair (hol_Group B') (prod (hol_Group C') (hol_Group D')) B''' (@pair (hol_Group C') (hol_Group D') C''' D''')) (@pair (B' -> C') (C' -> D') g' h')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ ((forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))) /\ (forall z : C, (@IN C z (@gcar C C'')) -> (h' (c z)) = (d (h z))))))))))))) -> @group_monomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c.
Axiom thm_FOUR_LEMMA_EPI : forall {A A' B B' C C' D D' : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall f' : A' -> B', forall g' : B' -> C', forall h' : C' -> D', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall d : D -> D', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall D'' : hol_Group D, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', forall D''' : hol_Group D', ((@group_epimorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_homomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_epimorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@group_monomorphism D D' (@pair (hol_Group D) (hol_Group D') D'' D''') d) /\ ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B'' (@pair (hol_Group C) (hol_Group D) C'' D'')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((@group_exactness B' C' D' (@pair (hol_Group B') (prod (hol_Group C') (hol_Group D')) B''' (@pair (hol_Group C') (hol_Group D') C''' D''')) (@pair (B' -> C') (C' -> D') g' h')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ ((forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))) /\ (forall z : C, (@IN C z (@gcar C C'')) -> (h' (c z)) = (d (h z))))))))))))) -> @group_epimorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b.
Axiom thm_FIVE_LEMMA : forall {A A' B B' C C' D D' E E' : Type'}, forall f : A -> B, forall g : B -> C, forall h : C -> D, forall k : D -> E, forall f' : A' -> B', forall g' : B' -> C', forall h' : C' -> D', forall k' : D' -> E', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall d : D -> D', forall e : E -> E', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall D'' : hol_Group D, forall E'' : hol_Group E, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', forall D''' : hol_Group D', forall E''' : hol_Group E', ((@group_epimorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_isomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_homomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@group_isomorphism D D' (@pair (hol_Group D) (hol_Group D') D'' D''') d) /\ ((@group_monomorphism E E' (@pair (hol_Group E) (hol_Group E') E'' E''') e) /\ ((@group_exactness A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@group_exactness B C D (@pair (hol_Group B) (prod (hol_Group C) (hol_Group D)) B'' (@pair (hol_Group C) (hol_Group D) C'' D'')) (@pair (B -> C) (C -> D) g h)) /\ ((@group_exactness C D E (@pair (hol_Group C) (prod (hol_Group D) (hol_Group E)) C'' (@pair (hol_Group D) (hol_Group E) D'' E'')) (@pair (C -> D) (D -> E) h k)) /\ ((@group_exactness A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((@group_exactness B' C' D' (@pair (hol_Group B') (prod (hol_Group C') (hol_Group D')) B''' (@pair (hol_Group C') (hol_Group D') C''' D''')) (@pair (B' -> C') (C' -> D') g' h')) /\ ((@group_exactness C' D' E' (@pair (hol_Group C') (prod (hol_Group D') (hol_Group E')) C''' (@pair (hol_Group D') (hol_Group E') D''' E''')) (@pair (C' -> D') (D' -> E') h' k')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ ((forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))) /\ ((forall z : C, (@IN C z (@gcar C C'')) -> (h' (c z)) = (d (h z))) /\ (forall w : D, (@IN D w (@gcar D D'')) -> (k' (d w)) = (e (k w))))))))))))))))) -> @group_isomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c.
Axiom thm_SHORT_FIVE_LEMMA_MONO : forall {A A' B B' C C' : Type'}, forall f : A -> B, forall g : B -> C, forall f' : A' -> B', forall g' : B' -> C', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', ((@group_monomorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_homomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_monomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@short_exact_sequence A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ (forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))))))))) -> @group_monomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b.
Axiom thm_SHORT_FIVE_LEMMA_EPI : forall {A A' B B' C C' : Type'}, forall f : A -> B, forall g : B -> C, forall f' : A' -> B', forall g' : B' -> C', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', ((@group_epimorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_homomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_epimorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@short_exact_sequence A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ (forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))))))))) -> @group_epimorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b.
Axiom thm_SHORT_FIVE_LEMMA : forall {A A' B B' C C' : Type'}, forall f : A -> B, forall g : B -> C, forall f' : A' -> B', forall g' : B' -> C', forall a : A -> A', forall b : B -> B', forall c : C -> C', forall A'' : hol_Group A, forall B'' : hol_Group B, forall C'' : hol_Group C, forall A''' : hol_Group A', forall B''' : hol_Group B', forall C''' : hol_Group C', ((@group_isomorphism A A' (@pair (hol_Group A) (hol_Group A') A'' A''') a) /\ ((@group_homomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b) /\ ((@group_isomorphism C C' (@pair (hol_Group C) (hol_Group C') C'' C''') c) /\ ((@short_exact_sequence A B C (@pair (hol_Group A) (prod (hol_Group B) (hol_Group C)) A'' (@pair (hol_Group B) (hol_Group C) B'' C'')) (@pair (A -> B) (B -> C) f g)) /\ ((@short_exact_sequence A' B' C' (@pair (hol_Group A') (prod (hol_Group B') (hol_Group C')) A''' (@pair (hol_Group B') (hol_Group C') B''' C''')) (@pair (A' -> B') (B' -> C') f' g')) /\ ((forall x : A, (@IN A x (@gcar A A'')) -> (f' (a x)) = (b (f x))) /\ (forall y : B, (@IN B y (@gcar B B'')) -> (g' (b y)) = (c (g y))))))))) -> @group_isomorphism B B' (@pair (hol_Group B) (hol_Group B') B'' B''') b.
Axiom thm_EXACT_SEQUENCE_HEXAGON_LEMMA : forall {A B C D W X Y : Type'}, forall f : X -> C, forall g : X -> D, forall h : A -> C, forall h' : C -> A, forall i : A -> X, forall j : B -> X, forall k : B -> D, forall k' : D -> B, forall a : A -> Y, forall b : B -> Y, forall c : W -> C, forall d : W -> D, forall l : W -> X, forall m : X -> Y, forall A' : hol_Group A, forall B' : hol_Group B, forall C' : hol_Group C, forall D' : hol_Group D, forall W' : hol_Group W, forall X' : hol_Group X, forall Y' : hol_Group Y, ((@abelian_group X X') /\ ((@group_homomorphism A Y (@pair (hol_Group A) (hol_Group Y) A' Y') a) /\ ((@group_homomorphism B Y (@pair (hol_Group B) (hol_Group Y) B' Y') b) /\ ((@group_homomorphism W C (@pair (hol_Group W) (hol_Group C) W' C') c) /\ ((@group_homomorphism W D (@pair (hol_Group W) (hol_Group D) W' D') d) /\ ((@group_isomorphisms A C (@pair (hol_Group A) (hol_Group C) A' C') (@pair (A -> C) (C -> A) h h')) /\ ((@group_isomorphisms B D (@pair (hol_Group B) (hol_Group D) B' D') (@pair (B -> D) (D -> B) k k')) /\ ((@group_exactness A X D (@pair (hol_Group A) (prod (hol_Group X) (hol_Group D)) A' (@pair (hol_Group X) (hol_Group D) X' D')) (@pair (A -> X) (X -> D) i g)) /\ ((@group_exactness B X C (@pair (hol_Group B) (prod (hol_Group X) (hol_Group C)) B' (@pair (hol_Group X) (hol_Group C) X' C')) (@pair (B -> X) (X -> C) j f)) /\ ((@group_exactness W X Y (@pair (hol_Group W) (prod (hol_Group X) (hol_Group Y)) W' (@pair (hol_Group X) (hol_Group Y) X' Y')) (@pair (W -> X) (X -> Y) l m)) /\ ((forall x : W, (@IN W x (@gcar W W')) -> (f (l x)) = (c x)) /\ ((forall x : W, (@IN W x (@gcar W W')) -> (g (l x)) = (d x)) /\ ((forall x : A, (@IN A x (@gcar A A')) -> (f (i x)) = (h x)) /\ ((forall x : A, (@IN A x (@gcar A A')) -> (m (i x)) = (a x)) /\ ((forall x : B, (@IN B x (@gcar B B')) -> (g (j x)) = (k x)) /\ (forall x : B, (@IN B x (@gcar B B')) -> (m (j x)) = (b x))))))))))))))))) -> forall x : W, (@IN W x (@gcar W W')) -> (@ginv Y Y' (a (h' (c x)))) = (b (k' (d x))).
Axiom thm_matroid_set : forall {A : Type'}, (@mat_set A) = (fun m : Matroid A => @fst (A -> Prop) ((A -> Prop) -> A -> Prop) (@dest_matroid A m)).
Axiom thm_matroid_span : forall {A : Type'}, (@mat_span A) = (fun m : Matroid A => @snd (A -> Prop) ((A -> Prop) -> A -> Prop) (@dest_matroid A m)).
Axiom thm_MATROID_SPAN_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> @subset A (@mat_span A m s) (@mat_set A m).
Axiom thm_MATROID_SPAN_SUPERSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> @subset A s (@mat_span A m s).
Axiom thm_MATROID_SPAN_MONO : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s t) /\ (@subset A t (@mat_set A m))) -> @subset A (@mat_span A m s) (@mat_span A m t).
Axiom thm_MATROID_SPAN_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> (@mat_span A m (@mat_span A m s)) = (@mat_span A m s).
Axiom thm_MATROID_SPAN_FINITARY : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@subset A s (@mat_set A m)) /\ (@IN A x (@mat_span A m s))) -> exists s' : A -> Prop, (@finite_set A s') /\ ((@subset A s' s) /\ (@IN A x (@mat_span A m s'))).
Axiom thm_MATROID_SPAN_EXCHANGE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, forall y : A, ((@subset A s (@mat_set A m)) /\ ((@IN A x (@mat_set A m)) /\ ((@IN A y (@mat_span A m (@INSERT A x s))) /\ (~ (@IN A y (@mat_span A m s)))))) -> @IN A x (@mat_span A m (@INSERT A y s)).
Axiom thm_MATROID_SPAN_INC : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@subset A s (@mat_set A m)) /\ (@IN A x s)) -> @IN A x (@mat_span A m s).
Axiom thm_SUBSET_MATROID_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> (@subset A (@mat_span A m s) (@mat_span A m t)) = (@subset A s (@mat_span A m t)).
Axiom thm_MATROID_SPAN_MINIMAL : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A t (@mat_set A m)) /\ (@subset A s (@mat_span A m t))) -> @subset A (@mat_span A m s) (@mat_span A m t).
Axiom thm_MATROID_SPAN_SET : forall {A : Type'}, forall m : Matroid A, (@mat_span A m (@mat_set A m)) = (@mat_set A m).
Axiom thm_MATROID_SPAN_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> ((@mat_span A m s) = (@mat_span A m t)) = ((@subset A s (@mat_span A m t)) /\ (@subset A t (@mat_span A m s))).
Axiom thm_MATROID_SPAN_EQ_SET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> ((@mat_span A m s) = (@mat_set A m)) = (@subset A (@mat_set A m) (@mat_span A m s)).
Axiom thm_MATROID_SPAN_SUBSET_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s t) /\ (@subset A t (@mat_set A m))) -> ((@mat_span A m s) = (@mat_span A m t)) = (@subset A t (@mat_span A m s)).
Axiom thm_MATROID_SPAN_INTER_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> @subset A (@mat_span A m (@setI A s t)) (@setI A (@mat_span A m s) (@mat_span A m t)).
Axiom thm_MATROID_SPAN_UNION : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> (@mat_span A m (@setU A s t)) = (@mat_span A m (@setU A (@mat_span A m s) (@mat_span A m t))).
Axiom thm_MATROID_SPAN_UNION_LEFT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> (@mat_span A m (@setU A s t)) = (@mat_span A m (@setU A (@mat_span A m s) t)).
Axiom thm_MATROID_SPAN_UNION_RIGHT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> (@mat_span A m (@setU A s t)) = (@mat_span A m (@setU A s (@mat_span A m t))).
Axiom thm_MATROID_SPAN_UNION_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> @subset A (@setU A (@mat_span A m s) (@mat_span A m t)) (@mat_span A m (@setU A s t)).
Axiom thm_MATROID_SPAN_EXCHANGE_DELETE : forall {A : Type'}, forall m : Matroid A, forall a : A, forall b : A, forall s : A -> Prop, ((@subset A s (@mat_set A m)) /\ ((@IN A b (@mat_set A m)) /\ ((@IN A a (@mat_span A m s)) /\ (~ (@IN A a (@mat_span A m (@DELETE A s b))))))) -> @IN A b (@mat_span A m (@INSERT A a (@DELETE A s b))).
Axiom thm_MATROID_SPAN_UNION_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> ((@mat_span A m (@setU A s t)) = (@mat_span A m t)) = (@subset A s (@mat_span A m t)).
Axiom thm_MATROID_SPAN_INSERT_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@subset A s (@mat_set A m)) /\ (@IN A x (@mat_set A m))) -> ((@mat_span A m (@INSERT A x s)) = (@mat_span A m s)) = (@IN A x (@mat_span A m s)).
Axiom thm_MATROID_SPAN_DELETE_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@IN A x s) /\ (@subset A s (@mat_set A m))) -> ((@mat_span A m (@DELETE A s x)) = (@mat_span A m s)) = (@IN A x (@mat_span A m (@DELETE A s x))).
Axiom thm_MATROID_SPAN_TRANS : forall {A : Type'}, forall m : Matroid A, forall x : A, forall y : A, forall s : A -> Prop, ((@subset A s (@mat_set A m)) /\ ((@IN A x (@mat_span A m s)) /\ (@IN A y (@mat_span A m (@INSERT A x s))))) -> @IN A y (@mat_span A m s).
Axiom thm_MATROID_SPAN_FINITARY_GEN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall k : A -> Prop, ((@subset A s (@mat_set A m)) /\ ((@finite_set A k) /\ (@subset A k (@mat_span A m s)))) -> exists s' : A -> Prop, (@finite_set A s') /\ ((@subset A s' s) /\ (@subset A k (@mat_span A m s'))).
Axiom thm_MATROID_SPAN_FINITARY_MINIMAL : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@subset A s (@mat_set A m)) /\ (@IN A x (@mat_span A m s))) -> exists t : A -> Prop, (@finite_set A t) /\ ((@subset A t s) /\ ((@IN A x (@mat_span A m t)) /\ (forall t' : A -> Prop, (@proper A t' t) -> ~ (@IN A x (@mat_span A m t'))))).
Axiom thm_matroid_spanning : forall {A : Type'}, forall s : A -> Prop, forall m : Matroid A, (@matroid_spanning A m s) = ((@subset A s (@mat_set A m)) /\ ((@mat_span A m s) = (@mat_set A m))).
Axiom thm_matroid_independent : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_independent A m s) = ((@subset A s (@mat_set A m)) /\ (forall x : A, (@IN A x s) -> ~ (@IN A x (@mat_span A m (@DELETE A s x))))).
Axiom thm_matroid_basis : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_basis A m s) = ((@matroid_spanning A m s) /\ (@matroid_independent A m s)).
Axiom thm_MATROID_SPANNING_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_spanning A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_INDEPENDENT_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_independent A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_DEPENDENT_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_dependent A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_BASIS_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_basis A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_SPANNING_ALT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_spanning A m s) = ((@subset A s (@mat_set A m)) /\ (@subset A (@mat_set A m) (@mat_span A m s))).
Axiom thm_MATROID_SPANNING_SET : forall {A : Type'}, forall m : Matroid A, @matroid_spanning A m (@mat_set A m).
Axiom thm_MATROID_INDEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_independent A m s) = ((@subset A s (@mat_set A m)) /\ (~ (@matroid_dependent A m s))).
Axiom thm_MATROID_DEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_dependent A m s) = ((@subset A s (@mat_set A m)) /\ (exists x : A, (@IN A x s) /\ (@IN A x (@mat_span A m (@DELETE A s x))))).
Axiom thm_MATROID_INDEPENDENT_EMPTY : forall {A : Type'}, forall m : Matroid A, @matroid_independent A m (@set0 A).
Axiom thm_MATROID_INDEPENDENT_MONO : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m t) /\ (@subset A s t)) -> @matroid_independent A m s.
Axiom thm_MATROID_INDEPENDENT_FINITARY : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_independent A m s) = ((@subset A s (@mat_set A m)) /\ (forall t : A -> Prop, ((@finite_set A t) /\ (@subset A t s)) -> @matroid_independent A m t)).
Axiom thm_MATROID_DEPENDENT_FINITARY : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_dependent A m s) = ((@subset A s (@mat_set A m)) /\ (exists t : A -> Prop, (@finite_set A t) /\ ((@subset A t s) /\ (@matroid_dependent A m t)))).
Axiom thm_MATROID_INDEPENDENT_INSERT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall a : A, (@matroid_independent A m (@INSERT A a s)) = (@COND Prop (@IN A a s) (@matroid_independent A m s) ((@IN A a (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (~ (@IN A a (@mat_span A m s)))))).
Axiom thm_MATROID_SPAN_PSUBSET_INDEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@proper A s t) /\ (@matroid_independent A m t)) -> @proper A (@mat_span A m s) (@mat_span A m t).
Axiom thm_MATROID_SPAN_PSUBSET_EXPLICIT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@proper A s t) /\ (@matroid_independent A m t)) -> exists a : A, (@IN A a t) /\ (~ (@IN A a (@mat_span A m s))).
Axiom thm_MATROID_SPANNING_SUBSET_INDEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A t s) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t)))) -> s = t.
Axiom thm_MATROID_SPANNING_PSUBSET_INDEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ~ ((@proper A s t) /\ ((@matroid_spanning A m s) /\ (@matroid_independent A m t))).
Axiom thm_MATROID_MAXIMAL_INDEPENDENT_SUBSET_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s t) /\ ((@subset A t (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (forall s' : A -> Prop, ((@proper A s s') /\ (@subset A s' t)) -> ~ (@matroid_independent A m s'))))) -> (@mat_span A m s) = (@mat_span A m t).
Axiom thm_MATROID_BASIS_EQ_MAXIMAL_INDEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_basis A m s) = ((@matroid_independent A m s) /\ (forall s' : A -> Prop, (@proper A s s') -> ~ (@matroid_independent A m s'))).
Axiom thm_MATROID_BASIS_EQ_MINIMAL_SPANNING : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_basis A m s) = ((@matroid_spanning A m s) /\ (forall s' : A -> Prop, (@proper A s' s) -> ~ (@matroid_spanning A m s'))).
Axiom thm_MATROID_INDEPENDENT_CHAIN : forall {A : Type'}, forall m : Matroid A, forall c : (A -> Prop) -> Prop, ((forall s : A -> Prop, (@IN (A -> Prop) s c) -> @matroid_independent A m s) /\ (forall s : A -> Prop, forall t : A -> Prop, ((@IN (A -> Prop) s c) /\ (@IN (A -> Prop) t c)) -> (@subset A s t) \/ (@subset A t s))) -> @matroid_independent A m (@UNIONS A c).
Axiom thm_MATROID_SPAN_CHAIN : forall {A : Type'}, forall m : Matroid A, forall c : (A -> Prop) -> Prop, ((~ (c = (@set0 (A -> Prop)))) /\ ((forall s : A -> Prop, (@IN (A -> Prop) s c) -> @subset A s (@mat_set A m)) /\ (forall s : A -> Prop, forall t : A -> Prop, ((@IN (A -> Prop) s c) /\ (@IN (A -> Prop) t c)) -> (@subset A s t) \/ (@subset A t s)))) -> (@mat_span A m (@UNIONS A c)) = (@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1221 : A -> Prop => exists s : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_1221 (@IN (A -> Prop) s c) (@mat_span A m s)))).
Axiom thm_MATROID_INTERMEDIATE_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ ((@subset A t (@mat_set A m)) /\ (@subset A s (@mat_span A m t)))) -> exists b : A -> Prop, (@subset A s b) /\ ((@subset A b (@setU A s t)) /\ ((@matroid_independent A m b) /\ ((@mat_span A m b) = (@mat_span A m t)))).
Axiom thm_MATROID_INTERMEDIATE_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ (@matroid_spanning A m t)) -> exists b : A -> Prop, (@subset A s b) /\ ((@subset A b (@setU A s t)) /\ (@matroid_basis A m b)).
Axiom thm_MATROID_INDEPENDENT_EXTENDS_TO_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_independent A m s) -> exists b : A -> Prop, (@subset A s b) /\ (@matroid_basis A m b).
Axiom thm_MATROID_BASIS_EXISTS : forall {A : Type'}, forall m : Matroid A, exists b : A -> Prop, @matroid_basis A m b.
Axiom thm_MATROID_SPANNING_CONTAINS_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_spanning A m s) -> exists b : A -> Prop, (@subset A b s) /\ (@matroid_basis A m b).
Axiom thm_MATROID_SPAN_DEPENDENCE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall x : A, ((@IN A x (@mat_set A m)) /\ (@subset A s (@mat_set A m))) -> (@IN A x (@mat_span A m s)) = ((@IN A x s) \/ (exists t : A -> Prop, (@subset A t s) /\ ((@matroid_independent A m t) /\ (@matroid_dependent A m (@INSERT A x t))))).
Axiom thm_MATROID_STEINITZ_EXCHANGE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A t (@mat_set A m)) /\ ((@finite_set A s) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t))))) -> exists t' : A -> Prop, (@subset A t' t) /\ ((@HAS_SIZE A t' (@CARD A s)) /\ ((@mat_span A m (@setU A (@setD A t t') s)) = (@mat_span A m t))).
Axiom thm_MATROID_INDEPENDENT_CARD_LE_SPAN_FINITE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@finite_set A t) /\ ((@subset A t (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t))))) -> (@finite_set A s) /\ (leqn (@CARD A s) (@CARD A t)).
Axiom thm_MATROID_EQ_SPANS_FINITE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ ((@matroid_independent A m t) /\ ((@mat_span A m s) = (@mat_span A m t)))) -> (@finite_set A s) = (@finite_set A t).
Axiom thm_MATROID_EQ_SPANS_SIZE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, forall n : nat, ((@matroid_independent A m s) /\ ((@matroid_independent A m t) /\ ((@mat_span A m s) = (@mat_span A m t)))) -> (@HAS_SIZE A s n) = (@HAS_SIZE A t n).
Axiom thm_MATROID_BASES_FINITE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_basis A m s) /\ (@matroid_basis A m t)) -> (@finite_set A s) = (@finite_set A t).
Axiom thm_MATROID_BASES_SIZE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, forall n : nat, ((@matroid_basis A m s) /\ (@matroid_basis A m t)) -> (@HAS_SIZE A s n) = (@HAS_SIZE A t n).
Axiom thm_MATROID_INDEPENDENT_CARD_LE_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A t (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t)))) -> @le_c A A s t.
Axiom thm_MATROID_INDEPENDENT_CARD_LE_SPANNING : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ (@matroid_spanning A m t)) -> @le_c A A s t.
Axiom thm_MATROID_EQ_SPANS_CARD_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ ((@matroid_independent A m t) /\ ((@mat_span A m s) = (@mat_span A m t)))) -> @eq_c A A s t.
Axiom thm_MATROID_BASES_CARD_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_basis A m s) /\ (@matroid_basis A m t)) -> @eq_c A A s t.
Axiom thm_MATROID_INDEPENDENT_SPANNING_FINITE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_independent A m s) /\ ((@matroid_spanning A m t) /\ (@finite_set A t))) -> @finite_set A s.
Axiom thm_MATROID_DEPENDENT_FINITARY_MINIMAL : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_dependent A m s) -> exists t : A -> Prop, (@finite_set A t) /\ ((@subset A t s) /\ ((@matroid_dependent A m t) /\ (forall t' : A -> Prop, (@proper A t' t) -> @matroid_independent A m t'))).
Axiom thm_MATROID_MINIMALLY_DEPENDENT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (forall t : A -> Prop, (@proper A t s) -> @matroid_independent A m t) -> (@matroid_dependent A m s) = ((~ (s = (@set0 A))) /\ ((@subset A s (@mat_set A m)) /\ (forall a : A, (@IN A a s) -> @IN A a (@mat_span A m (@DELETE A s a))))).
Axiom thm_MATROID_MINIMALLY_DEPENDENT_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_dependent A m s) -> exists t : A -> Prop, (@finite_set A t) /\ ((@subset A t s) /\ ((@matroid_dependent A m t) /\ ((~ (t = (@set0 A))) /\ (forall a : A, (@IN A a t) -> @IN A a (@mat_span A m (@DELETE A t a)))))).
Axiom thm_matroid_subspace : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_subspace A m s) = ((@subset A s (@mat_set A m)) /\ ((@mat_span A m s) = s)).
Axiom thm_MATROID_SUBSPACE_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_subspace A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_SUBSPACE_SET : forall {A : Type'}, forall m : Matroid A, @matroid_subspace A m (@mat_set A m).
Axiom thm_MATROID_SUBSPACE_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> @matroid_subspace A m (@mat_span A m s).
Axiom thm_MATROID_SUBSPACE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_subspace A m s) = ((@subset A s (@mat_set A m)) /\ (@subset A (@mat_span A m s) s)).
Axiom thm_MATROID_SUBSPACE_INTERS : forall {A : Type'}, forall m : Matroid A, forall f : (A -> Prop) -> Prop, ((~ (f = (@set0 (A -> Prop)))) /\ (forall s : A -> Prop, (@IN (A -> Prop) s f) -> @matroid_subspace A m s)) -> @matroid_subspace A m (@INTERS A f).
Axiom thm_MATROID_SUBSPACE_INTER : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@matroid_subspace A m s) /\ (@matroid_subspace A m t)) -> @matroid_subspace A m (@setI A s t).
Axiom thm_MATROID_SPAN_INTER_SPANS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@mat_set A m)) /\ (@subset A t (@mat_set A m))) -> (@mat_span A m (@setI A (@mat_span A m s) (@mat_span A m t))) = (@setI A (@mat_span A m s) (@mat_span A m t)).
Axiom thm_MATROID_SUBSPACE_CHAIN : forall {A : Type'}, forall m : Matroid A, forall c : (A -> Prop) -> Prop, ((~ (c = (@set0 (A -> Prop)))) /\ ((forall s : A -> Prop, (@IN (A -> Prop) s c) -> @matroid_subspace A m s) /\ (forall s : A -> Prop, forall t : A -> Prop, ((@IN (A -> Prop) s c) /\ (@IN (A -> Prop) t c)) -> (@subset A s t) \/ (@subset A t s)))) -> @matroid_subspace A m (@UNIONS A c).
Axiom thm_MATROID_SPAN_SUBSPACE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall b : A -> Prop, ((@subset A b s) /\ ((@subset A s (@mat_span A m b)) /\ (@matroid_subspace A m s))) -> (@mat_span A m b) = s.
Axiom thm_MATROID_SPAN_EQ_SELF : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> ((@mat_span A m s) = s) = (@matroid_subspace A m s).
Axiom thm_MATROID_SPAN_OF_SUBSPACE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_subspace A m s) -> (@mat_span A m s) = s.
Axiom thm_MATROID_SPAN_SUBSET_SUBSPACE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s t) /\ (@matroid_subspace A m t)) -> @subset A (@mat_span A m s) t.
Axiom thm_submatroid : forall {A : Type'}, forall s : A -> Prop, forall m : Matroid A, (@submatroid A m s) = (@matroid A (@pair (A -> Prop) ((A -> Prop) -> A -> Prop) (@mat_span A m (@setI A (@mat_set A m) s)) (@mat_span A m))).
Axiom thm_SUBMATROID_GEN : forall {A : Type'}, (forall m : Matroid A, forall s : A -> Prop, (@mat_set A (@submatroid A m s)) = (@mat_span A m (@setI A (@mat_set A m) s))) /\ (forall m : Matroid A, forall s : A -> Prop, (@mat_span A (@submatroid A m s)) = (@mat_span A m)).
Axiom thm_SUBMATROID : forall {A : Type'}, (forall m : Matroid A, forall s : A -> Prop, (@matroid_subspace A m s) -> (@mat_set A (@submatroid A m s)) = s) /\ (forall m : Matroid A, forall s : A -> Prop, (@mat_span A (@submatroid A m s)) = (@mat_span A m)).
Axiom thm_SUBMATROID_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> (@submatroid A m (@mat_span A m s)) = (@submatroid A m s).
Axiom thm_SUBMATROID_SUBSET : forall {A : Type'}, (forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> (@mat_set A (@submatroid A m s)) = (@mat_span A m s)) /\ (forall m : Matroid A, forall s : A -> Prop, (@mat_span A (@submatroid A m s)) = (@mat_span A m)).
Axiom thm_SUBMATROID_SET : forall {A : Type'}, forall m : Matroid A, (@submatroid A m (@mat_set A m)) = m.
Axiom thm_MATROID_INDEPENDENT_SUBMATROID : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall b : A -> Prop, (@subset A s (@mat_set A m)) -> (@matroid_independent A (@submatroid A m s) b) = ((@subset A b (@mat_span A m s)) /\ (@matroid_independent A m b)).
Axiom thm_MATROID_SPANNING_SUBMATROID : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall b : A -> Prop, (@subset A s (@mat_set A m)) -> (@matroid_spanning A (@submatroid A m s) b) = ((@subset A b (@mat_span A m s)) /\ ((@mat_span A m b) = (@mat_span A m s))).
Axiom thm_MATROID_SPANNING_SUBMATROID_SELF : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> @matroid_spanning A (@submatroid A m s) s.
Axiom thm_MATROID_BASIS_SUBMATROID : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall b : A -> Prop, (@subset A s (@mat_set A m)) -> (@matroid_basis A (@submatroid A m s) b) = ((@subset A b (@mat_span A m s)) /\ ((@matroid_independent A m b) /\ ((@mat_span A m b) = (@mat_span A m s)))).
Axiom thm_MATROID_SUBSET_CONTAINS_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> exists b : A -> Prop, (@subset A b s) /\ ((@matroid_independent A m b) /\ ((@mat_span A m b) = (@mat_span A m s))).
Axiom thm_MATROID_STEINITZ_EXCHANGE_FINITE : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@finite_set A t) /\ ((@subset A t (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t))))) -> exists t' : A -> Prop, (@HAS_SIZE A t' (@CARD A t)) /\ ((@subset A s t') /\ ((@subset A t' (@setU A s t)) /\ ((@mat_span A m t') = (@mat_span A m t)))).
Axiom thm_MATROID_STEINITZ_EXCHANGE_ALT : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, forall t : A -> Prop, ((@finite_set A t) /\ ((@subset A t (@mat_set A m)) /\ ((@matroid_independent A m s) /\ (@subset A s (@mat_span A m t))))) -> exists t' : A -> Prop, (@subset A t' t) /\ (((addn (@CARD A t') (@CARD A s)) = (@CARD A t)) /\ ((@mat_span A m (@setU A s t')) = (@mat_span A m t))).
Axiom thm_MATROID_FINITE_DIM_IMP_SUBSET : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_finite_dim A m s) -> @subset A s (@mat_set A m).
Axiom thm_MATROID_FINITE_DIM_SET : forall {A : Type'}, forall m : Matroid A, (@matroid_finite_dim A m (@mat_set A m)) = (@matroid_finite_dimensional A m).
Axiom thm_MATROID_DIM_SET : forall {A : Type'}, forall m : Matroid A, (@matroid_dim A m (@mat_set A m)) = (@matroid_dimension A m).
Axiom thm_MATROID_FINITE_DIM_SPAN_EQ : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_finite_dim A m s) = ((@subset A s (@mat_set A m)) /\ (@matroid_finite_dim A m (@mat_span A m s))).
Axiom thm_MATROID_FINITE_DIM_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> (@matroid_finite_dim A m (@mat_span A m s)) = (@matroid_finite_dim A m s).
Axiom thm_MATROID_DIM_SPAN : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@subset A s (@mat_set A m)) -> (@matroid_dim A m (@mat_span A m s)) = (@matroid_dim A m s).
Axiom thm_MATROID_FINITE_DIMENSIONAL : forall {A : Type'}, forall m : Matroid A, (@matroid_finite_dimensional A m) = (exists b : A -> Prop, (@finite_set A b) /\ ((@subset A b (@mat_set A m)) /\ (@subset A (@mat_set A m) (@mat_span A m b)))).
Axiom thm_MATROID_FINITE_DIMENSIONAL_BASIS : forall {A : Type'}, forall m : Matroid A, (@matroid_finite_dimensional A m) = (exists b : A -> Prop, (@finite_set A b) /\ (@matroid_basis A m b)).
Axiom thm_MATROID_FINITE_DIMENSIONAL_CONTAINS_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, ((@matroid_finite_dimensional A m) /\ (@matroid_spanning A m s)) -> exists b : A -> Prop, (@finite_set A b) /\ ((@subset A b s) /\ (@matroid_basis A m b)).
Axiom thm_MATROID_FINITE_DIMENSIONAL_ANY : forall {A : Type'}, forall m : Matroid A, forall b : A -> Prop, (@matroid_basis A m b) -> (@matroid_finite_dimensional A m) = (@finite_set A b).
Axiom thm_MATROID_FINITE_DIM : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_finite_dim A m s) = (exists b : A -> Prop, (@finite_set A b) /\ ((@subset A b (@mat_set A m)) /\ (@subset A s (@mat_span A m b)))).
Axiom thm_MATROID_FINITE_DIM_BASIS : forall {A : Type'}, forall m : Matroid A, forall s : A -> Prop, (@matroid_finite_dim A m s) = ((@subset A s (@mat_set A m)) /\ (exists b : A -> Prop, (@finite_set A b) /\ ((@subset A b s) /\ ((@matroid_independent A m b) /\ ((@mat_span A m b) = (@mat_span A m s)))))).
