Axiom thm_HOMEOMORPHIC_MAP_FRONTIER_OF : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall s : A -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@subset A s (@topspace A top))) -> (@frontier_of B top' (@IMAGE A B f s)) = (@IMAGE A B f (@frontier_of A top s)).
Axiom thm_HOMEOMORPHIC_MAPS_SUBTOPOLOGIES : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : B -> A, forall s : A -> Prop, forall t : B -> Prop, ((@homeomorphic_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)) /\ ((@IMAGE A B f (@setI A (@topspace A top) s)) = (@setI B (@topspace B top') t))) -> @homeomorphic_maps A B (@pair (Topology A) (Topology B) (@subtopology A top s) (@subtopology B top' t)) (@pair (A -> B) (B -> A) f g).
Axiom thm_HOMEOMORPHIC_MAPS_SUBTOPOLOGIES_ALT : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : B -> A, forall s : A -> Prop, forall t : B -> Prop, ((@homeomorphic_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)) /\ ((@subset B (@IMAGE A B f (@setI A (@topspace A top) s)) t) /\ (@subset A (@IMAGE B A g (@setI B (@topspace B top') t)) s))) -> @homeomorphic_maps A B (@pair (Topology A) (Topology B) (@subtopology A top s) (@subtopology B top' t)) (@pair (A -> B) (B -> A) f g).
Axiom thm_HOMEOMORPHIC_MAP_SUBTOPOLOGIES : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall s : A -> Prop, forall t : B -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@IMAGE A B f (@setI A (@topspace A top) s)) = (@setI B (@topspace B top') t))) -> @homeomorphic_map A B (@pair (Topology A) (Topology B) (@subtopology A top s) (@subtopology B top' t)) f.
Axiom thm_HOMEOMORPHIC_MAP_SUBTOPOLOGIES_ALT : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall s : A -> Prop, forall t : B -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ (forall x : A, ((@IN A x (@topspace A top)) /\ (@IN B (f x) (@topspace B top'))) -> (@IN B (f x) t) = (@IN A x s))) -> @homeomorphic_map A B (@pair (Topology A) (Topology B) (@subtopology A top s) (@subtopology B top' t)) f.
Axiom thm_HOMEOMORPHIC_MAPS_PROD : forall {A B C D : Type'}, forall top1 : Topology A, forall top2 : Topology C, forall top3 : Topology B, forall top4 : Topology D, forall f : A -> B, forall g : C -> D, forall f' : B -> A, forall g' : D -> C, (@homeomorphic_maps (prod A C) (prod B D) (@pair (Topology (prod A C)) (Topology (prod B D)) (@prod_topology A C top1 top2) (@prod_topology B D top3 top4)) (@pair ((prod A C) -> prod B D) ((prod B D) -> prod A C) (@ε ((prod A C) -> prod B D) (fun f'' : (prod A C) -> prod B D => forall x : A, forall y : C, @eq (prod B D) (f'' (@pair A C x y)) (@pair B D (f x) (g y)))) (@ε ((prod B D) -> prod A C) (fun f'' : (prod B D) -> prod A C => forall x : B, forall y : D, @eq (prod A C) (f'' (@pair B D x y)) (@pair A C (f' x) (g' y)))))) = ((((@topspace (prod A C) (@prod_topology A C top1 top2)) = (@set0 (prod A C))) /\ ((@topspace (prod B D) (@prod_topology B D top3 top4)) = (@set0 (prod B D)))) \/ ((@homeomorphic_maps A B (@pair (Topology A) (Topology B) top1 top3) (@pair (A -> B) (B -> A) f f')) /\ (@homeomorphic_maps C D (@pair (Topology C) (Topology D) top2 top4) (@pair (C -> D) (D -> C) g g')))).
Axiom thm_HOMEOMORPHIC_MAPS_SWAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, @homeomorphic_maps (prod A B) (prod B A) (@pair (Topology (prod A B)) (Topology (prod B A)) (@prod_topology A B top top') (@prod_topology B A top' top)) (@pair ((prod A B) -> prod B A) ((prod B A) -> prod A B) (@ε ((prod A B) -> prod B A) (fun f : (prod A B) -> prod B A => forall x : A, forall y : B, @eq (prod B A) (f (@pair A B x y)) (@pair B A y x))) (@ε ((prod B A) -> prod A B) (fun f : (prod B A) -> prod A B => forall y : B, forall x : A, @eq (prod A B) (f (@pair B A y x)) (@pair A B x y)))).
Axiom thm_HOMEOMORPHIC_MAP_SWAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, @homeomorphic_map (prod A B) (prod B A) (@pair (Topology (prod A B)) (Topology (prod B A)) (@prod_topology A B top top') (@prod_topology B A top' top)) (@ε ((prod A B) -> prod B A) (fun f : (prod A B) -> prod B A => forall x : A, forall y : B, @eq (prod B A) (f (@pair A B x y)) (@pair B A y x))).
Axiom thm_homeomorphic_space : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') = (exists f : A -> B, exists g : B -> A, @homeomorphic_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)).
Axiom thm_HOMEOMORPHIC_SPACE_REFL : forall {A : Type'}, forall top : Topology A, @homeomorphic_space A A top top.
Axiom thm_HOMEOMORPHIC_SPACE_SYM : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') = (@homeomorphic_space B A top' top).
Axiom thm_HOMEOMORPHIC_SPACE_TRANS : forall {A B C : Type'}, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homeomorphic_space A B top1 top2) /\ (@homeomorphic_space B C top2 top3)) -> @homeomorphic_space A C top1 top3.
Axiom thm_HOMEOMORPHIC_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') = (exists f : A -> B, @homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f).
Axiom thm_HOMEOMORPHIC_MAPS_IMP_HOMEOMORPHIC_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : B -> A, (@homeomorphic_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)) -> @homeomorphic_space A B top top'.
Axiom thm_HOMEOMORPHIC_MAP_IMP_HOMEOMORPHIC_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) -> @homeomorphic_space A B top top'.
Axiom thm_HOMEOMORPHIC_SPACE_IMP_CARD_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> @eq_c A B (@topspace A top) (@topspace B top').
Axiom thm_HOMEOMORPHIC_SPACE_FINITENESS : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@finite_set A (@topspace A top)) = (@finite_set B (@topspace B top')).
Axiom thm_HOMEOMORPHIC_SPACE_INFINITENESS : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@INFINITE A (@topspace A top)) = (@INFINITE B (@topspace B top')).
Axiom thm_HOMEOMORPHIC_SPACE_COUNTABILITY : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@COUNTABLE A (@topspace A top)) = (@COUNTABLE B (@topspace B top')).
Axiom thm_HOMEOMORPHIC_EMPTY_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> ((@topspace A top) = (@set0 A)) = ((@topspace B top') = (@set0 B)).
Axiom thm_HOMEOMORPHIC_EMPTY_SPACE_EQ : forall {A B : Type'}, (forall top : Topology A, forall top' : Topology B, ((@topspace A top) = (@set0 A)) -> (@homeomorphic_space A B top top') = ((@topspace B top') = (@set0 B))) /\ (forall top : Topology A, forall top' : Topology B, ((@topspace B top') = (@set0 B)) -> (@homeomorphic_space A B top top') = ((@topspace A top) = (@set0 A))).
Axiom thm_PROD_TOPOLOGY_HOMEOMORPHIC_SPACE_LEFT : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall b : B, ((@topspace B top') = (@INSERT B b (@set0 B))) -> @homeomorphic_space (prod A B) A (@prod_topology A B top top') top.
Axiom thm_PROD_TOPOLOGY_HOMEOMORPHIC_SPACE_RIGHT : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall a : A, ((@topspace A top) = (@INSERT A a (@set0 A))) -> @homeomorphic_space (prod A B) B (@prod_topology A B top top') top'.
Axiom thm_HOMEOMORPHIC_SPACE_PROD_TOPOLOGY_SING : forall {A B : Type'}, (forall top : Topology A, forall top' : Topology B, forall b : B, (@IN B b (@topspace B top')) -> @homeomorphic_space A (prod A B) top (@prod_topology A B top (@subtopology B top' (@INSERT B b (@set0 B))))) /\ (forall top : Topology A, forall top' : Topology B, forall a : A, (@IN A a (@topspace A top)) -> @homeomorphic_space B (prod A B) top' (@prod_topology A B (@subtopology A top (@INSERT A a (@set0 A))) top')).
Axiom thm_TOPOLOGICAL_PROPERTY_OF_PROD_COMPONENT : forall {A B : Type'}, forall P : (Topology (prod A B)) -> Prop, forall Q : (Topology A) -> Prop, forall R' : (Topology B) -> Prop, forall top1 : Topology A, forall top2 : Topology B, ((forall a : A, ((@IN A a (@topspace A top1)) /\ (P (@prod_topology A B top1 top2))) -> P (@subtopology (prod A B) (@prod_topology A B top1 top2) (@CROSS A B (@INSERT A a (@set0 A)) (@topspace B top2)))) /\ ((forall b : B, ((@IN B b (@topspace B top2)) /\ (P (@prod_topology A B top1 top2))) -> P (@subtopology (prod A B) (@prod_topology A B top1 top2) (@CROSS A B (@topspace A top1) (@INSERT B b (@set0 B))))) /\ ((forall top : Topology (prod A B), forall top' : Topology A, (@homeomorphic_space (prod A B) A top top') -> (P top) = (Q top')) /\ (forall top : Topology (prod A B), forall top' : Topology B, (@homeomorphic_space (prod A B) B top top') -> (P top) = (R' top'))))) -> (P (@prod_topology A B top1 top2)) -> ((@topspace (prod A B) (@prod_topology A B top1 top2)) = (@set0 (prod A B))) \/ ((Q top1) /\ (R' top2)).
Axiom thm_PRODUCT_TOPOLOGY_HOMEOMORPHIC_COMPONENT : forall {A K : Type'}, forall tops : K -> Topology A, forall k : K -> Prop, forall i : K, ((@IN K i k) /\ (forall j : K, ((@IN K j k) /\ (~ (j = i))) -> exists a : A, (@topspace A (tops j)) = (@INSERT A a (@set0 A)))) -> @homeomorphic_space (K -> A) A (@product_topology A K k tops) (tops i).
Axiom thm_TOPOLOGICAL_PROPERTY_OF_PRODUCT_COMPONENT : forall {A K : Type'}, forall P : (Topology (K -> A)) -> Prop, forall Q : (Topology A) -> Prop, forall tops : K -> Topology A, forall k : K -> Prop, ((forall z : K -> A, forall i : K, ((@IN (K -> A) z (@topspace (K -> A) (@product_topology A K k tops))) /\ ((P (@product_topology A K k tops)) /\ (@IN K i k))) -> P (@subtopology (K -> A) (@product_topology A K k tops) (@cartesian_product A K k (fun j : K => @COND (A -> Prop) (j = i) (@topspace A (tops i)) (@INSERT A (z j) (@set0 A)))))) /\ (forall top : Topology (K -> A), forall top' : Topology A, (@homeomorphic_space (K -> A) A top top') -> (P top) = (Q top'))) -> (P (@product_topology A K k tops)) -> ((@topspace (K -> A) (@product_topology A K k tops)) = (@set0 (K -> A))) \/ (forall i : K, (@IN K i k) -> Q (tops i)).
Axiom thm_HOMEOMORPHIC_SPACE_PROD_TOPOLOGY : forall {A B C D : Type'}, forall top1 : Topology A, forall top1' : Topology B, forall top2 : Topology C, forall top2' : Topology D, ((@homeomorphic_space A B top1 top1') /\ (@homeomorphic_space C D top2 top2')) -> @homeomorphic_space (prod A C) (prod B D) (@prod_topology A C top1 top2) (@prod_topology B D top1' top2').
Axiom thm_HOMEOMORPHIC_SPACE_PROD_TOPOLOGY_SWAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, @homeomorphic_space (prod A B) (prod B A) (@prod_topology A B top top') (@prod_topology B A top' top).
Axiom thm_HOMEOMORPHIC_SPACE_SINGLETON_PRODUCT : forall {A K : Type'}, forall tops : K -> Topology A, forall k : K, @homeomorphic_space (K -> A) A (@product_topology A K (@INSERT K k (@set0 K)) tops) (tops k).
Axiom thm_embedding_map : forall {A B : Type'}, forall top' : Topology B, forall top : Topology A, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) = (@homeomorphic_map A B (@pair (Topology A) (Topology B) top (@subtopology B top' (@IMAGE A B f (@topspace A top)))) f).
Axiom thm_EMBEDDING_MAP_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, ((forall x : A, (@IN A x (@topspace A top)) -> (f x) = (g x)) /\ (@embedding_map A B (@pair (Topology A) (Topology B) top top') f)) -> @embedding_map A B (@pair (Topology A) (Topology B) top top') g.
Axiom thm_EMBEDDING_MAP_COMPOSE : forall {A B C : Type'}, forall top : Topology A, forall top' : Topology B, forall top'' : Topology C, forall f : A -> B, forall g : B -> C, ((@embedding_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@embedding_map B C (@pair (Topology B) (Topology C) top' top'') g)) -> @embedding_map A C (@pair (Topology A) (Topology C) top top'') (@o A B C g f).
Axiom thm_SURJECTIVE_EMBEDDING_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@embedding_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@IMAGE A B f (@topspace A top)) = (@topspace B top'))) = (@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f).
Axiom thm_EMBEDDING_MAP_IN_SUBTOPOLOGY : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall s : B -> Prop, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top (@subtopology B top' s)) f) = ((@embedding_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@subset B (@IMAGE A B f (@topspace A top)) s)).
Axiom thm_INJECTIVE_OPEN_IMP_EMBEDDING_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@open_map A B (@pair (Topology A) (Topology B) top top') f) /\ (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> ((f x) = (f y)) = (x = y)))) -> @embedding_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_INJECTIVE_CLOSED_IMP_EMBEDDING_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@closed_map A B (@pair (Topology A) (Topology B) top top') f) /\ (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> ((f x) = (f y)) = (x = y)))) -> @embedding_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_EMBEDDING_MAP_IMP_HOMEOMORPHIC_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) -> @homeomorphic_space A B top (@subtopology B top' (@IMAGE A B f (@topspace A top))).
Axiom thm_EMBEDDING_IMP_CONTINUOUS_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) -> @continuous_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_EMBEDDING_IMP_INJECTIVE_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) -> forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> ((f x) = (f y)) = (x = y).
Axiom thm_EMBEDDING_IMP_CLOSED_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@embedding_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@closed_in B top' (@IMAGE A B f (@topspace A top)))) -> @closed_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_EMBEDDING_IMP_CLOSED_MAP_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) -> (@closed_map A B (@pair (Topology A) (Topology B) top top') f) = (@closed_in B top' (@IMAGE A B f (@topspace A top))).
Axiom thm_EMBEDDING_IMP_OPEN_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@embedding_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@open_in B top' (@IMAGE A B f (@topspace A top)))) -> @open_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_EMBEDDING_IMP_OPEN_MAP_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@embedding_map A B (@pair (Topology A) (Topology B) top top') f) -> (@open_map A B (@pair (Topology A) (Topology B) top top') f) = (@open_in B top' (@IMAGE A B f (@topspace A top))).
Axiom thm_EMBEDDING_MAP_ON_EMPTY : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@topspace A top) = (@set0 A)) -> @embedding_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_EMBEDDING_MAP_COMPONENT_INJECTION : forall {A K : Type'}, forall k : K -> Prop, forall top : K -> Topology A, forall i : K, (@IN K i k) -> @embedding_map A (prod K A) (@pair (Topology A) (Topology (prod K A)) (top i) (@sum_topology A K k top)) (fun x : A => @pair K A i x).
Axiom thm_TOPOLOGICAL_PROPERTY_OF_SUM_COMPONENT : forall {A K : Type'}, forall P : (Topology (prod K A)) -> Prop, forall Q : (Topology A) -> Prop, forall tops : K -> Topology A, forall k : K -> Prop, ((forall top : Topology (prod K A), forall s : (prod K A) -> Prop, ((P top) /\ ((@closed_in (prod K A) top s) /\ (@open_in (prod K A) top s))) -> P (@subtopology (prod K A) top s)) /\ (forall top : Topology (prod K A), forall top' : Topology A, (@homeomorphic_space (prod K A) A top top') -> (P top) = (Q top'))) -> (P (@sum_topology A K k tops)) -> forall i : K, (@IN K i k) -> Q (tops i).
Axiom thm_retraction_maps : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : B -> A, (@retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)) = ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@continuous_map B A (@pair (Topology B) (Topology A) top' top) g) /\ (forall x : B, (@IN B x (@topspace B top')) -> (f (g x)) = x))).
Axiom thm_section_map : forall {A B : Type'}, forall top' : Topology B, forall top : Topology A, forall f : A -> B, (@section_map A B (@pair (Topology A) (Topology B) top top') f) = (exists g : B -> A, @retraction_maps B A (@pair (Topology B) (Topology A) top' top) (@pair (B -> A) (A -> B) g f)).
Axiom thm_retraction_map : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@retraction_map A B (@pair (Topology A) (Topology B) top top') f) = (exists g : B -> A, @retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)).
Axiom thm_RETRACTION_IMP_CONTINUOUS_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@retraction_map A B (@pair (Topology A) (Topology B) top top') f) -> @continuous_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_SECTION_IMP_CONTINUOUS_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, (@section_map A B (@pair (Topology A) (Topology B) top top') f) -> @continuous_map A B (@pair (Topology A) (Topology B) top top') f.
Axiom thm_RETRACTION_MAPS_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall f' : A -> B, forall g : B -> A, forall g' : B -> A, ((forall x : A, (@IN A x (@topspace A top)) -> (f x) = (f' x)) /\ ((forall x : B, (@IN B x (@topspace B top')) -> (g x) = (g' x)) /\ (@retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)))) -> @retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f' g').
Axiom thm_SECTION_MAP_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, ((forall x : A, (@IN A x (@topspace A top)) -> (f x) = (g x)) /\ (@section_map A B (@pair (Topology A) (Topology B) top top') f)) -> @section_map A B (@pair (Topology A) (Topology B) top top') g.
Axiom thm_RETRACTION_MAP_EQ : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, ((forall x : A, (@IN A x (@topspace A top)) -> (f x) = (g x)) /\ (@retraction_map A B (@pair (Topology A) (Topology B) top top') f)) -> @retraction_map A B (@pair (Topology A) (Topology B) top top') g.
Axiom thm_HOMEOMORPHIC_IMP_RETRACTION_MAPS : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : B -> A, (@homeomorphic_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g)) -> @retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) f g).
