Axiom thm_TRIVIAL_LIMIT_SEQUENTIALLY : ~ (@trivial_limit nat sequentially).
Axiom thm_EVENTUALLY_HAPPENS_SEQUENTIALLY : forall P : nat -> Prop, (@eventually nat P sequentially) -> exists n : nat, P n.
Axiom thm_EVENTUALLY_SEQUENTIALLY_WITHIN : forall k : nat -> Prop, forall p : nat -> Prop, (@eventually nat p (@within nat sequentially k)) = ((@finite_set nat k) \/ (exists N' : nat, forall n : nat, ((@IN nat n k) /\ (leqn N' n)) -> p n)).
Axiom thm_TRIVIAL_LIMIT_SEQUENTIALLY_WITHIN : forall k : nat -> Prop, (@trivial_limit nat (@within nat sequentially k)) = (@finite_set nat k).
Axiom thm_EVENTUALLY_SUBSEQUENCE : forall P : nat -> Prop, forall r : nat -> nat, ((forall m : nat, forall n : nat, (ltn m n) -> ltn (r m) (r n)) /\ (@eventually nat P sequentially)) -> @eventually nat (@o nat nat Prop P r) sequentially.
Axiom thm_ARCH_EVENTUALLY_LT : forall x : R, @eventually nat (fun n : nat => ltr x (R_of_nat n)) sequentially.
Axiom thm_ARCH_EVENTUALLY_LE : forall x : R, @eventually nat (fun n : nat => ler x (R_of_nat n)) sequentially.
Axiom thm_ARCH_EVENTUALLY_ABS_INV_OFFSET : forall a : R, forall e : R, (@eventually nat (fun n : nat => ltr (normr (invr (addr (R_of_nat n) a))) e) sequentially) = (ltr (R_of_nat (NUMERAL O)) e).
Axiom thm_ARCH_EVENTUALLY_INV_OFFSET : forall a : R, forall e : R, (@eventually nat (fun n : nat => ltr (invr (addr (R_of_nat n) a)) e) sequentially) = (ltr (R_of_nat (NUMERAL O)) e).
Axiom thm_ARCH_EVENTUALLY_INV1 : forall e : R, (@eventually nat (fun n : nat => ltr (invr (addr (R_of_nat n) (R_of_nat (NUMERAL (BIT1 O))))) e) sequentially) = (ltr (R_of_nat (NUMERAL O)) e).
Axiom thm_ARCH_EVENTUALLY_INV : forall e : R, (@eventually nat (fun n : nat => ltr (invr (R_of_nat n)) e) sequentially) = (ltr (R_of_nat (NUMERAL O)) e).
Axiom thm_ARCH_EVENTUALLY_POW : forall x : R, forall b : R, (ltr (R_of_nat (NUMERAL (BIT1 O))) x) -> @eventually nat (fun n : nat => ltr b (expr x n)) sequentially.
Axiom thm_ARCH_EVENTUALLY_POW_INV : forall x : R, forall e : R, ((ltr (R_of_nat (NUMERAL O)) e) /\ (ltr (normr x) (R_of_nat (NUMERAL (BIT1 O))))) -> @eventually nat (fun n : nat => ltr (normr (expr x n)) e) sequentially.
Axiom thm_EVENTUALLY_IN_SEQUENTIALLY : forall P : nat -> Prop, (@eventually nat P sequentially) = (@finite_set nat (@GSPEC nat (fun GEN_PVAR_1597 : nat => exists n : nat, @SETSPEC nat GEN_PVAR_1597 (~ (P n)) n))).
Axiom thm_EVENTUALLY_NO_SUBSEQUENCE : forall P : nat -> Prop, (@eventually nat P sequentially) = (~ (exists r : nat -> nat, (forall m : nat, forall n : nat, (ltn m n) -> ltn (r m) (r n)) /\ (forall n : nat, ~ (P (r n))))).
Axiom thm_EVENTUALLY_UBOUND_LE_SEQUENTIALLY : forall f : nat -> R, (exists b : R, @eventually nat (fun n : nat => ler (f n) b) sequentially) = (exists b : R, forall n : nat, ler (f n) b).
Axiom thm_EVENTUALLY_LBOUND_LE_SEQUENTIALLY : forall f : nat -> R, (exists b : R, @eventually nat (fun n : nat => ler b (f n)) sequentially) = (exists b : R, forall n : nat, ler b (f n)).
Axiom thm_fsigma_in : forall {A : Type'}, forall top : Topology A, (@fsigma_in A top) = (@UNION_OF A (@COUNTABLE (A -> Prop)) (@closed_in A top)).
Axiom thm_gdelta_in : forall {A : Type'}, forall top : Topology A, (@gdelta_in A top) = (@relative_to A (@INTERSECTION_OF A (@COUNTABLE (A -> Prop)) (@open_in A top)) (@topspace A top)).
Axiom thm_FSIGMA_IN_ASCENDING : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@fsigma_in A top s) = (exists c : nat -> A -> Prop, (forall n : nat, @closed_in A top (c n)) /\ ((forall n : nat, @subset A (c n) (c (addn n (NUMERAL (BIT1 O))))) /\ ((@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1608 : A -> Prop => exists n : nat, @SETSPEC (A -> Prop) GEN_PVAR_1608 (@IN nat n (@setT nat)) (c n)))) = s))).
Axiom thm_GDELTA_IN_ALT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@gdelta_in A top s) = ((@subset A s (@topspace A top)) /\ (@INTERSECTION_OF A (@COUNTABLE (A -> Prop)) (@open_in A top) s)).
Axiom thm_FSIGMA_IN_SUBSET : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@fsigma_in A top s) -> @subset A s (@topspace A top).
Axiom thm_GDELTA_IN_SUBSET : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@gdelta_in A top s) -> @subset A s (@topspace A top).
Axiom thm_CLOSED_IMP_FSIGMA_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@closed_in A top s) -> @fsigma_in A top s.
Axiom thm_OPEN_IMP_GDELTA_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@open_in A top s) -> @gdelta_in A top s.
Axiom thm_FSIGMA_IN_EMPTY : forall {A : Type'}, forall top : Topology A, @fsigma_in A top (@set0 A).
Axiom thm_GDELTA_IN_EMPTY : forall {A : Type'}, forall top : Topology A, @gdelta_in A top (@set0 A).
Axiom thm_FSIGMA_IN_TOPSPACE : forall {A : Type'}, forall top : Topology A, @fsigma_in A top (@topspace A top).
Axiom thm_GDELTA_IN_TOPSPACE : forall {A : Type'}, forall top : Topology A, @gdelta_in A top (@topspace A top).
Axiom thm_FSIGMA_IN_UNIONS : forall {A : Type'}, forall top : Topology A, forall t : (A -> Prop) -> Prop, ((@COUNTABLE (A -> Prop) t) /\ (forall s : A -> Prop, (@IN (A -> Prop) s t) -> @fsigma_in A top s)) -> @fsigma_in A top (@UNIONS A t).
Axiom thm_FSIGMA_IN_UNION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@fsigma_in A top s) /\ (@fsigma_in A top t)) -> @fsigma_in A top (@setU A s t).
Axiom thm_FSIGMA_IN_INTER : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@fsigma_in A top s) /\ (@fsigma_in A top t)) -> @fsigma_in A top (@setI A s t).
Axiom thm_GDELTA_IN_INTERS : forall {A : Type'}, forall top : Topology A, forall t : (A -> Prop) -> Prop, ((@COUNTABLE (A -> Prop) t) /\ ((~ (t = (@set0 (A -> Prop)))) /\ (forall s : A -> Prop, (@IN (A -> Prop) s t) -> @gdelta_in A top s))) -> @gdelta_in A top (@INTERS A t).
Axiom thm_GDELTA_IN_INTER : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@gdelta_in A top s) /\ (@gdelta_in A top t)) -> @gdelta_in A top (@setI A s t).
Axiom thm_GDELTA_IN_UNION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@gdelta_in A top s) /\ (@gdelta_in A top t)) -> @gdelta_in A top (@setU A s t).
Axiom thm_FSIGMA_IN_DIFF : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@fsigma_in A top s) /\ (@gdelta_in A top t)) -> @fsigma_in A top (@setD A s t).
Axiom thm_GDELTA_IN_DIFF : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@gdelta_in A top s) /\ (@fsigma_in A top t)) -> @gdelta_in A top (@setD A s t).
Axiom thm_GDELTA_IN_FSIGMA_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@gdelta_in A top s) = ((@subset A s (@topspace A top)) /\ (@fsigma_in A top (@setD A (@topspace A top) s))).
Axiom thm_FSIGMA_IN_GDELTA_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@fsigma_in A top s) = ((@subset A s (@topspace A top)) /\ (@gdelta_in A top (@setD A (@topspace A top) s))).
Axiom thm_GDELTA_IN_DESCENDING : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@gdelta_in A top s) = (exists c : nat -> A -> Prop, (forall n : nat, @open_in A top (c n)) /\ ((forall n : nat, @subset A (c (addn n (NUMERAL (BIT1 O)))) (c n)) /\ ((@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1612 : A -> Prop => exists n : nat, @SETSPEC (A -> Prop) GEN_PVAR_1612 (@IN nat n (@setT nat)) (c n)))) = s))).
Axiom thm_HOMEOMORPHIC_MAP_FSIGMANESS : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@subset A u (@topspace A top))) -> (@fsigma_in B top' (@IMAGE A B f u)) = (@fsigma_in A top u).
Axiom thm_HOMEOMORPHIC_MAP_FSIGMANESS_EQ : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, (@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) -> (@fsigma_in A top u) = ((@subset A u (@topspace A top)) /\ (@fsigma_in B top' (@IMAGE A B f u))).
Axiom thm_HOMEOMORPHIC_MAP_GDELTANESS : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@subset A u (@topspace A top))) -> (@gdelta_in B top' (@IMAGE A B f u)) = (@gdelta_in A top u).
Axiom thm_HOMEOMORPHIC_MAP_GDELTANESS_EQ : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, (@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) -> (@gdelta_in A top u) = ((@subset A u (@topspace A top)) /\ (@gdelta_in B top' (@IMAGE A B f u))).
Axiom thm_FSIGMA_IN_RELATIVE_TO : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@relative_to A (@fsigma_in A top) s) = (@fsigma_in A (@subtopology A top s)).
Axiom thm_FSIGMA_IN_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, forall s : A -> Prop, (@fsigma_in A (@subtopology A top u) s) = (exists t : A -> Prop, (@fsigma_in A top t) /\ (s = (@setI A t u))).
Axiom thm_GDELTA_IN_RELATIVE_TO : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@relative_to A (@gdelta_in A top) s) = (@gdelta_in A (@subtopology A top s)).
Axiom thm_GDELTA_IN_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, forall s : A -> Prop, (@gdelta_in A (@subtopology A top u) s) = (exists t : A -> Prop, (@gdelta_in A top t) /\ (s = (@setI A t u))).
Axiom thm_FSIGMA_IN_FSIGMA_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@fsigma_in A top s) -> (@fsigma_in A (@subtopology A top s) t) = ((@fsigma_in A top t) /\ (@subset A t s)).
Axiom thm_GDELTA_IN_GDELTA_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@gdelta_in A top s) -> (@gdelta_in A (@subtopology A top s) t) = ((@gdelta_in A top t) /\ (@subset A t s)).
Axiom thm_is_metric_space : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) = ((forall x : A, forall y : A, ((@IN A x s) /\ (@IN A y s)) -> ler (R_of_nat (NUMERAL O)) (d (@pair A A x y))) /\ ((forall x : A, forall y : A, ((@IN A x s) /\ (@IN A y s)) -> ((d (@pair A A x y)) = (R_of_nat (NUMERAL O))) = (x = y)) /\ ((forall x : A, forall y : A, ((@IN A x s) /\ (@IN A y s)) -> (d (@pair A A x y)) = (d (@pair A A y x))) /\ (forall x : A, forall y : A, forall z : A, ((@IN A x s) /\ ((@IN A y s) /\ (@IN A z s))) -> ler (d (@pair A A x z)) (addr (d (@pair A A x y)) (d (@pair A A y z))))))).
Axiom thm_IS_METRIC_SPACE : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) = ((forall x : A, forall y : A, ((@IN A x s) /\ (@IN A y s)) -> ((d (@pair A A x y)) = (R_of_nat (NUMERAL O))) = (x = y)) /\ (forall x : A, forall y : A, forall z : A, ((@IN A x s) /\ ((@IN A y s) /\ (@IN A z s))) -> ler (d (@pair A A x z)) (addr (d (@pair A A y x)) (d (@pair A A y z))))).
Axiom thm_IS_METRIC_SPACE_SUBSPACE : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) -> forall s' : A -> Prop, (@subset A s' s) -> @is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s' d).
Axiom thm_mspace : forall {A : Type'}, forall m : Metric A, (@mspace A m) = (@fst (A -> Prop) ((prod A A) -> R) (@dest_metric A m)).
Axiom thm_mdist : forall {A : Type'}, forall m : Metric A, (@mdist A m) = (@snd (A -> Prop) ((prod A A) -> R) (@dest_metric A m)).
Axiom thm_METRIC : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) -> ((@mspace A (@metric A (@pair (A -> Prop) ((prod A A) -> R) s d))) = s) /\ ((@mdist A (@metric A (@pair (A -> Prop) ((prod A A) -> R) s d))) = d).
Axiom thm_MSPACE : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) -> (@mspace A (@metric A (@pair (A -> Prop) ((prod A A) -> R) s d))) = s.
Axiom thm_MDIST : forall {A : Type'}, forall s : A -> Prop, forall d : (prod A A) -> R, (@is_metric_space A (@pair (A -> Prop) ((prod A A) -> R) s d)) -> (@mdist A (@metric A (@pair (A -> Prop) ((prod A A) -> R) s d))) = d.
Axiom thm_MDIST_POS_LE : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> ler (R_of_nat (NUMERAL O)) (@mdist A m (@pair A A x y)).
Axiom thm_MDIST_0 : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> ((@mdist A m (@pair A A x y)) = (R_of_nat (NUMERAL O))) = (x = y).
Axiom thm_MDIST_TRIANGLE : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, forall z : A, ((@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (@IN A z (@mspace A m)))) -> ler (@mdist A m (@pair A A x z)) (addr (@mdist A m (@pair A A x y)) (@mdist A m (@pair A A y z))).
Axiom thm_MDIST_SYM : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> (@mdist A m (@pair A A x y)) = (@mdist A m (@pair A A y x)).
Axiom thm_REAL_ABS_MDIST : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> (normr (@mdist A m (@pair A A x y))) = (@mdist A m (@pair A A x y)).
Axiom thm_MDIST_POS_LT : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (~ (x = y)))) -> ltr (R_of_nat (NUMERAL O)) (@mdist A m (@pair A A x y)).
Axiom thm_MDIST_REFL : forall {A : Type'}, forall m : Metric A, forall x : A, (@IN A x (@mspace A m)) -> (@mdist A m (@pair A A x x)) = (R_of_nat (NUMERAL O)).
Axiom thm_MDIST_POS_EQ : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> (ltr (R_of_nat (NUMERAL O)) (@mdist A m (@pair A A x y))) = (~ (x = y)).
Axiom thm_MDIST_REVERSE_TRIANGLE : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, forall z : A, ((@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (@IN A z (@mspace A m)))) -> ler (normr (subr (@mdist A m (@pair A A x y)) (@mdist A m (@pair A A y z)))) (@mdist A m (@pair A A x z)).
Axiom thm_mball : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, (@mball A m (@pair A R x r)) = (@GSPEC A (fun GEN_PVAR_1613 : A => exists y : A, @SETSPEC A GEN_PVAR_1613 ((@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (ltr (@mdist A m (@pair A A x y)) r))) y)).
Axiom thm_IN_MBALL : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, forall r : R, (@IN A y (@mball A m (@pair A R x r))) = ((@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (ltr (@mdist A m (@pair A A x y)) r))).
Axiom thm_CENTRE_IN_MBALL : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, ((ltr (R_of_nat (NUMERAL O)) r) /\ (@IN A x (@mspace A m))) -> @IN A x (@mball A m (@pair A R x r)).
Axiom thm_CENTRE_IN_MBALL_EQ : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, (@IN A x (@mball A m (@pair A R x r))) = ((@IN A x (@mspace A m)) /\ (ltr (R_of_nat (NUMERAL O)) r)).
Axiom thm_MBALL_SUBSET_MSPACE : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, @subset A (@mball A m (@pair A R x r)) (@mspace A m).
Axiom thm_MBALL_EMPTY : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, (ler r (R_of_nat (NUMERAL O))) -> (@mball A m (@pair A R x r)) = (@set0 A).
Axiom thm_MBALL_EMPTY_ALT : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, (~ (@IN A x (@mspace A m))) -> (@mball A m (@pair A R x r)) = (@set0 A).
Axiom thm_MBALL_EQ_EMPTY : forall {A : Type'}, forall m : Metric A, forall x : A, forall r : R, ((@mball A m (@pair A R x r)) = (@set0 A)) = ((~ (@IN A x (@mspace A m))) \/ (ler r (R_of_nat (NUMERAL O)))).
Axiom thm_MBALL_SUBSET : forall {A : Type'}, forall m : Metric A, forall x : A, forall y : A, forall a : R, forall b : R, ((@IN A y (@mspace A m)) /\ (ler (addr (@mdist A m (@pair A A x y)) a) b)) -> @subset A (@mball A m (@pair A R x a)) (@mball A m (@pair A R y b)).
Axiom thm_DISJOINT_MBALL : forall {A : Type'}, forall m : Metric A, forall x : A, forall x' : A, forall r : R, forall r' : R, (ler (addr r r') (@mdist A m (@pair A A x x'))) -> @DISJOINT A (@mball A m (@pair A R x r)) (@mball A m (@pair A R x' r')).
Axiom thm_MBALL_SUBSET_CONCENTRIC : forall {A : Type'}, forall m : Metric A, forall x : A, forall r1 : R, forall r2 : R, (ler r1 r2) -> @subset A (@mball A m (@pair A R x r1)) (@mball A m (@pair A R x r2)).
Axiom thm_submetric : forall {A : Type'}, forall s : A -> Prop, forall m : Metric A, (@submetric A m s) = (@metric A (@pair (A -> Prop) ((prod A A) -> R) (@setI A s (@mspace A m)) (@mdist A m))).
Axiom thm_SUBMETRIC : forall {A : Type'}, (forall m : Metric A, forall s : A -> Prop, (@mspace A (@submetric A m s)) = (@setI A s (@mspace A m))) /\ (forall m : Metric A, forall s : A -> Prop, (@mdist A (@submetric A m s)) = (@mdist A m)).
Axiom thm_MBALL_SUBMETRIC_EQ : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall a : A, forall r : R, (@mball A (@submetric A m s) (@pair A R a r)) = (@COND (A -> Prop) (@IN A a s) (@setI A s (@mball A m (@pair A R a r))) (@set0 A)).
Axiom thm_MBALL_SUBMETRIC : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall x : A, forall r : R, (@IN A x s) -> (@mball A (@submetric A m s) (@pair A R x r)) = (@setI A (@mball A m (@pair A R x r)) s).
Axiom thm_SUBMETRIC_UNIV : forall {A : Type'} (m : Metric A), (@submetric A m (@setT A)) = m.
Axiom thm_SUBMETRIC_SUBMETRIC : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, (@submetric A (@submetric A m s) t) = (@submetric A m (@setI A s t)).
Axiom thm_SUBMETRIC_MSPACE : forall {A : Type'}, forall m : Metric A, (@submetric A m (@mspace A m)) = m.
Axiom thm_SUBMETRIC_RESTRICT : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@submetric A m s) = (@submetric A m (@setI A (@mspace A m) s)).
Axiom thm_mtopology : forall {A : Type'}, forall m : Metric A, (@mtopology A m) = (@topology A (@GSPEC (A -> Prop) (fun GEN_PVAR_1614 : A -> Prop => exists u : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_1614 ((@subset A u (@mspace A m)) /\ (forall x : A, (@IN A x u) -> exists r : R, (ltr (R_of_nat (NUMERAL O)) r) /\ (@subset A (@mball A m (@pair A R x r)) u))) u))).
Axiom thm_IS_TOPOLOGY_METRIC_TOPOLOGY : forall {A : Type'} (m : Metric A), @istopology A (@GSPEC (A -> Prop) (fun GEN_PVAR_1615 : A -> Prop => exists u : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_1615 ((@subset A u (@mspace A m)) /\ (forall x : A, (@IN A x u) -> exists r : R, (ltr (R_of_nat (NUMERAL O)) r) /\ (@subset A (@mball A m (@pair A R x r)) u))) u)).
Axiom thm_OPEN_IN_MTOPOLOGY : forall {A : Type'}, forall m : Metric A, forall u : A -> Prop, (@open_in A (@mtopology A m) u) = ((@subset A u (@mspace A m)) /\ (forall x : A, (@IN A x u) -> exists r : R, (ltr (R_of_nat (NUMERAL O)) r) /\ (@subset A (@mball A m (@pair A R x r)) u))).
Axiom thm_TOPSPACE_MTOPOLOGY : forall {A : Type'}, forall m : Metric A, (@topspace A (@mtopology A m)) = (@mspace A m).
Axiom thm_SUBTOPOLOGY_MSPACE : forall {A : Type'}, forall m : Metric A, (@subtopology A (@mtopology A m) (@mspace A m)) = (@mtopology A m).
