Axiom thm_CONNECTED_SPACE_EQ_FRONTIER_EQ_EMPTY : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall s : A -> Prop, ((@subset A s (@topspace A top)) /\ ((@frontier_of A top s) = (@set0 A))) -> (s = (@set0 A)) \/ (s = (@topspace A top))).
Axiom thm_CONNECTED_SPACE_FRONTIER_EQ_EMPTY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@connected_space A top) /\ (@subset A s (@topspace A top))) -> ((@frontier_of A top s) = (@set0 A)) = ((s = (@set0 A)) \/ (s = (@topspace A top))).
Axiom thm_CONNECTED_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists e1 : A -> Prop, exists e2 : A -> Prop, (@open_in A top e1) /\ ((@open_in A top e2) /\ ((@subset A s (@setU A e1 e2)) /\ (((@setI A e1 (@setI A e2 s)) = (@set0 A)) /\ ((~ ((@setI A e1 s) = (@set0 A))) /\ (~ ((@setI A e2 s) = (@set0 A)))))))))).
Axiom thm_CONNECTED_IN_CLOSED_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists e1 : A -> Prop, exists e2 : A -> Prop, (@closed_in A top e1) /\ ((@closed_in A top e2) /\ ((@subset A s (@setU A e1 e2)) /\ (((@setI A e1 (@setI A e2 s)) = (@set0 A)) /\ ((~ ((@setI A e1 s) = (@set0 A))) /\ (~ ((@setI A e2 s) = (@set0 A)))))))))).
Axiom thm_CONNECTED_IN_EMPTY : forall {A : Type'}, forall top : Topology A, @connected_in A top (@set0 A).
Axiom thm_CONNECTED_SPACE_TOPSPACE_EMPTY : forall {A : Type'}, forall top : Topology A, ((@topspace A top) = (@set0 A)) -> @connected_space A top.
Axiom thm_CONNECTED_IN_SING : forall {A : Type'}, forall top : Topology A, forall a : A, (@connected_in A top (@INSERT A a (@set0 A))) = (@IN A a (@topspace A top)).
Axiom thm_CONNECTED_IN_ABSOLUTE : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A (@subtopology A top s) s) = (@connected_in A top s).
Axiom thm_CONNECTED_IN_UNIONS : forall {A : Type'}, forall top : Topology A, forall u : (A -> Prop) -> Prop, ((forall s : A -> Prop, (@IN (A -> Prop) s u) -> @connected_in A top s) /\ (~ ((@INTERS A u) = (@set0 A)))) -> @connected_in A top (@UNIONS A u).
Axiom thm_CONNECTED_IN_UNION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@connected_in A top s) /\ ((@connected_in A top t) /\ (~ ((@setI A s t) = (@set0 A))))) -> @connected_in A top (@setU A s t).
Axiom thm_CONNECTED_SPACE_SUBCONNECTED : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> exists s : A -> Prop, (@connected_in A top s) /\ ((@IN A x s) /\ (@IN A y s))).
Axiom thm_CONNECTED_IN_INTERMEDIATE_CLOSURE_OF : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@connected_in A top s) /\ ((@subset A s t) /\ (@subset A t (@closure_of A top s)))) -> @connected_in A top t.
Axiom thm_CONNECTED_IN_CLOSURE_OF : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) -> @connected_in A top (@closure_of A top s).
Axiom thm_CONNECTED_IN_SEPARATION_ALT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, (@subset A s (@setU A c1 c2)) /\ ((~ ((@setI A c1 s) = (@set0 A))) /\ ((~ ((@setI A c2 s) = (@set0 A))) /\ (((@setI A c1 (@closure_of A top c2)) = (@set0 A)) /\ ((@setI A c2 (@closure_of A top c1)) = (@set0 A)))))))).
Axiom thm_CONNECTED_IN_SEPARATION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, ((@setU A c1 c2) = s) /\ ((~ (c1 = (@set0 A))) /\ ((~ (c2 = (@set0 A))) /\ (((@setI A c1 (@closure_of A top c2)) = (@set0 A)) /\ ((@setI A c2 (@closure_of A top c1)) = (@set0 A)))))))).
Axiom thm_CONNECTED_IN_EQ_NOT_SEPARATED : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, ((@setU A c1 c2) = s) /\ ((~ (c1 = (@set0 A))) /\ ((~ (c2 = (@set0 A))) /\ (@separated_in A top c1 c2)))))).
Axiom thm_CONNECTED_IN_EQ_NOT_SEPARATED_SUBSET : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@connected_in A top s) = ((@subset A s (@topspace A top)) /\ (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, (@subset A s (@setU A c1 c2)) /\ ((~ ((@setI A s c1) = (@set0 A))) /\ ((~ ((@setI A s c2) = (@set0 A))) /\ (@separated_in A top c1 c2)))))).
Axiom thm_CONNECTED_SPACE_EQ_NOT_SEPARATED : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, ((@setU A c1 c2) = (@topspace A top)) /\ ((~ (c1 = (@set0 A))) /\ ((~ (c2 = (@set0 A))) /\ (@separated_in A top c1 c2))))).
Axiom thm_CONNECTED_SPACE_EQ_NOT_SEPARATED_SUBSET : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (~ (exists c1 : A -> Prop, exists c2 : A -> Prop, (@subset A (@topspace A top) (@setU A c1 c2)) /\ ((~ (c1 = (@set0 A))) /\ ((~ (c2 = (@set0 A))) /\ (@separated_in A top c1 c2))))).
Axiom thm_CONNECTED_IN_SUBSET_SEPARATED_UNION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall c : A -> Prop, ((@connected_in A top c) /\ ((@separated_in A top s t) /\ (@subset A c (@setU A s t)))) -> (@subset A c s) \/ (@subset A c t).
Axiom thm_CONNECTED_IN_NONSEPARATED_UNION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@connected_in A top s) /\ ((@connected_in A top t) /\ (~ (@separated_in A top s t)))) -> @connected_in A top (@setU A s t).
Axiom thm_CONNECTED_IN_EQ_SUBSET_SEPARATED_UNION : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@connected_in A top c) = ((@subset A c (@topspace A top)) /\ (forall s : A -> Prop, forall t : A -> Prop, ((@separated_in A top s t) /\ (@subset A c (@setU A s t))) -> (@subset A c s) \/ (@subset A c t))).
Axiom thm_CONNECTED_IN_CLOPEN_CASES : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall t : A -> Prop, ((@connected_in A top c) /\ ((@closed_in A top t) /\ (@open_in A top t))) -> (@subset A c t) \/ (@DISJOINT A c t).
Axiom thm_CONNECTED_SPACE_CLOSURES : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (~ (exists e1 : A -> Prop, exists e2 : A -> Prop, ((@setU A e1 e2) = (@topspace A top)) /\ (((@setI A (@closure_of A top e1) (@closure_of A top e2)) = (@set0 A)) /\ ((~ (e1 = (@set0 A))) /\ (~ (e2 = (@set0 A))))))).
Axiom thm_CONNECTED_IN_INTER_FRONTIER_OF : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@connected_in A top s) /\ ((~ ((@setI A s t) = (@set0 A))) /\ (~ ((@setD A s t) = (@set0 A))))) -> ~ ((@setI A s (@frontier_of A top t)) = (@set0 A)).
Axiom thm_CONNECTED_IN_CONTINUOUS_MAP_IMAGE : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall s : A -> Prop, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@connected_in A top s)) -> @connected_in B top' (@IMAGE A B f s).
Axiom thm_HOMEOMORPHIC_CONNECTED_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@connected_space A top) = (@connected_space B top').
Axiom thm_HOMEOMORPHIC_MAP_CONNECTEDNESS : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, ((@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@subset A u (@topspace A top))) -> (@connected_in B top' (@IMAGE A B f u)) = (@connected_in A top u).
Axiom thm_HOMEOMORPHIC_MAP_CONNECTEDNESS_EQ : forall {A B : Type'}, forall f : A -> B, forall top : Topology A, forall top' : Topology B, forall u : A -> Prop, (@homeomorphic_map A B (@pair (Topology A) (Topology B) top top') f) -> (@connected_in A top u) = ((@subset A u (@topspace A top)) /\ (@connected_in B top' (@IMAGE A B f u))).
Axiom thm_CONNECTED_SPACE_QUOTIENT_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall q : A -> B, ((@quotient_map A B (@pair (Topology A) (Topology B) top top') q) /\ (@connected_space A top)) -> @connected_space B top'.
Axiom thm_CONNECTED_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') r) /\ (@connected_space A top)) -> @connected_space B top'.
Axiom thm_CONNECTED_IN_DISCRETE_TOPOLOGY : forall {A : Type'}, forall u : A -> Prop, forall s : A -> Prop, (@connected_in A (@discrete_topology A u) s) = ((@subset A s u) /\ (exists a : A, @subset A s (@INSERT A a (@set0 A)))).
Axiom thm_CONNECTED_SPACE_DISCRETE_TOPOLOGY : forall {A : Type'}, forall u : A -> Prop, (@connected_space A (@discrete_topology A u)) = (exists a : A, @subset A u (@INSERT A a (@set0 A))).
Axiom thm_CONNECTED_IN_IMP_PERFECT_GEN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@t1_space A top) /\ ((@connected_in A top s) /\ (~ (exists a : A, s = (@INSERT A a (@set0 A)))))) -> @subset A s (@derived_set_of A top s).
Axiom thm_CONNECTED_IN_IMP_PERFECT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@hausdorff_space A top) /\ ((@connected_in A top s) /\ (~ (exists a : A, s = (@INSERT A a (@set0 A)))))) -> @subset A s (@derived_set_of A top s).
Axiom thm_CARD_LE_PAIRWISE_SEPARATED_CONNECTED_IN : forall {A : Type'}, forall top : Topology A, forall u : (A -> Prop) -> Prop, forall v : (A -> Prop) -> Prop, ((@finite_set (A -> Prop) u) /\ ((@pairwise (A -> Prop) (@separated_in A top) u) /\ ((forall c : A -> Prop, (@IN (A -> Prop) c u) -> ~ (c = (@set0 A))) /\ ((forall c : A -> Prop, (@IN (A -> Prop) c v) -> @connected_in A top c) /\ ((@UNIONS A u) = (@UNIONS A v)))))) -> @le_c (A -> Prop) (A -> Prop) u v.
Axiom thm_CONNECTED_SPACE_PROD_TOPOLOGY : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, (@connected_space (prod A B) (@prod_topology A B top1 top2)) = (((@topspace (prod A B) (@prod_topology A B top1 top2)) = (@set0 (prod A B))) \/ ((@connected_space A top1) /\ (@connected_space B top2))).
Axiom thm_CONNECTED_IN_CROSS : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, forall s : A -> Prop, forall t : B -> Prop, (@connected_in (prod A B) (@prod_topology A B top1 top2) (@CROSS A B s t)) = ((s = (@set0 A)) \/ ((t = (@set0 B)) \/ ((@connected_in A top1 s) /\ (@connected_in B top2 t)))).
Axiom thm_CONNECTED_SPACE_PRODUCT_TOPOLOGY : forall {A K : Type'}, forall tops : K -> Topology A, forall k : K -> Prop, (@connected_space (K -> A) (@product_topology A K k tops)) = (((@topspace (K -> A) (@product_topology A K k tops)) = (@set0 (K -> A))) \/ (forall i : K, (@IN K i k) -> @connected_space A (tops i))).
Axiom thm_CONNECTED_IN_CARTESIAN_PRODUCT : forall {A K : Type'}, forall tops : K -> Topology A, forall s : K -> A -> Prop, forall k : K -> Prop, (@connected_in (K -> A) (@product_topology A K k tops) (@cartesian_product A K k s)) = (((@cartesian_product A K k s) = (@set0 (K -> A))) \/ (forall i : K, (@IN K i k) -> @connected_in A (tops i) (s i))).
Axiom thm_separated_between : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = (exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((@open_in A top v) /\ (((@setU A u v) = (@topspace A top)) /\ ((@DISJOINT A u v) /\ ((@subset A s u) /\ (@subset A t v)))))).
Axiom thm_SEPARATED_BETWEEN_ALT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = (exists u : A -> Prop, exists v : A -> Prop, (@closed_in A top u) /\ ((@closed_in A top v) /\ (((@setU A u v) = (@topspace A top)) /\ ((@DISJOINT A u v) /\ ((@subset A s u) /\ (@subset A t v)))))).
Axiom thm_SEPARATED_BETWEEN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = (exists u : A -> Prop, (@closed_in A top u) /\ ((@open_in A top u) /\ ((@subset A s u) /\ (@subset A t (@setD A (@topspace A top) u))))).
Axiom thm_SEPARATED_BETWEEN_MONO : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall s' : A -> Prop, forall t' : A -> Prop, ((@separated_between A top s t) /\ ((@subset A s' s) /\ (@subset A t' t))) -> @separated_between A top s' t'.
Axiom thm_SEPARATED_BETWEEN_REFL : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@separated_between A top s s) = (s = (@set0 A)).
Axiom thm_SEPARATED_BETWEEN_SYM : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = (@separated_between A top t s).
Axiom thm_SEPARATED_BETWEEN_IMP_SUBSET : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) -> (@subset A s (@topspace A top)) /\ (@subset A t (@topspace A top)).
Axiom thm_SEPARATED_BETWEEN_EMPTY : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, (@separated_between A top (@set0 A) s) = (@subset A s (@topspace A top))) /\ (forall top : Topology A, forall s : A -> Prop, (@separated_between A top s (@set0 A)) = (@subset A s (@topspace A top))).
Axiom thm_SEPARATED_BETWEEN_UNION : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall u : A -> Prop, (@separated_between A top s (@setU A t u)) = ((@separated_between A top s t) /\ (@separated_between A top s u))) /\ (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall u : A -> Prop, (@separated_between A top (@setU A s t) u) = ((@separated_between A top s u) /\ (@separated_between A top t u))).
Axiom thm_SEPARATED_BETWEEN_IMP_DISJOINT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) -> @DISJOINT A s t.
Axiom thm_SEPARATED_BETWEEN_IMP_SEPARATED_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) -> @separated_in A top s t.
Axiom thm_SEPARATED_BETWEEN_FULL : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@setU A s t) = (@topspace A top)) -> (@separated_between A top s t) = ((@DISJOINT A s t) /\ ((@closed_in A top s) /\ ((@open_in A top s) /\ ((@closed_in A top t) /\ (@open_in A top t))))).
Axiom thm_SEPARATED_BETWEEN_EQ_SEPARATED_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@setU A s t) = (@topspace A top)) -> (@separated_between A top s t) = (@separated_in A top s t).
Axiom thm_SEPARATED_BETWEEN_POINTWISE_LEFT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@compact_in A top s) -> (@separated_between A top s t) = (((s = (@set0 A)) -> @subset A t (@topspace A top)) /\ (forall x : A, (@IN A x s) -> @separated_between A top (@INSERT A x (@set0 A)) t)).
Axiom thm_SEPARATED_BETWEEN_POINTWISE_RIGHT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@compact_in A top t) -> (@separated_between A top s t) = (((t = (@set0 A)) -> @subset A s (@topspace A top)) /\ (forall y : A, (@IN A y t) -> @separated_between A top s (@INSERT A y (@set0 A)))).
Axiom thm_SEPARATED_BETWEEN_CLOSURE_OF : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@subset A s (@topspace A top)) -> (@separated_between A top (@closure_of A top s) t) = (@separated_between A top s t)) /\ (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@subset A t (@topspace A top)) -> (@separated_between A top s (@closure_of A top t)) = (@separated_between A top s t)).
Axiom thm_SEPARATED_BETWEEN_CLOSURE_OF_EQ : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = ((@subset A s (@topspace A top)) /\ (@separated_between A top (@closure_of A top s) t))) /\ (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = ((@subset A t (@topspace A top)) /\ (@separated_between A top s (@closure_of A top t)))).
Axiom thm_SEPARATED_BETWEEN_FRONTIER_OF_EQ : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = ((@subset A s (@topspace A top)) /\ ((@DISJOINT A s t) /\ (@separated_between A top (@frontier_of A top s) t)))) /\ (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) = ((@subset A t (@topspace A top)) /\ ((@DISJOINT A s t) /\ (@separated_between A top s (@frontier_of A top t))))).
Axiom thm_SEPARATED_BETWEEN_FRONTIER_OF : forall {A : Type'}, (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A s (@topspace A top)) /\ (@DISJOINT A s t)) -> (@separated_between A top (@frontier_of A top s) t) = (@separated_between A top s t)) /\ (forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@subset A t (@topspace A top)) /\ (@DISJOINT A s t)) -> (@separated_between A top s (@frontier_of A top t)) = (@separated_between A top s t)).
Axiom thm_CONNECTED_SPACE_SEPARATED_BETWEEN : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall s : A -> Prop, forall t : A -> Prop, (@separated_between A top s t) -> (s = (@set0 A)) \/ (t = (@set0 A))).
Axiom thm_CONNECTED_SPACE_IMP_SEPARATED_BETWEEN_TRIVIAL : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, (@connected_space A top) -> (@separated_between A top s t) = (((s = (@set0 A)) /\ (@subset A t (@topspace A top))) \/ ((@subset A s (@topspace A top)) /\ (t = (@set0 A)))).
Axiom thm_connected_component_of : forall {_422455 : Type'}, forall top : Topology _422455, forall x : _422455, forall y : _422455, (@connected_component_of _422455 top x y) = (exists t : _422455 -> Prop, (@connected_in _422455 top t) /\ ((@IN _422455 x t) /\ (@IN _422455 y t))).
Axiom thm_connected_components_of : forall {_422485 : Type'}, forall top : Topology _422485, (@connected_components_of _422485 top) = (@GSPEC (_422485 -> Prop) (fun GEN_PVAR_1650 : _422485 -> Prop => exists x : _422485, @SETSPEC (_422485 -> Prop) GEN_PVAR_1650 (@IN _422485 x (@topspace _422485 top)) (@connected_component_of _422485 top x))).
Axiom thm_CONNECTED_COMPONENT_IN_TOPSPACE : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@connected_component_of A top x y) -> (@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top)).
Axiom thm_CONNECTED_COMPONENT_OF_REFL : forall {A : Type'}, forall top : Topology A, forall x : A, (@connected_component_of A top x x) = (@IN A x (@topspace A top)).
Axiom thm_CONNECTED_COMPONENT_OF_SYM : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@connected_component_of A top x y) = (@connected_component_of A top y x).
Axiom thm_CONNECTED_COMPONENT_OF_TRANS : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, forall z : A, ((@connected_component_of A top x y) /\ (@connected_component_of A top y z)) -> @connected_component_of A top x z.
Axiom thm_CONNECTED_COMPONENT_OF_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall x : A, forall y : A, (@connected_component_of A (@subtopology A top s) x y) -> @connected_component_of A top x y.
Axiom thm_CONNECTED_COMPONENT_OF_MONO : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall x : A, forall y : A, ((@connected_component_of A (@subtopology A top s) x y) /\ (@subset A s t)) -> @connected_component_of A (@subtopology A top t) x y.
Axiom thm_CONNECTED_COMPONENT_OF_SET : forall {A : Type'}, forall top : Topology A, forall x : A, (@connected_component_of A top x) = (@GSPEC A (fun GEN_PVAR_1651 : A => exists y : A, @SETSPEC A GEN_PVAR_1651 (exists t : A -> Prop, (@connected_in A top t) /\ ((@IN A x t) /\ (@IN A y t))) y)).
Axiom thm_CONNECTED_COMPONENT_OF_SUBSET_TOPSPACE : forall {_422739 : Type'}, forall top : Topology _422739, forall x : _422739, @subset _422739 (@connected_component_of _422739 top x) (@topspace _422739 top).
