Axiom thm_NEIGHBOURHOOD_BASE_OF_MONO : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, forall Q : (A -> Prop) -> Prop, ((forall s : A -> Prop, (P s) -> Q s) /\ (@neighbourhood_base_of A P top)) -> @neighbourhood_base_of A Q top.
Axiom thm_OPEN_NEIGHBOURHOOD_BASE_AT : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, forall x : A, (forall s : A -> Prop, ((P s) /\ (@IN A x s)) -> @open_in A top s) -> (@neighbourhood_base_at A x P top) = (forall w : A -> Prop, ((@open_in A top w) /\ (@IN A x w)) -> exists u : A -> Prop, (P u) /\ ((@IN A x u) /\ (@subset A u w))).
Axiom thm_OPEN_NEIGHBOURHOOD_BASE_OF : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, (forall s : A -> Prop, (P s) -> @open_in A top s) -> (@neighbourhood_base_of A P top) = (forall w : A -> Prop, forall x : A, ((@open_in A top w) /\ (@IN A x w)) -> exists u : A -> Prop, (P u) /\ ((@IN A x u) /\ (@subset A u w))).
Axiom thm_OPEN_IN_TOPOLOGY_NEIGHBOURHOOD_BASE_UNIQUE : forall {A : Type'}, forall top : Topology A, forall b : (A -> Prop) -> Prop, ((@open_in A top) = (@UNION_OF A (@ARBITRARY A) b)) = ((forall u : A -> Prop, (@IN (A -> Prop) u b) -> @open_in A top u) /\ (@neighbourhood_base_of A b top)).
Axiom thm_NEIGHBOURHOOD_BASE_OF_OPEN_SUBSET : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, forall s : A -> Prop, ((@neighbourhood_base_of A P top) /\ (@open_in A top s)) -> @neighbourhood_base_of A P (@subtopology A top s).
Axiom thm_NEIGHBOURHOOD_BASE_AT_TOPOLOGY_BASE : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall top : Topology A, forall b : (A -> Prop) -> Prop, forall x : A, ((@open_in A top) = (@UNION_OF A (@ARBITRARY A) b)) -> (@neighbourhood_base_at A x P top) = (forall w : A -> Prop, ((@IN (A -> Prop) w b) /\ (@IN A x w)) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((P v) /\ ((@IN A x u) /\ ((@subset A u v) /\ (@subset A v w))))).
Axiom thm_NEIGHBOURHOOD_BASE_OF_TOPOLOGY_BASE : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall top : Topology A, forall b : (A -> Prop) -> Prop, ((@open_in A top) = (@UNION_OF A (@ARBITRARY A) b)) -> (@neighbourhood_base_of A P top) = (forall w : A -> Prop, forall x : A, ((@IN (A -> Prop) w b) /\ (@IN A x w)) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((P v) /\ ((@IN A x u) /\ ((@subset A u v) /\ (@subset A v w))))).
Axiom thm_NEIGHBOURHOOD_BASE_AT_UNLOCALIZED : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, forall x : A, (forall s : A -> Prop, forall t : A -> Prop, ((P s) /\ ((@open_in A top t) /\ ((@IN A x t) /\ (@subset A t s)))) -> P t) -> (@neighbourhood_base_at A x P top) = ((@IN A x (@topspace A top)) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((P v) /\ ((@IN A x u) /\ ((@subset A u v) /\ (@subset A v (@topspace A top)))))).
Axiom thm_NEIGHBOURHOOD_BASE_OF_UNLOCALIZED : forall {A : Type'}, forall top : Topology A, forall P : (A -> Prop) -> Prop, (forall s : A -> Prop, forall t : A -> Prop, ((P s) /\ ((@open_in A top t) /\ ((~ (t = (@set0 A))) /\ (@subset A t s)))) -> P t) -> (@neighbourhood_base_of A P top) = (forall x : A, (@IN A x (@topspace A top)) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((P v) /\ ((@IN A x u) /\ ((@subset A u v) /\ (@subset A v (@topspace A top)))))).
Axiom thm_NEIGHBOURHOOD_BASE_AT_DISCRETE_TOPOLOGY : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall u : A -> Prop, forall x : A, (@neighbourhood_base_at A x P (@discrete_topology A u)) = ((@IN A x u) -> P (@INSERT A x (@set0 A))).
Axiom thm_NEIGHBOURHOOD_BASE_OF_DISCRETE_TOPOLOGY : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall u : A -> Prop, (@neighbourhood_base_of A P (@discrete_topology A u)) = (forall x : A, (@IN A x u) -> P (@INSERT A x (@set0 A))).
Axiom thm_NEIGHBOURHOOD_BASE_AT_WITH_SUBSET : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall top : Topology A, forall u : A -> Prop, forall x : A, ((@open_in A top u) /\ (@IN A x u)) -> (@neighbourhood_base_at A x P top) = (@neighbourhood_base_at A x (fun t : A -> Prop => (@subset A t u) /\ (P t)) top).
Axiom thm_NEIGHBOURHOOD_BASE_OF_WITH_SUBSET : forall {A : Type'}, forall P : (A -> Prop) -> Prop, forall top : Topology A, (@neighbourhood_base_of A P top) = (@neighbourhood_base_of A (fun t : A -> Prop => (@subset A t (@topspace A top)) /\ (P t)) top).
Axiom thm_SECOND_COUNTABLE_NEIGHBOURHOOD_BASE_ALT : forall {A : Type'}, forall top : Topology A, (@second_countable A top) = (exists b : (A -> Prop) -> Prop, (@COUNTABLE (A -> Prop) b) /\ ((forall v : A -> Prop, (@IN (A -> Prop) v b) -> @open_in A top v) /\ (@neighbourhood_base_of A b top))).
Axiom thm_FIRST_COUNTABLE_NEIGHBOURHOOD_BASE_ALT : forall {A : Type'}, forall top : Topology A, (@first_countable A top) = (forall x : A, (@IN A x (@topspace A top)) -> exists b : (A -> Prop) -> Prop, (@COUNTABLE (A -> Prop) b) /\ ((forall v : A -> Prop, (@IN (A -> Prop) v b) -> @open_in A top v) /\ (@neighbourhood_base_at A x b top))).
Axiom thm_SECOND_COUNTABLE_NEIGHBOURHOOD_BASE : forall {A : Type'}, forall top : Topology A, (@second_countable A top) = (exists b : (A -> Prop) -> Prop, (@COUNTABLE (A -> Prop) b) /\ (@neighbourhood_base_of A b top)).
Axiom thm_FIRST_COUNTABLE_NEIGHBOURHOOD_BASE : forall {A : Type'}, forall top : Topology A, (@first_countable A top) = (forall x : A, (@IN A x (@topspace A top)) -> exists b : (A -> Prop) -> Prop, (@COUNTABLE (A -> Prop) b) /\ (@neighbourhood_base_at A x b top)).
Axiom thm_t0_space : forall {A : Type'}, forall top : Topology A, (@t0_space A top) = (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (x = y)))) -> exists u : A -> Prop, (@open_in A top u) /\ (~ ((@IN A x u) = (@IN A y u)))).
Axiom thm_T0_SPACE_EXPANSIVE : forall {A : Type'}, forall top : Topology A, forall top' : Topology A, (((@topspace A top') = (@topspace A top)) /\ (forall u : A -> Prop, (@open_in A top u) -> @open_in A top' u)) -> (@t0_space A top) -> @t0_space A top'.
Axiom thm_T1_IMP_T0_SPACE : forall {A : Type'}, forall top : Topology A, (@t1_space A top) -> @t0_space A top.
Axiom thm_T1_EQ_SYMMETRIC_T0_SPACE_ALT : forall {A : Type'}, forall top : Topology A, (@t1_space A top) = ((@t0_space A top) /\ (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> (@IN A x (@closure_of A top (@INSERT A y (@set0 A)))) = (@IN A y (@closure_of A top (@INSERT A x (@set0 A)))))).
Axiom thm_T1_EQ_SYMMETRIC_T0_SPACE : forall {A : Type'}, forall top : Topology A, (@t1_space A top) = ((@t0_space A top) /\ (forall x : A, forall y : A, (@IN A x (@closure_of A top (@INSERT A y (@set0 A)))) = (@IN A y (@closure_of A top (@INSERT A x (@set0 A)))))).
Axiom thm_HAUSDORFF_IMP_T0_SPACE : forall {A : Type'}, forall top : Topology A, (@hausdorff_space A top) -> @t0_space A top.
Axiom thm_T0_SPACE : forall {A : Type'}, forall top : Topology A, (@t0_space A top) = (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (x = y)))) -> exists c : A -> Prop, (@closed_in A top c) /\ (~ ((@IN A x c) = (@IN A y c)))).
Axiom thm_HOMEOMORPHIC_T0_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@t0_space A top) = (@t0_space B top').
Axiom thm_T0_SPACE_CLOSURE_OF_SING : forall {A : Type'}, forall top : Topology A, (@t0_space A top) = (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ ((@closure_of A top (@INSERT A x (@set0 A))) = (@closure_of A top (@INSERT A y (@set0 A)))))) -> x = y).
Axiom thm_T0_SPACE_DISCRETE_TOPOLOGY : forall {A : Type'}, forall s : A -> Prop, @t0_space A (@discrete_topology A s).
Axiom thm_T0_SPACE_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, (@t0_space A top) -> @t0_space A (@subtopology A top u).
Axiom thm_T0_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') r) /\ (@t0_space A top)) -> @t0_space B top'.
Axiom thm_T0_SPACE_PROD_TOPOLOGY : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, (@t0_space (prod A B) (@prod_topology A B top1 top2)) = (((@topspace (prod A B) (@prod_topology A B top1 top2)) = (@set0 (prod A B))) \/ ((@t0_space A top1) /\ (@t0_space B top2))).
Axiom thm_T0_SPACE_PRODUCT_TOPOLOGY : forall {A K : Type'}, forall tops : K -> Topology A, forall k : K -> Prop, (@t0_space (K -> A) (@product_topology A K k tops)) = (((@topspace (K -> A) (@product_topology A K k tops)) = (@set0 (K -> A))) \/ (forall i : K, (@IN K i k) -> @t0_space A (tops i))).
Axiom thm_kolmogorov_quotient : forall {A : Type'}, forall top : Topology A, (@kolmogorov_quotient A top) = (fun x : A => @ε A (fun y : A => forall u : A -> Prop, (@open_in A top u) -> (@IN A y u) = (@IN A x u))).
Axiom thm_KOLMOGOROV_QUOTIENT_IN_OPEN : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, forall x : A, (@open_in A top u) -> (@IN A (@kolmogorov_quotient A top x) u) = (@IN A x u).
Axiom thm_KOLMOGOROV_QUOTIENT_IN_TOPSPACE : forall {A : Type'}, forall top : Topology A, forall x : A, (@IN A (@kolmogorov_quotient A top x) (@topspace A top)) = (@IN A x (@topspace A top)).
Axiom thm_KOLMOGOROV_QUOTIENT_IN_CLOSED : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall x : A, (@closed_in A top c) -> (@IN A (@kolmogorov_quotient A top x) c) = (@IN A x c).
Axiom thm_CONTINUOUS_MAP_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @continuous_map A A (@pair (Topology A) (Topology A) top top) (@kolmogorov_quotient A top).
Axiom thm_OPEN_MAP_KOLMOGOROV_QUOTIENT_EXPLICIT : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, (@open_in A top u) -> (@IMAGE A A (@kolmogorov_quotient A top) u) = (@setI A (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)) u).
Axiom thm_OPEN_MAP_KOLMOGOROV_QUOTIENT_GEN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, @open_map A A (@pair (Topology A) (Topology A) (@subtopology A top s) (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) s))) (@kolmogorov_quotient A top).
Axiom thm_OPEN_MAP_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @open_map A A (@pair (Topology A) (Topology A) top (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)))) (@kolmogorov_quotient A top).
Axiom thm_CLOSED_MAP_KOLMOGOROV_QUOTIENT_EXPLICIT : forall {A : Type'}, forall top : Topology A, forall u : A -> Prop, (@closed_in A top u) -> (@IMAGE A A (@kolmogorov_quotient A top) u) = (@setI A (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)) u).
Axiom thm_CLOSED_MAP_KOLMOGOROV_QUOTIENT_GEN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, @closed_map A A (@pair (Topology A) (Topology A) (@subtopology A top s) (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) s))) (@kolmogorov_quotient A top).
Axiom thm_CLOSED_MAP_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @closed_map A A (@pair (Topology A) (Topology A) top (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)))) (@kolmogorov_quotient A top).
Axiom thm_QUOTIENT_MAP_KOLMOGOROV_QUOTIENT_GEN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, @quotient_map A A (@pair (Topology A) (Topology A) (@subtopology A top s) (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) s))) (@kolmogorov_quotient A top).
Axiom thm_QUOTIENT_MAP_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @quotient_map A A (@pair (Topology A) (Topology A) top (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)))) (@kolmogorov_quotient A top).
Axiom thm_KOLMOGOROV_QUOTIENT_EQ : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, ((@kolmogorov_quotient A top x) = (@kolmogorov_quotient A top y)) = (forall u : A -> Prop, (@open_in A top u) -> (@IN A x u) = (@IN A y u)).
Axiom thm_KOLMOGOROV_QUOTIENT_EQ_ALT : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, ((@kolmogorov_quotient A top x) = (@kolmogorov_quotient A top y)) = (forall u : A -> Prop, (@closed_in A top u) -> (@IN A x u) = (@IN A y u)).
Axiom thm_KOLMOGOROV_QUOTIENT_CONTINUOUS_MAP : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall x : A, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@t0_space B top') /\ (@IN A x (@topspace A top)))) -> (f (@kolmogorov_quotient A top x)) = (f x).
Axiom thm_T0_SPACE_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @t0_space A (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top))).
Axiom thm_KOLMOGOROV_QUOTIENT_ID : forall {A : Type'}, forall top : Topology A, forall x : A, ((@t0_space A top) /\ (@IN A x (@topspace A top))) -> (@kolmogorov_quotient A top x) = x.
Axiom thm_KOLMOGOROV_QUOTIENT_IDEMP : forall {A : Type'}, forall top : Topology A, forall x : A, (@kolmogorov_quotient A top (@kolmogorov_quotient A top x)) = (@kolmogorov_quotient A top x).
Axiom thm_RETRACTION_MAPS_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @retraction_maps A A (@pair (Topology A) (Topology A) top (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)))) (@pair (A -> A) (A -> A) (@kolmogorov_quotient A top) (@I A)).
Axiom thm_RETRACTION_MAP_KOLMOGOROV_QUOTIENT : forall {A : Type'}, forall top : Topology A, @retraction_map A A (@pair (Topology A) (Topology A) top (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)))) (@kolmogorov_quotient A top).
Axiom thm_RETRACT_OF_SPACE_KOLMOGOROV_QUOTIENT_IMAGE : forall {A : Type'}, forall top : Topology A, @retract_of_space A (@IMAGE A A (@kolmogorov_quotient A top) (@topspace A top)) top.
Axiom thm_KOLMOGOROV_QUOTIENT_LIFT_EXISTS : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall s : A -> Prop, ((@subset A s (@topspace A top)) /\ ((@t0_space B top') /\ (@continuous_map A B (@pair (Topology A) (Topology B) (@subtopology A top s) top') f))) -> exists g : A -> B, (@continuous_map A B (@pair (Topology A) (Topology B) (@subtopology A top (@IMAGE A A (@kolmogorov_quotient A top) s)) top') g) /\ (forall x : A, (@IN A x s) -> (g (@kolmogorov_quotient A top x)) = (f x)).
Axiom thm_regular_space : forall {A : Type'}, forall top : Topology A, (@regular_space A top) = (forall c : A -> Prop, forall a : A, ((@closed_in A top c) /\ (@IN A a (@setD A (@topspace A top) c))) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((@open_in A top v) /\ ((@IN A a u) /\ ((@subset A c v) /\ (@DISJOINT A u v))))).
Axiom thm_HOMEOMORPHIC_REGULAR_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@regular_space A top) = (@regular_space B top').
Axiom thm_REGULAR_SPACE : forall {A : Type'}, forall top : Topology A, (@regular_space A top) = (forall c : A -> Prop, forall a : A, ((@closed_in A top c) /\ (@IN A a (@setD A (@topspace A top) c))) -> exists u : A -> Prop, (@open_in A top u) /\ ((@IN A a u) /\ (@DISJOINT A c (@closure_of A top u)))).
Axiom thm_NEIGHBOURHOOD_BASE_OF_CLOSED_IN : forall {A : Type'}, forall top : Topology A, (@neighbourhood_base_of A (@closed_in A top) top) = (@regular_space A top).
Axiom thm_REGULAR_SPACE_DISCRETE_TOPOLOGY : forall {A : Type'}, forall s : A -> Prop, @regular_space A (@discrete_topology A s).
Axiom thm_REGULAR_SPACE_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@regular_space A top) -> @regular_space A (@subtopology A top s).
Axiom thm_REGULAR_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') r) /\ (@regular_space A top)) -> @regular_space B top'.
Axiom thm_REGULAR_T0_IMP_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, ((@regular_space A top) /\ (@t0_space A top)) -> @hausdorff_space A top.
Axiom thm_REGULAR_T0_EQ_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, (@regular_space A top) -> (@t0_space A top) = (@hausdorff_space A top).
Axiom thm_REGULAR_T1_IMP_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, ((@regular_space A top) /\ (@t1_space A top)) -> @hausdorff_space A top.
Axiom thm_REGULAR_T1_EQ_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, (@regular_space A top) -> (@t1_space A top) = (@hausdorff_space A top).
Axiom thm_COMPACT_HAUSDORFF_IMP_REGULAR_SPACE : forall {A : Type'}, forall top : Topology A, ((@compact_space A top) /\ (@hausdorff_space A top)) -> @regular_space A top.
Axiom thm_NEIGHBOURHOOD_BASE_OF_CLOSED_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, ((@regular_space A top) /\ (@hausdorff_space A top)) = (@neighbourhood_base_of A (fun c : A -> Prop => (@closed_in A top c) /\ (@hausdorff_space A (@subtopology A top c))) top).
Axiom thm_LOCALLY_COMPACT_IMP_KC_EQ_HAUSDORFF_SPACE : forall {A : Type'}, forall top : Topology A, (@neighbourhood_base_of A (@compact_in A top) top) -> (@kc_space A top) = (@hausdorff_space A top).
Axiom thm_REGULAR_SPACE_MTOPOLOGY : forall {A : Type'}, forall m : Metric A, @regular_space A (@mtopology A m).
Axiom thm_METRIZABLE_IMP_REGULAR_SPACE : forall {A : Type'}, forall top : Topology A, (@metrizable_space A top) -> @regular_space A top.
Axiom thm_REGULAR_SPACE_COMPACT_CLOSED_SEPARATION : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, ((@regular_space A top) /\ ((@compact_in A top s) /\ ((@closed_in A top t) /\ (@DISJOINT A s t)))) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((@open_in A top v) /\ ((@subset A s u) /\ ((@subset A t v) /\ (@DISJOINT A u v)))).
Axiom thm_REGULAR_SPACE_COMPACT_CLOSED_SETS : forall {A : Type'}, forall top : Topology A, (@regular_space A top) = (forall s : A -> Prop, forall t : A -> Prop, ((@compact_in A top s) /\ ((@closed_in A top t) /\ (@DISJOINT A s t))) -> exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((@open_in A top v) /\ ((@subset A s u) /\ ((@subset A t v) /\ (@DISJOINT A u v))))).
Axiom thm_REGULAR_SPACE_PROD_TOPOLOGY : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, (@regular_space (prod A B) (@prod_topology A B top1 top2)) = (((@topspace (prod A B) (@prod_topology A B top1 top2)) = (@set0 (prod A B))) \/ ((@regular_space A top1) /\ (@regular_space B top2))).
