Axiom thm_CLOSED_MAP_PAIRED_GEN : forall {A B C : Type'}, forall top : Topology A, forall top1 : Topology B, forall top2 : Topology C, forall f : A -> B, forall g : A -> C, ((@closed_map A B (@pair (Topology A) (Topology B) top top1) f) /\ ((@closed_map A C (@pair (Topology A) (Topology C) top top2) g) /\ (((@regular_space B top1) /\ ((@continuous_map A B (@pair (Topology A) (Topology B) top top1) f) /\ (forall z : C, (@IN C z (@topspace C top2)) -> @closed_in A top (@GSPEC A (fun GEN_PVAR_1680 : A => exists x : A, @SETSPEC A GEN_PVAR_1680 ((@IN A x (@topspace A top)) /\ ((g x) = z)) x))))) \/ ((@regular_space C top2) /\ ((@continuous_map A C (@pair (Topology A) (Topology C) top top2) g) /\ (forall y : B, (@IN B y (@topspace B top1)) -> @closed_in A top (@GSPEC A (fun GEN_PVAR_1681 : A => exists x : A, @SETSPEC A GEN_PVAR_1681 ((@IN A x (@topspace A top)) /\ ((f x) = y)) x)))))))) -> @closed_map A (prod B C) (@pair (Topology A) (Topology (prod B C)) top (@prod_topology B C top1 top2)) (fun x : A => @pair B C (f x) (g x)).
