Axiom thm_LIMIT_SEQUENTIALLY_OFFSET : forall {A : Type'}, forall top : Topology A, forall f : nat -> A, forall l : A, forall k : nat, (@limit nat A top f l sequentially) -> @limit nat A top (fun i : nat => f (addn i k)) l sequentially.
Axiom thm_LIMIT_SEQUENTIALLY_OFFSET_REV : forall {A : Type'}, forall top : Topology A, forall f : nat -> A, forall l : A, forall k : nat, (@limit nat A top (fun i : nat => f (addn i k)) l sequentially) -> @limit nat A top f l sequentially.
Axiom thm_LIMIT_ATPOINTOF : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall x : A, forall y : B, (@limit A B top' f y (@atpointof A top x)) = ((@IN B y (@topspace B top')) /\ ((@IN A x (@topspace A top)) -> forall v : B -> Prop, ((@open_in B top' v) /\ (@IN B y v)) -> exists u : A -> Prop, (@open_in A top u) /\ ((@IN A x u) /\ (@subset B (@IMAGE A B f (@DELETE A u x)) v)))).
Axiom thm_LIMIT_ATPOINTOF_SELF : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, forall f : A -> B, forall a : A, (@limit A B top2 f (f a) (@atpointof A top1 a)) = ((@IN B (f a) (@topspace B top2)) /\ ((@IN A a (@topspace A top1)) -> forall v : B -> Prop, ((@open_in B top2 v) /\ (@IN B (f a) v)) -> exists u : A -> Prop, (@open_in A top1 u) /\ ((@IN A a u) /\ (@subset B (@IMAGE A B f u) v)))).
Axiom thm_LIMIT_TRIVIAL : forall {A B : Type'}, forall net' : net A, forall f : A -> B, forall top : Topology B, forall y : B, ((@trivial_limit A net') /\ (@IN B y (@topspace B top))) -> @limit A B top f y net'.
Axiom thm_LIMIT_TRANSFORM_EVENTUALLY : forall {A B : Type'}, forall net' : net A, forall top : Topology B, forall f : A -> B, forall g : A -> B, forall l : B, ((@eventually A (fun x : A => (f x) = (g x)) net') /\ (@limit A B top f l net')) -> @limit A B top g l net'.
Axiom thm_CONTINUOUS_MAP_LIMIT : forall {A B C : Type'}, forall net' : net A, forall top : Topology B, forall top' : Topology C, forall f : A -> B, forall g : B -> C, forall l : B, ((@continuous_map B C (@pair (Topology B) (Topology C) top top') g) /\ (@limit A B top f l net')) -> @limit A C top' (@o A B C g f) (g l) net'.
Axiom thm_LIMIT_PAIRWISE : forall {A B C : Type'}, forall net' : net C, forall top1 : Topology A, forall top2 : Topology B, forall f : C -> prod A B, forall l : prod A B, (@limit C (prod A B) (@prod_topology A B top1 top2) f l net') = ((@limit C A top1 (@o C (prod A B) A (@fst A B) f) (@fst A B l) net') /\ (@limit C B top2 (@o C (prod A B) B (@snd A B) f) (@snd A B l) net')).
Axiom thm_LIMIT_COMPONENTWISE : forall {A C K : Type'}, forall net' : net C, forall tops : K -> Topology A, forall t : K -> Prop, forall f : C -> K -> A, forall l : K -> A, (@limit C (K -> A) (@product_topology A K t tops) f l net') = ((@EXTENSIONAL K A t l) /\ ((@eventually C (fun a : C => @IN (K -> A) (f a) (@topspace (K -> A) (@product_topology A K t tops))) net') /\ (forall k : K, (@IN K k t) -> @limit C A (tops k) (fun c : C => f c k) (l k) net'))).
Axiom thm_COMPACT_IN_SEQUENCE_WITH_LIMIT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall a : nat -> A, forall l : A, ((@limit nat A top a l sequentially) /\ ((@subset A s (@IMAGE nat A a (@setT nat))) /\ (@subset A s (@topspace A top)))) -> @compact_in A top (@INSERT A l s).
Axiom thm_LIMIT_HAUSDORFF_UNIQUE : forall {A B : Type'}, forall net' : net A, forall top : Topology B, forall f : A -> B, forall l1 : B, forall l2 : B, ((~ (@trivial_limit A net')) /\ ((@hausdorff_space B top) /\ ((@limit A B top f l1 net') /\ (@limit A B top f l2 net')))) -> l1 = l2.
Axiom thm_LIMIT_KC_UNIQUE : forall {A : Type'}, forall top : Topology A, forall f : nat -> A, forall l1 : A, forall l2 : A, ((@kc_space A top) /\ ((@limit nat A top f l1 sequentially) /\ (@limit nat A top f l2 sequentially))) -> l1 = l2.
Axiom thm_LIMIT_IN_MSPACE : forall {A B : Type'}, forall net' : net A, forall m : Metric B, forall f : A -> B, forall l : B, (@limit A B (@mtopology B m) f l net') -> @IN B l (@mspace B m).
Axiom thm_LIMIT_METRIC_UNIQUE : forall {A B : Type'}, forall net' : net A, forall m : Metric B, forall f : A -> B, forall l1 : B, forall l2 : B, ((~ (@trivial_limit A net')) /\ ((@limit A B (@mtopology B m) f l1 net') /\ (@limit A B (@mtopology B m) f l2 net'))) -> l1 = l2.
Axiom thm_LIMIT_METRIC : forall {A B : Type'}, forall m : Metric B, forall f : A -> B, forall l : B, forall net' : net A, (@limit A B (@mtopology B m) f l net') = ((@IN B l (@mspace B m)) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> @eventually A (fun x : A => (@IN B (f x) (@mspace B m)) /\ (ltr (@mdist B m (@pair B B (f x) l)) e)) net')).
Axiom thm_LIMIT_METRIC_SEQUENTIALLY : forall {A : Type'}, forall m : Metric A, forall f : nat -> A, forall l : A, (@limit nat A (@mtopology A m) f l sequentially) = ((@IN A l (@mspace A m)) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists N' : nat, forall n : nat, (leqn N' n) -> (@IN A (f n) (@mspace A m)) /\ (ltr (@mdist A m (@pair A A (f n) l)) e))).
Axiom thm_LIMIT_IN_CLOSED_IN : forall {A B : Type'}, forall net' : net A, forall top : Topology B, forall s : B -> Prop, forall f : A -> B, forall l : B, ((~ (@trivial_limit A net')) /\ ((@limit A B top f l net') /\ ((@closed_in B top s) /\ (@eventually A (fun x : A => @IN B (f x) s) net')))) -> @IN B l s.
Axiom thm_LIMIT_SUBMETRIC_IFF : forall {A B : Type'}, forall net' : net A, forall m : Metric B, forall s : B -> Prop, forall f : A -> B, forall l : B, (@limit A B (@mtopology B (@submetric B m s)) f l net') = ((@IN B l s) /\ ((@eventually A (fun x : A => @IN B (f x) s) net') /\ (@limit A B (@mtopology B m) f l net'))).
Axiom thm_METRIC_CLOSED_IN_IFF_SEQUENTIALLY_CLOSED : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@closed_in A (@mtopology A m) s) = ((@subset A s (@mspace A m)) /\ (forall a : nat -> A, forall l : A, ((forall n : nat, @IN A (a n) s) /\ (@limit nat A (@mtopology A m) a l sequentially)) -> @IN A l s)).
Axiom thm_LIMIT_ATPOINTOF_METRIC : forall {A B : Type'}, forall m : Metric A, forall top : Topology B, forall f : A -> B, forall x : A, forall y : B, (@limit A B top f y (@atpointof A (@mtopology A m) x)) = ((@IN B y (@topspace B top)) /\ ((@IN A x (@mspace A m)) -> forall v : B -> Prop, ((@open_in B top v) /\ (@IN B y v)) -> exists d : R, (ltr (R_of_nat (NUMERAL O)) d) /\ (forall x' : A, ((@IN A x' (@mspace A m)) /\ ((ltr (R_of_nat (NUMERAL O)) (@mdist A m (@pair A A x' x))) /\ (ltr (@mdist A m (@pair A A x' x)) d))) -> @IN B (f x') v))).
Axiom thm_LIMIT_METRIC_DIST_NULL : forall {A K : Type'}, forall net' : net K, forall m : Metric A, forall f : K -> A, forall l : A, (@limit K A (@mtopology A m) f l net') = ((@IN A l (@mspace A m)) /\ ((@eventually K (fun x : K => @IN A (f x) (@mspace A m)) net') /\ (@limit K R euclideanreal (fun x : K => @mdist A m (@pair A A (f x) l)) (R_of_nat (NUMERAL O)) net'))).
Axiom thm_LIMIT_NULL_REAL : forall {A : Type'}, forall net' : net A, forall f : A -> R, (@limit A R euclideanreal f (R_of_nat (NUMERAL O)) net') = (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> @eventually A (fun a : A => ltr (normr (f a)) e) net').
Axiom thm_LIMIT_NULL_REAL_ABS : forall {A : Type'}, forall net' : net A, forall f : A -> R, (@limit A R euclideanreal (fun a : A => normr (f a)) (R_of_nat (NUMERAL O)) net') = (@limit A R euclideanreal f (R_of_nat (NUMERAL O)) net').
Axiom thm_LIMIT_NULL_REAL_COMPARISON : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, ((@limit A R euclideanreal f (R_of_nat (NUMERAL O)) net') /\ (@eventually A (fun a : A => ler (normr (g a)) (normr (f a))) net')) -> @limit A R euclideanreal g (R_of_nat (NUMERAL O)) net'.
Axiom thm_LIMIT_NULL_REAL_HARMONIC_OFFSET : forall a : R, @limit nat R euclideanreal (fun n : nat => invr (addr (R_of_nat n) a)) (R_of_nat (NUMERAL O)) sequentially.
Axiom thm_EVENTUALLY_ATPOINTOF_WITHIN_SEQUENTIALLY : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall s : A -> Prop, forall a : A, (@eventually A P (@within A (@atpointof A (@mtopology A met) a) s)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A met)) a)) /\ (@limit nat A (@mtopology A met) x a sequentially)) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_EVENTUALLY_ATPOINTOF_WITHIN_SEQUENTIALLY_DECREASING : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall s : A -> Prop, forall a : A, (@eventually A P (@within A (@atpointof A (@mtopology A met) a) s)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A met)) a)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A met (@pair A A (x n) a)) (@mdist A met (@pair A A (x m) a))) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A met) x a sequentially)))) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_EVENTUALLY_ATPOINTOF_WITHIN_SEQUENTIALLY_INJ : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall s : A -> Prop, forall a : A, (@eventually A P (@within A (@atpointof A (@mtopology A met) a) s)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A met)) a)) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A met) x a sequentially))) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_EVENTUALLY_ATPOINTOF_SEQUENTIALLY : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall a : A, (@eventually A P (@atpointof A (@mtopology A met) a)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A met) a)) /\ (@limit nat A (@mtopology A met) x a sequentially)) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_EVENTUALLY_ATPOINTOF_SEQUENTIALLY_INJ : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall a : A, (@eventually A P (@atpointof A (@mtopology A met) a)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A met) a)) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A met) x a sequentially))) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_EVENTUALLY_ATPOINTOF_SEQUENTIALLY_DECREASING : forall {A : Type'}, forall met : Metric A, forall P : A -> Prop, forall a : A, (@eventually A P (@atpointof A (@mtopology A met) a)) = (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A met) a)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A met (@pair A A (x n) a)) (@mdist A met (@pair A A (x m) a))) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A met) x a sequentially)))) -> @eventually nat (fun n : nat => P (x n)) sequentially).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY_WITHIN : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall s : A -> Prop, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@within A (@atpointof A (@mtopology A m1) a) s)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A m1)) a)) /\ (@limit nat A (@mtopology A m1) x a sequentially)) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY_WITHIN_INJ : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall s : A -> Prop, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@within A (@atpointof A (@mtopology A m1) a) s)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A m1)) a)) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A m1) x a sequentially))) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY_WITHIN_DECREASING : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall s : A -> Prop, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@within A (@atpointof A (@mtopology A m1) a) s)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@setI A s (@mspace A m1)) a)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A m1 (@pair A A (x n) a)) (@mdist A m1 (@pair A A (x m) a))) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A m1) x a sequentially)))) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@atpointof A (@mtopology A m1) a)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A m1) a)) /\ (@limit nat A (@mtopology A m1) x a sequentially)) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY_INJ : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@atpointof A (@mtopology A m1) a)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A m1) a)) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A m1) x a sequentially))) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_LIMIT_ATPOINTOF_SEQUENTIALLY_DECREASING : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, forall a : A, forall l : B, (@limit A B (@mtopology B m2) f l (@atpointof A (@mtopology A m1) a)) = ((@IN B l (@mspace B m2)) /\ (forall x : nat -> A, ((forall n : nat, @IN A (x n) (@DELETE A (@mspace A m1) a)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A m1 (@pair A A (x n) a)) (@mdist A m1 (@pair A A (x m) a))) /\ ((forall m : nat, forall n : nat, ((x m) = (x n)) = (m = n)) /\ (@limit nat A (@mtopology A m1) x a sequentially)))) -> @limit nat B (@mtopology B m2) (@o nat A B f x) l sequentially)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1792 : A => exists x : A, @SETSPEC A GEN_PVAR_1792 ((@IN A x (@mspace A met)) /\ (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A (@setI A s (@mspace A met)) x)) /\ (@limit nat A (@mtopology A met) f x sequentially))) x)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY_ALT : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1793 : A => exists x : A, @SETSPEC A GEN_PVAR_1793 (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A s x)) /\ (@limit nat A (@mtopology A met) f x sequentially)) x)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY_INJ : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1794 : A => exists x : A, @SETSPEC A GEN_PVAR_1794 ((@IN A x (@mspace A met)) /\ (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A (@setI A s (@mspace A met)) x)) /\ ((forall m : nat, forall n : nat, ((f m) = (f n)) = (m = n)) /\ (@limit nat A (@mtopology A met) f x sequentially)))) x)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY_INJ_ALT : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1795 : A => exists x : A, @SETSPEC A GEN_PVAR_1795 (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A s x)) /\ ((forall m : nat, forall n : nat, ((f m) = (f n)) = (m = n)) /\ (@limit nat A (@mtopology A met) f x sequentially))) x)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY_DECREASING : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1796 : A => exists x : A, @SETSPEC A GEN_PVAR_1796 ((@IN A x (@mspace A met)) /\ (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A (@setI A s (@mspace A met)) x)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A met (@pair A A (f n) x)) (@mdist A met (@pair A A (f m) x))) /\ ((forall m : nat, forall n : nat, ((f m) = (f n)) = (m = n)) /\ (@limit nat A (@mtopology A met) f x sequentially))))) x)).
Axiom thm_DERIVED_SET_OF_SEQUENTIALLY_DECREASING_ALT : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@derived_set_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1797 : A => exists x : A, @SETSPEC A GEN_PVAR_1797 (exists f : nat -> A, (forall n : nat, @IN A (f n) (@DELETE A s x)) /\ ((forall m : nat, forall n : nat, (ltn m n) -> ltr (@mdist A met (@pair A A (f n) x)) (@mdist A met (@pair A A (f m) x))) /\ ((forall m : nat, forall n : nat, ((f m) = (f n)) = (m = n)) /\ (@limit nat A (@mtopology A met) f x sequentially)))) x)).
Axiom thm_CLOSURE_OF_SEQUENTIALLY : forall {A : Type'}, forall met : Metric A, forall s : A -> Prop, (@closure_of A (@mtopology A met) s) = (@GSPEC A (fun GEN_PVAR_1798 : A => exists x : A, @SETSPEC A GEN_PVAR_1798 ((@IN A x (@mspace A met)) /\ (exists f : nat -> A, (forall n : nat, @IN A (f n) (@setI A s (@mspace A met))) /\ (@limit nat A (@mtopology A met) f x sequentially))) x)).
Axiom thm_LIMIT_REAL_MUL : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ (@limit A R euclideanreal g m net')) -> @limit A R euclideanreal (fun x : A => mulr (f x) (g x)) (mulr l m) net'.
Axiom thm_LIMIT_REAL_LMUL : forall {A : Type'}, forall net' : net A, forall c : R, forall f : A -> R, forall l : R, (@limit A R euclideanreal f l net') -> @limit A R euclideanreal (fun x : A => mulr c (f x)) (mulr c l) net'.
Axiom thm_LIMIT_REAL_LMUL_EQ : forall {A : Type'}, forall net' : net A, forall c : R, forall f : A -> R, forall l : R, (@limit A R euclideanreal (fun x : A => mulr c (f x)) (mulr c l) net') = ((c = (R_of_nat (NUMERAL O))) \/ (@limit A R euclideanreal f l net')).
Axiom thm_LIMIT_REAL_RMUL : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall c : R, forall l : R, (@limit A R euclideanreal f l net') -> @limit A R euclideanreal (fun x : A => mulr (f x) c) (mulr l c) net'.
Axiom thm_LIMIT_REAL_RMUL_EQ : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall c : R, forall l : R, (@limit A R euclideanreal (fun x : A => mulr (f x) c) (mulr l c) net') = ((c = (R_of_nat (NUMERAL O))) \/ (@limit A R euclideanreal f l net')).
Axiom thm_LIMIT_REAL_NEG : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall l : R, (@limit A R euclideanreal f l net') -> @limit A R euclideanreal (fun x : A => oppr (f x)) (oppr l) net'.
Axiom thm_LIMIT_REAL_NEG_EQ : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall l : R, (@limit A R euclideanreal (fun x : A => oppr (f x)) l net') = (@limit A R euclideanreal f (oppr l) net').
Axiom thm_LIMIT_REAL_ADD : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ (@limit A R euclideanreal g m net')) -> @limit A R euclideanreal (fun x : A => addr (f x) (g x)) (addr l m) net'.
Axiom thm_LIMIT_REAL_SUB : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ (@limit A R euclideanreal g m net')) -> @limit A R euclideanreal (fun x : A => subr (f x) (g x)) (subr l m) net'.
Axiom thm_LIMIT_REAL_ABS : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall l : R, (@limit A R euclideanreal f l net') -> @limit A R euclideanreal (fun x : A => normr (f x)) (normr l) net'.
Axiom thm_LIMIT_REAL_MAX : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ (@limit A R euclideanreal g m net')) -> @limit A R euclideanreal (fun x : A => maxr (f x) (g x)) (maxr l m) net'.
Axiom thm_LIMIT_REAL_MIN : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ (@limit A R euclideanreal g m net')) -> @limit A R euclideanreal (fun x : A => minr (f x) (g x)) (minr l m) net'.
Axiom thm_LIMIT_SUM : forall {A K : Type'}, forall net' : net A, forall f : A -> K -> R, forall l : K -> R, forall k : K -> Prop, ((@finite_set K k) /\ (forall i : K, (@IN K i k) -> @limit A R euclideanreal (fun x : A => f x i) (l i) net')) -> @limit A R euclideanreal (fun x : A => @sum K k (f x)) (@sum K k l) net'.
Axiom thm_LIMIT_PRODUCT : forall {A K : Type'}, forall net' : net A, forall f : A -> K -> R, forall l : K -> R, forall k : K -> Prop, ((@finite_set K k) /\ (forall i : K, (@IN K i k) -> @limit A R euclideanreal (fun x : A => f x i) (l i) net')) -> @limit A R euclideanreal (fun x : A => @product K k (f x)) (@product K k l) net'.
Axiom thm_LIMIT_REAL_INV : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall l : R, ((@limit A R euclideanreal f l net') /\ (~ (l = (R_of_nat (NUMERAL O))))) -> @limit A R euclideanreal (fun x : A => invr (f x)) (invr l) net'.
Axiom thm_LIMIT_REAL_DIV : forall {A : Type'}, forall net' : net A, forall f : A -> R, forall g : A -> R, forall l : R, forall m : R, ((@limit A R euclideanreal f l net') /\ ((@limit A R euclideanreal g m net') /\ (~ (m = (R_of_nat (NUMERAL O)))))) -> @limit A R euclideanreal (fun x : A => divr (f x) (g x)) (divr l m) net'.
Axiom thm_LIMIT_INF : forall {A K : Type'}, forall net' : net A, forall f : A -> K -> R, forall l : K -> R, forall k : K -> Prop, ((@finite_set K k) /\ (forall i : K, (@IN K i k) -> @limit A R euclideanreal (fun x : A => f x i) (l i) net')) -> @limit A R euclideanreal (fun x : A => inf (@GSPEC R (fun GEN_PVAR_1799 : R => exists i : K, @SETSPEC R GEN_PVAR_1799 (@IN K i k) (f x i)))) (inf (@GSPEC R (fun GEN_PVAR_1800 : R => exists i : K, @SETSPEC R GEN_PVAR_1800 (@IN K i k) (l i)))) net'.
Axiom thm_LIMIT_SUP : forall {A K : Type'}, forall net' : net A, forall f : A -> K -> R, forall l : K -> R, forall k : K -> Prop, ((@finite_set K k) /\ (forall i : K, (@IN K i k) -> @limit A R euclideanreal (fun x : A => f x i) (l i) net')) -> @limit A R euclideanreal (fun x : A => sup (@GSPEC R (fun GEN_PVAR_1801 : R => exists i : K, @SETSPEC R GEN_PVAR_1801 (@IN K i k) (f x i)))) (sup (@GSPEC R (fun GEN_PVAR_1802 : R => exists i : K, @SETSPEC R GEN_PVAR_1802 (@IN K i k) (l i)))) net'.
Axiom thm_cauchy_in : forall {A : Type'}, forall m : Metric A, forall s : nat -> A, (@cauchy_in A m s) = ((forall n : nat, @IN A (s n) (@mspace A m)) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists N' : nat, forall n : nat, forall n' : nat, ((leqn N' n) /\ (leqn N' n')) -> ltr (@mdist A m (@pair A A (s n) (s n'))) e)).
Axiom thm_mcomplete : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall s : nat -> A, (@cauchy_in A m s) -> exists x : A, @limit nat A (@mtopology A m) s x sequentially).
Axiom thm_MCOMPLETE : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall s : nat -> A, ((@eventually nat (fun n : nat => @IN A (s n) (@mspace A m)) sequentially) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists N' : nat, forall n : nat, forall n' : nat, ((leqn N' n) /\ (leqn N' n')) -> ltr (@mdist A m (@pair A A (s n) (s n'))) e)) -> exists x : A, @limit nat A (@mtopology A m) s x sequentially).
Axiom thm_MCOMPLETE_EMPTY_MSPACE : forall {A : Type'}, forall m : Metric A, ((@mspace A m) = (@set0 A)) -> @mcomplete A m.
Axiom thm_MCOMPLETE_SUBMETRIC_EMPTY : forall {A : Type'}, forall m : Metric A, @mcomplete A (@submetric A m (@set0 A)).
Axiom thm_CAUCHY_IN_SUBMETRIC : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall x : nat -> A, (@cauchy_in A (@submetric A m s) x) = ((forall n : nat, @IN A (x n) s) /\ (@cauchy_in A m x)).
Axiom thm_CAUCHY_IN_CONST : forall {A : Type'}, forall m : Metric A, forall a : A, (@cauchy_in A m (fun n : nat => a)) = (@IN A a (@mspace A m)).
Axiom thm_CONVERGENT_IMP_CAUCHY_IN : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, forall l : A, ((forall n : nat, @IN A (x n) (@mspace A m)) /\ (@limit nat A (@mtopology A m) x l sequentially)) -> @cauchy_in A m x.
Axiom thm_MCOMPLETE_ALT : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall s : nat -> A, (@cauchy_in A m s) = ((forall n : nat, @IN A (s n) (@mspace A m)) /\ (exists x : A, @limit nat A (@mtopology A m) s x sequentially))).
Axiom thm_CAUCHY_IN_SUBSEQUENCE : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, forall r : nat -> nat, ((forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@cauchy_in A m x)) -> @cauchy_in A m (@o nat nat A x r).
Axiom thm_CAUCHY_IN_OFFSET : forall {A : Type'}, forall m : Metric A, forall a : nat, forall x : nat -> A, ((forall n : nat, (ltn n a) -> @IN A (x n) (@mspace A m)) /\ (@cauchy_in A m (fun n : nat => x (addn a n)))) -> @cauchy_in A m x.
Axiom thm_CAUCHY_IN_CONVERGENT_SUBSEQUENCE : forall {A : Type'}, forall m : Metric A, forall r : nat -> nat, forall a : A, forall x : nat -> A, ((@cauchy_in A m x) /\ ((forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@limit nat A (@mtopology A m) (@o nat nat A x r) a sequentially))) -> @limit nat A (@mtopology A m) x a sequentially.
Axiom thm_CLOSED_IN_MCOMPLETE_IMP_MCOMPLETE : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, ((@closed_in A (@mtopology A m) s) /\ (@mcomplete A m)) -> @mcomplete A (@submetric A m s).
Axiom thm_SEQUENTIALLY_CLOSED_IN_MCOMPLETE_IMP_MCOMPLETE : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, ((@mcomplete A m) /\ (forall x : nat -> A, forall l : A, ((forall n : nat, @IN A (x n) s) /\ (@limit nat A (@mtopology A m) x l sequentially)) -> @IN A l s)) -> @mcomplete A (@submetric A m s).
Axiom thm_CAUCHY_IN_INTERLEAVING_GEN : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, forall y : nat -> A, (@cauchy_in A m (fun n : nat => @COND A (even n) (x (divn n (NUMERAL (BIT0 (BIT1 O))))) (y (divn n (NUMERAL (BIT0 (BIT1 O))))))) = ((@cauchy_in A m x) /\ ((@cauchy_in A m y) /\ (@limit nat R euclideanreal (fun n : nat => @mdist A m (@pair A A (x n) (y n))) (R_of_nat (NUMERAL O)) sequentially))).
Axiom thm_CAUCHY_IN_INTERLEAVING : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, forall a : A, (@cauchy_in A m (fun n : nat => @COND A (even n) (x (divn n (NUMERAL (BIT0 (BIT1 O))))) a)) = ((forall n : nat, @IN A (x n) (@mspace A m)) /\ (@limit nat A (@mtopology A m) x a sequentially)).
Axiom thm_MCOMPLETE_NEST : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall c : nat -> A -> Prop, ((forall n : nat, @closed_in A (@mtopology A m) (c n)) /\ ((forall n : nat, ~ ((c n) = (@set0 A))) /\ ((forall m' : nat, forall n : nat, (leqn m' n) -> @subset A (c n) (c m')) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists n : nat, exists a : A, @subset A (c n) (@mcball A m (@pair A R a e)))))) -> ~ ((@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1803 : A -> Prop => exists n : nat, @SETSPEC (A -> Prop) GEN_PVAR_1803 (@IN nat n (@setT nat)) (c n)))) = (@set0 A))).
Axiom thm_MCOMPLETE_NEST_SING : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall c : nat -> A -> Prop, ((forall n : nat, @closed_in A (@mtopology A m) (c n)) /\ ((forall n : nat, ~ ((c n) = (@set0 A))) /\ ((forall m' : nat, forall n : nat, (leqn m' n) -> @subset A (c n) (c m')) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists n : nat, exists a : A, @subset A (c n) (@mcball A m (@pair A R a e)))))) -> exists l : A, (@IN A l (@mspace A m)) /\ ((@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1805 : A -> Prop => exists n : nat, @SETSPEC (A -> Prop) GEN_PVAR_1805 (@IN nat n (@setT nat)) (c n)))) = (@INSERT A l (@set0 A)))).
Axiom thm_MCOMPLETE_FIP : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall f : (A -> Prop) -> Prop, ((forall c : A -> Prop, (@IN (A -> Prop) c f) -> @closed_in A (@mtopology A m) c) /\ ((forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists c : A -> Prop, exists a : A, (@IN (A -> Prop) c f) /\ (@subset A c (@mcball A m (@pair A R a e)))) /\ (forall f' : (A -> Prop) -> Prop, ((@finite_set (A -> Prop) f') /\ (@subset (A -> Prop) f' f)) -> ~ ((@INTERS A f') = (@set0 A))))) -> ~ ((@INTERS A f) = (@set0 A))).
Axiom thm_MCOMPLETE_FIP_SING : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) = (forall f : (A -> Prop) -> Prop, ((forall c : A -> Prop, (@IN (A -> Prop) c f) -> @closed_in A (@mtopology A m) c) /\ ((forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists c : A -> Prop, exists a : A, (@IN (A -> Prop) c f) /\ (@subset A c (@mcball A m (@pair A R a e)))) /\ (forall f' : (A -> Prop) -> Prop, ((@finite_set (A -> Prop) f') /\ (@subset (A -> Prop) f' f)) -> ~ ((@INTERS A f') = (@set0 A))))) -> exists l : A, (@IN A l (@mspace A m)) /\ ((@INTERS A f) = (@INSERT A l (@set0 A)))).
Axiom thm_MCOMPLETE_UNION : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, ((@mcomplete A (@submetric A m s)) /\ (@mcomplete A (@submetric A m t))) -> @mcomplete A (@submetric A m (@setU A s t)).
Axiom thm_MCOMPLETE_UNIONS : forall {_448495 : Type'}, forall m : Metric _448495, forall s : (_448495 -> Prop) -> Prop, ((@finite_set (_448495 -> Prop) s) /\ (forall t : _448495 -> Prop, (@IN (_448495 -> Prop) t s) -> @mcomplete _448495 (@submetric _448495 m t))) -> @mcomplete _448495 (@submetric _448495 m (@UNIONS _448495 s)).
Axiom thm_MCOMPLETE_INTERS : forall {A : Type'}, forall m : Metric A, forall s : (A -> Prop) -> Prop, ((@finite_set (A -> Prop) s) /\ ((~ (s = (@set0 (A -> Prop)))) /\ (forall t : A -> Prop, (@IN (A -> Prop) t s) -> @mcomplete A (@submetric A m t)))) -> @mcomplete A (@submetric A m (@INTERS A s)).
Axiom thm_MCOMPLETE_INTER : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, ((@mcomplete A (@submetric A m s)) /\ (@mcomplete A (@submetric A m t))) -> @mcomplete A (@submetric A m (@setI A s t)).
Axiom thm_totally_bounded_in : forall {A : Type'}, forall s : A -> Prop, forall m : Metric A, (@totally_bounded_in A m s) = (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists k : A -> Prop, (@finite_set A k) /\ ((@subset A k s) /\ (@subset A s (@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1814 : A -> Prop => exists x : A, @SETSPEC (A -> Prop) GEN_PVAR_1814 (@IN A x k) (@mball A m (@pair A R x e)))))))).
Axiom thm_TOTALLY_BOUNDED_IN_EMPTY : forall {A : Type'}, forall m : Metric A, @totally_bounded_in A m (@set0 A).
Axiom thm_FINITE_IMP_TOTALLY_BOUNDED_IN : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, ((@finite_set A s) /\ (@subset A s (@mspace A m))) -> @totally_bounded_in A m s.
Axiom thm_TOTALLY_BOUNDED_IN_IMP_SUBSET : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@totally_bounded_in A m s) -> @subset A s (@mspace A m).
Axiom thm_TOTALLY_BOUNDED_IN_SING : forall {A : Type'}, forall m : Metric A, forall x : A, (@totally_bounded_in A m (@INSERT A x (@set0 A))) = (@IN A x (@mspace A m)).
Axiom thm_TOTALLY_BOUNDED_IN_SEQUENTIALLY : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@totally_bounded_in A m s) = ((@subset A s (@mspace A m)) /\ (forall x : nat -> A, (forall n : nat, @IN A (x n) s) -> exists r : nat -> nat, (forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@cauchy_in A m (@o nat nat A x r)))).
Axiom thm_TOTALLY_BOUNDED_IN_SUBSET : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, ((@totally_bounded_in A m s) /\ (@subset A t s)) -> @totally_bounded_in A m t.
Axiom thm_TOTALLY_BOUNDED_IN_UNION : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, ((@totally_bounded_in A m s) /\ (@totally_bounded_in A m t)) -> @totally_bounded_in A m (@setU A s t).
Axiom thm_TOTALLY_BOUNDED_IN_UNIONS : forall {A : Type'}, forall m : Metric A, forall f : (A -> Prop) -> Prop, ((@finite_set (A -> Prop) f) /\ (forall s : A -> Prop, (@IN (A -> Prop) s f) -> @totally_bounded_in A m s)) -> @totally_bounded_in A m (@UNIONS A f).
Axiom thm_TOTALLY_BOUNDED_IN_IMP_MBOUNDED : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@totally_bounded_in A m s) -> @mbounded A m s.
Axiom thm_TOTALLY_BOUNDED_IN_SUBMETRIC : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall t : A -> Prop, ((@totally_bounded_in A m s) /\ (@subset A s t)) -> @totally_bounded_in A (@submetric A m t) s.
Axiom thm_TOTALLY_BOUNDED_IN_ABSOLUTE : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@totally_bounded_in A (@submetric A m s) s) = (@totally_bounded_in A m s).
Axiom thm_TOTALLY_BOUNDED_IN_CLOSURE_OF : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@totally_bounded_in A m s) -> @totally_bounded_in A m (@closure_of A (@mtopology A m) s).
Axiom thm_TOTALLY_BOUNDED_IN_CLOSURE_OF_EQ : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@subset A s (@mspace A m)) -> (@totally_bounded_in A m (@closure_of A (@mtopology A m) s)) = (@totally_bounded_in A m s).
Axiom thm_TOTALLY_BOUNDED_IN_CAUCHY_SEQUENCE : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, (@cauchy_in A m x) -> @totally_bounded_in A m (@IMAGE nat A x (@setT nat)).
Axiom thm_CAUCHY_IN_IMP_MBOUNDED : forall {A : Type'}, forall m : Metric A, forall x : nat -> A, (@cauchy_in A m x) -> @mbounded A m (@GSPEC A (fun GEN_PVAR_1822 : A => exists i : nat, @SETSPEC A GEN_PVAR_1822 (@IN nat i (@setT nat)) (x i))).
Axiom thm_BOLZANO_WEIERSTRASS_PROPERTY : forall {A : Type'}, forall m : Metric A, forall u : A -> Prop, forall s : A -> Prop, ((@subset A s u) /\ (@subset A s (@mspace A m))) -> (forall x : nat -> A, (forall n : nat, @IN A (x n) s) -> exists l : A, exists r : nat -> nat, (@IN A l u) /\ ((forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@limit nat A (@mtopology A m) (@o nat nat A x r) l sequentially))) = (forall t : A -> Prop, ((@subset A t s) /\ (@INFINITE A t)) -> ~ ((@setI A u (@derived_set_of A (@mtopology A m) t)) = (@set0 A))).
Axiom thm_COMPACT_IN_EQ_BOLZANO_WEIERSTRASS : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@compact_in A (@mtopology A m) s) = ((@subset A s (@mspace A m)) /\ (forall t : A -> Prop, ((@subset A t s) /\ (@INFINITE A t)) -> ~ ((@setI A s (@derived_set_of A (@mtopology A m) t)) = (@set0 A)))).
Axiom thm_COMPACT_IN_SEQUENTIALLY : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@compact_in A (@mtopology A m) s) = ((@subset A s (@mspace A m)) /\ (forall x : nat -> A, (forall n : nat, @IN A (x n) s) -> exists l : A, exists r : nat -> nat, (@IN A l s) /\ ((forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@limit nat A (@mtopology A m) (@o nat nat A x r) l sequentially)))).
Axiom thm_LEBESGUE_NUMBER : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall U : (A -> Prop) -> Prop, ((@compact_in A (@mtopology A m) s) /\ ((forall u : A -> Prop, (@IN (A -> Prop) u U) -> @open_in A (@mtopology A m) u) /\ (@subset A s (@UNIONS A U)))) -> exists e : R, (ltr (R_of_nat (NUMERAL O)) e) /\ (forall x : A, (@IN A x s) -> exists u : A -> Prop, (@IN (A -> Prop) u U) /\ (@subset A (@mball A m (@pair A R x e)) u)).
Axiom thm_COMPACT_IN_IMP_TOTALLY_BOUNDED_IN_EXPLICIT : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, forall e : R, ((@compact_in A (@mtopology A m) s) /\ (ltr (R_of_nat (NUMERAL O)) e)) -> exists k : A -> Prop, (@finite_set A k) /\ ((@subset A k s) /\ (@subset A s (@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1825 : A -> Prop => exists x : A, @SETSPEC (A -> Prop) GEN_PVAR_1825 (@IN A x k) (@mball A m (@pair A R x e))))))).
Axiom thm_COMPACT_SPACE_SEQUENTIALLY : forall {A : Type'}, forall m : Metric A, (@compact_space A (@mtopology A m)) = (forall x : nat -> A, (forall n : nat, @IN A (x n) (@mspace A m)) -> exists l : A, exists r : nat -> nat, (@IN A l (@mspace A m)) /\ ((forall m' : nat, forall n : nat, (ltn m' n) -> ltn (r m') (r n)) /\ (@limit nat A (@mtopology A m) (@o nat nat A x r) l sequentially))).
Axiom thm_COMPACT_SPACE_EQ_BOLZANO_WEIERSTRASS : forall {A : Type'}, forall m : Metric A, (@compact_space A (@mtopology A m)) = (forall s : A -> Prop, ((@subset A s (@mspace A m)) /\ (@INFINITE A s)) -> ~ ((@derived_set_of A (@mtopology A m) s) = (@set0 A))).
Axiom thm_COMPACT_SPACE_NEST : forall {A : Type'}, forall m : Metric A, (@compact_space A (@mtopology A m)) = (forall c : nat -> A -> Prop, ((forall n : nat, @closed_in A (@mtopology A m) (c n)) /\ ((forall n : nat, ~ ((c n) = (@set0 A))) /\ (forall m' : nat, forall n : nat, (leqn m' n) -> @subset A (c n) (c m')))) -> ~ ((@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1826 : A -> Prop => exists n : nat, @SETSPEC (A -> Prop) GEN_PVAR_1826 (@IN nat n (@setT nat)) (c n)))) = (@set0 A))).
Axiom thm_COMPACT_IN_IMP_TOTALLY_BOUNDED_IN : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@compact_in A (@mtopology A m) s) -> @totally_bounded_in A m s.
Axiom thm_MCOMPLETE_DISCRETE_METRIC : forall {A : Type'}, forall s : A -> Prop, @mcomplete A (@discrete_metric A s).
Axiom thm_COMPACT_SPACE_IMP_MCOMPLETE : forall {A : Type'}, forall m : Metric A, (@compact_space A (@mtopology A m)) -> @mcomplete A m.
Axiom thm_COMPACT_IN_IMP_MCOMPLETE : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@compact_in A (@mtopology A m) s) -> @mcomplete A (@submetric A m s).
Axiom thm_MCOMPLETE_IMP_CLOSED_IN : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, ((@mcomplete A (@submetric A m s)) /\ (@subset A s (@mspace A m))) -> @closed_in A (@mtopology A m) s.
Axiom thm_CLOSED_IN_EQ_MCOMPLETE : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@mcomplete A m) -> (@closed_in A (@mtopology A m) s) = ((@subset A s (@mspace A m)) /\ (@mcomplete A (@submetric A m s))).
Axiom thm_COMPACT_SPACE_EQ_MCOMPLETE_TOTALLY_BOUNDED_IN : forall {A : Type'}, forall m : Metric A, (@compact_space A (@mtopology A m)) = ((@mcomplete A m) /\ (@totally_bounded_in A m (@mspace A m))).
Axiom thm_COMPACT_CLOSURE_OF_IMP_TOTALLY_BOUNDED_IN : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, ((@subset A s (@mspace A m)) /\ (@compact_in A (@mtopology A m) (@closure_of A (@mtopology A m) s))) -> @totally_bounded_in A m s.
Axiom thm_TOTALLY_BOUNDED_IN_EQ_COMPACT_CLOSURE_OF : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@mcomplete A m) -> (@totally_bounded_in A m s) = ((@subset A s (@mspace A m)) /\ (@compact_in A (@mtopology A m) (@closure_of A (@mtopology A m) s))).
Axiom thm_COMPACT_CLOSURE_OF_EQ_BOLZANO_WEIERSTRASS : forall {A : Type'}, forall m : Metric A, forall s : A -> Prop, (@compact_in A (@mtopology A m) (@closure_of A (@mtopology A m) s)) = (forall t : A -> Prop, ((@INFINITE A t) /\ ((@subset A t s) /\ (@subset A t (@mspace A m)))) -> ~ ((@derived_set_of A (@mtopology A m) t) = (@set0 A))).
Axiom thm_MCOMPLETE_REAL_EUCLIDEAN_METRIC : @mcomplete R real_euclidean_metric.
Axiom thm_MCOMPLETE_SUBMETRIC_REAL_EUCLIDEAN_METRIC : forall s : R -> Prop, (@mcomplete R (@submetric R real_euclidean_metric s)) = (@closed_in R euclideanreal s).
Axiom thm_TOTALLY_BOUNDED_IN_DISCRETE_METRIC : forall {A : Type'}, forall u : A -> Prop, forall s : A -> Prop, (@totally_bounded_in A (@discrete_metric A u) s) = ((@finite_set A s) /\ (@subset A s u)).
