Axiom thm_LOCALLY_CONNECTED_SPACE_IM_KLEINEN : forall {A : Type'}, forall top : Topology A, (@locally_connected_space A top) = (forall v : A -> Prop, forall x : A, ((@open_in A top v) /\ (@IN A x v)) -> exists u : A -> Prop, (@open_in A top u) /\ ((@IN A x u) /\ ((@subset A u v) /\ (forall y : A, (@IN A y u) -> exists c : A -> Prop, (@connected_in A top c) /\ ((@subset A c v) /\ ((@IN A x c) /\ (@IN A y c))))))).
Axiom thm_LOCALLY_CONNECTED_SPACE_OPEN_SUBSET : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@locally_connected_space A top) /\ (@open_in A top s)) -> @locally_connected_space A (@subtopology A top s).
Axiom thm_LOCALLY_CONNECTED_SPACE_QUOTIENT_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@quotient_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@locally_connected_space A top)) -> @locally_connected_space B top'.
Axiom thm_LOCALLY_CONNECTED_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') r) /\ (@locally_connected_space A top)) -> @locally_connected_space B top'.
Axiom thm_HOMEOMORPHIC_LOCALLY_CONNECTED_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@locally_connected_space A top) = (@locally_connected_space B top').
Axiom thm_LOCALLY_CONNECTED_SPACE_EUCLIDEANREAL : @locally_connected_space R euclideanreal.
Axiom thm_LOCALLY_CONNECTED_IS_REALINTERVAL : forall s : R -> Prop, (is_realinterval s) -> @locally_connected_space R (@subtopology R euclideanreal s).
Axiom thm_LOCALLY_CONNECTED_REAL_INTERVAL : (forall a : R, forall b : R, @locally_connected_space R (@subtopology R euclideanreal (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))))) /\ (forall a : R, forall b : R, @locally_connected_space R (@subtopology R euclideanreal (open_real_interval (@pair R R a b)))).
Axiom thm_LOCALLY_CONNECTED_SPACE_DISCRETE_TOPOLOGY : forall {A : Type'}, forall u : A -> Prop, @locally_connected_space A (@discrete_topology A u).
Axiom thm_LOCALLY_PATH_CONNECTED_IMP_LOCALLY_CONNECTED_AT : forall {a : Type'}, forall top : Topology a, forall x : a, (@locally_path_connected_at a x top) -> @locally_connected_at a x top.
Axiom thm_WEAKLY_LOCALLY_PATH_CONNECTED_IMP_WEAKLY_LOCALLY_CONNECTED_AT : forall {a : Type'}, forall top : Topology a, forall x : a, (@weakly_locally_path_connected_at a x top) -> @weakly_locally_connected_at a x top.
Axiom thm_INTERIOR_OF_LOCALLY_CONNECTED_SUBSPACE_COMPONENT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall c : A -> Prop, ((@locally_connected_space A top) /\ (@IN (A -> Prop) c (@connected_components_of A (@subtopology A top s)))) -> (@interior_of A top c) = (@setI A c (@interior_of A top s)).
Axiom thm_FRONTIER_OF_LOCALLY_CONNECTED_SUBSPACE_COMPONENT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall c : A -> Prop, ((@locally_connected_space A top) /\ ((@closed_in A top s) /\ (@IN (A -> Prop) c (@connected_components_of A (@subtopology A top s))))) -> (@frontier_of A top c) = (@setI A c (@frontier_of A top s)).
Axiom thm_LOCALLY_CONNECTED_SPACE_PROD_TOPOLOGY : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, (@locally_connected_space (prod A B) (@prod_topology A B top1 top2)) = (((@topspace (prod A B) (@prod_topology A B top1 top2)) = (@set0 (prod A B))) \/ ((@locally_connected_space A top1) /\ (@locally_connected_space B top2))).
Axiom thm_LOCALLY_CONNECTED_SPACE_PRODUCT_TOPOLOGY : forall {A K : Type'}, forall tops : K -> Topology A, forall k : K -> Prop, (@locally_connected_space (K -> A) (@product_topology A K k tops)) = (((@topspace (K -> A) (@product_topology A K k tops)) = (@set0 (K -> A))) \/ ((@finite_set K (@GSPEC K (fun GEN_PVAR_1973 : K => exists i : K, @SETSPEC K GEN_PVAR_1973 ((@IN K i k) /\ (~ (@connected_space A (tops i)))) i))) /\ (forall i : K, (@IN K i k) -> @locally_connected_space A (tops i)))).
Axiom thm_LOCALLY_CONNECTED_SPACE_SUM_TOPOLOGY : forall {A K : Type'}, forall k : K -> Prop, forall top : K -> Topology A, (@locally_connected_space (prod K A) (@sum_topology A K k top)) = (forall i : K, (@IN K i k) -> @locally_connected_space A (top i)).
Axiom thm_quasi_component_of : forall {_475551 : Type'}, forall top : Topology _475551, forall x : _475551, forall y : _475551, (@quasi_component_of _475551 top x y) = ((@IN _475551 x (@topspace _475551 top)) /\ ((@IN _475551 y (@topspace _475551 top)) /\ (forall t : _475551 -> Prop, ((@closed_in _475551 top t) /\ (@open_in _475551 top t)) -> (@IN _475551 x t) = (@IN _475551 y t)))).
Axiom thm_quasi_components_of : forall {_475574 : Type'}, forall top : Topology _475574, (@quasi_components_of _475574 top) = (@GSPEC (_475574 -> Prop) (fun GEN_PVAR_1974 : _475574 -> Prop => exists x : _475574, @SETSPEC (_475574 -> Prop) GEN_PVAR_1974 (@IN _475574 x (@topspace _475574 top)) (@quasi_component_of _475574 top x))).
Axiom thm_QUASI_COMPONENT_IN_TOPSPACE : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) -> (@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top)).
Axiom thm_QUASI_COMPONENT_OF_REFL : forall {A : Type'}, forall top : Topology A, forall x : A, (@quasi_component_of A top x x) = (@IN A x (@topspace A top)).
Axiom thm_QUASI_COMPONENT_OF_SYM : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = (@quasi_component_of A top y x).
Axiom thm_QUASI_COMPONENT_OF_TRANS : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, forall z : A, ((@quasi_component_of A top x y) /\ (@quasi_component_of A top y z)) -> @quasi_component_of A top x z.
Axiom thm_QUASI_COMPONENT_OF_SUBSET_TOPSPACE : forall {_475701 : Type'}, forall top : Topology _475701, forall x : _475701, @subset _475701 (@quasi_component_of _475701 top x) (@topspace _475701 top).
Axiom thm_QUASI_COMPONENT_OF_EQ_EMPTY : forall {_475725 : Type'}, forall top : Topology _475725, forall x : _475725, ((@quasi_component_of _475725 top x) = (@set0 _475725)) = (~ (@IN _475725 x (@topspace _475725 top))).
Axiom thm_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (forall t : A -> Prop, ((@IN A x t) /\ ((@closed_in A top t) /\ (@open_in A top t))) -> @IN A y t))).
Axiom thm_QUASI_COMPONENT_OF_ALT : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (exists u : A -> Prop, exists v : A -> Prop, (@open_in A top u) /\ ((@open_in A top v) /\ (((@setU A u v) = (@topspace A top)) /\ ((@DISJOINT A u v) /\ ((@IN A x u) /\ (@IN A y v))))))))).
Axiom thm_QUASI_COMPONENT_OF_SET : forall {A : Type'}, forall top : Topology A, forall x : A, (@quasi_component_of A top x) = (@COND (A -> Prop) (@IN A x (@topspace A top)) (@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1975 : A -> Prop => exists t : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_1975 ((@closed_in A top t) /\ ((@open_in A top t) /\ (@IN A x t))) t))) (@set0 A)).
Axiom thm_QUASI_COMPONENT_OF_SEPARATED : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (exists u : A -> Prop, exists v : A -> Prop, (@separated_in A top u v) /\ (((@setU A u v) = (@topspace A top)) /\ ((@IN A x u) /\ (@IN A y v))))))).
Axiom thm_QUASI_COMPONENT_OF_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall x : A, forall y : A, (@quasi_component_of A (@subtopology A top s) x y) -> @quasi_component_of A top x y.
Axiom thm_QUASI_COMPONENT_OF_MONO : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall t : A -> Prop, forall x : A, forall y : A, ((@quasi_component_of A (@subtopology A top s) x y) /\ (@subset A s t)) -> @quasi_component_of A (@subtopology A top t) x y.
Axiom thm_QUASI_COMPONENT_OF_EQUIV : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ ((@quasi_component_of A top x) = (@quasi_component_of A top y)))).
Axiom thm_QUASI_COMPONENT_OF_DISJOINT : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@DISJOINT A (@quasi_component_of A top x) (@quasi_component_of A top y)) = (~ (@quasi_component_of A top x y)).
Axiom thm_QUASI_COMPONENT_OF_EQ : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, ((@quasi_component_of A top x) = (@quasi_component_of A top y)) = (((~ (@IN A x (@topspace A top))) /\ (~ (@IN A y (@topspace A top)))) \/ ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (@quasi_component_of A top x y)))).
Axiom thm_UNIONS_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, (@UNIONS A (@quasi_components_of A top)) = (@topspace A top).
Axiom thm_PAIRWISE_DISJOINT_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, @pairwise (A -> Prop) (@DISJOINT A) (@quasi_components_of A top).
Axiom thm_COMPLEMENT_QUASI_COMPONENTS_OF_UNIONS : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@setD A (@topspace A top) c) = (@UNIONS A (@DELETE (A -> Prop) (@quasi_components_of A top) c)).
Axiom thm_NONEMPTY_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> ~ (c = (@set0 A)).
Axiom thm_QUASI_COMPONENTS_OF_SUBSET : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> @subset A c (@topspace A top).
Axiom thm_QUASI_COMPONENT_IN_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, forall a : A, (@IN (A -> Prop) (@quasi_component_of A top a) (@quasi_components_of A top)) = (@IN A a (@topspace A top)).
Axiom thm_QUASI_COMPONENTS_OF_EQ_EMPTY : forall {A : Type'}, forall top : Topology A, ((@quasi_components_of A top) = (@set0 (A -> Prop))) = ((@topspace A top) = (@set0 A)).
Axiom thm_QUASI_COMPONENTS_OF_EMPTY_SPACE : forall {A : Type'}, forall top : Topology A, ((@topspace A top) = (@set0 A)) -> (@quasi_components_of A top) = (@set0 (A -> Prop)).
Axiom thm_CLOSED_IN_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, @closed_in A top (@quasi_component_of A top x).
Axiom thm_CLOSED_IN_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> @closed_in A top c.
Axiom thm_OPEN_IN_FINITE_QUASI_COMPONENTS : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, ((@finite_set (A -> Prop) (@quasi_components_of A top)) /\ (@IN (A -> Prop) c (@quasi_components_of A top))) -> @open_in A top c.
Axiom thm_QUASI_COMPONENT_OF_EQ_OVERLAP : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, ((@quasi_component_of A top x) = (@quasi_component_of A top y)) = (((~ (@IN A x (@topspace A top))) /\ (~ (@IN A y (@topspace A top)))) \/ (~ ((@setI A (@quasi_component_of A top x) (@quasi_component_of A top y)) = (@set0 A)))).
Axiom thm_QUASI_COMPONENT_OF_NONOVERLAP : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, ((@setI A (@quasi_component_of A top x) (@quasi_component_of A top y)) = (@set0 A)) = ((~ (@IN A x (@topspace A top))) \/ ((~ (@IN A y (@topspace A top))) \/ (~ ((@quasi_component_of A top x) = (@quasi_component_of A top y))))).
Axiom thm_QUASI_COMPONENT_OF_OVERLAP : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (~ ((@setI A (@quasi_component_of A top x) (@quasi_component_of A top y)) = (@set0 A))) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ ((@quasi_component_of A top x) = (@quasi_component_of A top y)))).
Axiom thm_QUASI_COMPONENTS_OF_DISJOINT : forall {_476707 : Type'}, forall top : Topology _476707, forall c : _476707 -> Prop, forall c' : _476707 -> Prop, ((@IN (_476707 -> Prop) c (@quasi_components_of _476707 top)) /\ (@IN (_476707 -> Prop) c' (@quasi_components_of _476707 top))) -> (@DISJOINT _476707 c c') = (~ (c = c')).
Axiom thm_QUASI_COMPONENTS_OF_OVERLAP : forall {_476758 : Type'}, forall top : Topology _476758, forall c : _476758 -> Prop, forall c' : _476758 -> Prop, ((@IN (_476758 -> Prop) c (@quasi_components_of _476758 top)) /\ (@IN (_476758 -> Prop) c' (@quasi_components_of _476758 top))) -> (~ ((@setI _476758 c c') = (@set0 _476758))) = (c = c').
Axiom thm_PAIRWISE_SEPARATED_QUASI_COMPONENTS_OF : forall {A : Type'}, forall top : Topology A, @pairwise (A -> Prop) (@separated_in A top) (@quasi_components_of A top).
Axiom thm_CARD_LE_QUASI_COMPONENTS_OF_TOPSPACE : forall {A : Type'}, forall top : Topology A, @le_c (A -> Prop) A (@quasi_components_of A top) (@topspace A top).
Axiom thm_FINITE_QUASI_COMPONENTS_OF_FINITE : forall {A : Type'}, forall top : Topology A, (@finite_set A (@topspace A top)) -> @finite_set (A -> Prop) (@quasi_components_of A top).
Axiom thm_CONNECTED_IMP_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@connected_component_of A top x y) -> @quasi_component_of A top x y.
Axiom thm_CONNECTED_COMPONENT_SUBSET_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, @subset A (@connected_component_of A top x) (@quasi_component_of A top x).
Axiom thm_QUASI_COMPONENT_AS_CONNECTED_COMPONENT_UNIONS : forall {A : Type'}, forall top : Topology A, forall x : A, (@quasi_component_of A top x) = (@UNIONS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1976 : A -> Prop => exists y : A, @SETSPEC (A -> Prop) GEN_PVAR_1976 (@quasi_component_of A top x y) (@connected_component_of A top y)))).
Axiom thm_QUASI_COMPONENTS_AS_CONNECTED_COMPONENTS_UNIONS : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> exists t : (A -> Prop) -> Prop, (@subset (A -> Prop) t (@connected_components_of A top)) /\ ((@UNIONS A t) = c).
Axiom thm_PATH_IMP_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@path_component_of A top x y) -> @quasi_component_of A top x y.
Axiom thm_PATH_COMPONENT_SUBSET_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall x : A, @subset A (@path_component_of A top x) (@quasi_component_of A top x).
Axiom thm_CONNECTED_SPACE_IFF_QUASI_COMPONENT : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall x : A, forall y : A, ((@IN A x (@topspace A top)) /\ (@IN A y (@topspace A top))) -> @quasi_component_of A top x y).
Axiom thm_CONNECTED_SPACE_IMP_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall a : A, forall b : A, ((@connected_space A top) /\ ((@IN A a (@topspace A top)) /\ (@IN A b (@topspace A top)))) -> @quasi_component_of A top a b.
Axiom thm_CONNECTED_SPACE_QUASI_COMPONENT_SET : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall x : A, (@IN A x (@topspace A top)) -> (@quasi_component_of A top x) = (@topspace A top)).
Axiom thm_CONNECTED_SPACE_IFF_QUASI_COMPONENTS_EQ : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (forall c : A -> Prop, forall c' : A -> Prop, ((@IN (A -> Prop) c (@quasi_components_of A top)) /\ (@IN (A -> Prop) c' (@quasi_components_of A top))) -> c = c').
Axiom thm_QUASI_COMPONENTS_OF_SUBSET_SING : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, (@subset (A -> Prop) (@quasi_components_of A top) (@INSERT (A -> Prop) s (@set0 (A -> Prop)))) = ((@connected_space A top) /\ (((@topspace A top) = (@set0 A)) \/ ((@topspace A top) = s))).
Axiom thm_CONNECTED_SPACE_IFF_QUASI_COMPONENTS_SUBSET_SING : forall {A : Type'}, forall top : Topology A, (@connected_space A top) = (exists a : A -> Prop, @subset (A -> Prop) (@quasi_components_of A top) (@INSERT (A -> Prop) a (@set0 (A -> Prop)))).
Axiom thm_QUASI_COMPONENTS_OF_EQ_SING : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@quasi_components_of A top) = (@INSERT (A -> Prop) s (@set0 (A -> Prop)))) = ((@connected_space A top) /\ ((~ ((@topspace A top) = (@set0 A))) /\ (s = (@topspace A top)))).
Axiom thm_QUASI_COMPONENTS_OF_CONNECTED_SPACE : forall {A : Type'}, forall top : Topology A, (@connected_space A top) -> (@quasi_components_of A top) = (@COND ((A -> Prop) -> Prop) ((@topspace A top) = (@set0 A)) (@set0 (A -> Prop)) (@INSERT (A -> Prop) (@topspace A top) (@set0 (A -> Prop)))).
Axiom thm_SEPARATED_BETWEEN_SINGS : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@separated_between A top (@INSERT A x (@set0 A)) (@INSERT A y (@set0 A))) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (@quasi_component_of A top x y)))).
Axiom thm_QUASI_COMPONENT_NONSEPARATED : forall {A : Type'}, forall top : Topology A, forall x : A, forall y : A, (@quasi_component_of A top x y) = ((@IN A x (@topspace A top)) /\ ((@IN A y (@topspace A top)) /\ (~ (@separated_between A top (@INSERT A x (@set0 A)) (@INSERT A y (@set0 A)))))).
Axiom thm_SEPARATED_BETWEEN_QUASI_COMPONENT_POINTWISE_LEFT : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall s : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@separated_between A top c s) = (exists x : A, (@IN A x c) /\ (@separated_between A top (@INSERT A x (@set0 A)) s)).
Axiom thm_SEPARATED_BETWEEN_QUASI_COMPONENT_POINTWISE_RIGHT : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@separated_between A top s c) = (exists x : A, (@IN A x c) /\ (@separated_between A top s (@INSERT A x (@set0 A)))).
Axiom thm_SEPARATED_BETWEEN_QUASI_COMPONENT_POINT : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall x : A, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@separated_between A top c (@INSERT A x (@set0 A))) = (@IN A x (@setD A (@topspace A top) c)).
Axiom thm_SEPARATED_BETWEEN_POINT_QUASI_COMPONENT : forall {A : Type'}, forall top : Topology A, forall x : A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@separated_between A top (@INSERT A x (@set0 A)) c) = (@IN A x (@setD A (@topspace A top) c)).
Axiom thm_SEPARATED_BETWEEN_QUASI_COMPONENT_COMPACT : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall k : A -> Prop, ((@IN (A -> Prop) c (@quasi_components_of A top)) /\ (@compact_in A top k)) -> (@separated_between A top c k) = (@DISJOINT A c k).
Axiom thm_SEPARATED_BETWEEN_COMPACT_QUASI_COMPONENT : forall {A : Type'}, forall top : Topology A, forall k : A -> Prop, forall c : A -> Prop, ((@compact_in A top k) /\ (@IN (A -> Prop) c (@quasi_components_of A top))) -> (@separated_between A top k c) = (@DISJOINT A k c).
Axiom thm_SEPARATED_BETWEEN_QUASI_COMPONENTS : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall c' : A -> Prop, ((@IN (A -> Prop) c (@quasi_components_of A top)) /\ (@IN (A -> Prop) c' (@quasi_components_of A top))) -> (@separated_between A top c c') = (@DISJOINT A c c').
Axiom thm_QUASI_EQ_CONNECTED_COMPONENT_OF_EQ : forall {A : Type'}, forall top : Topology A, forall x : A, ((@quasi_component_of A top x) = (@connected_component_of A top x)) = (@connected_in A top (@quasi_component_of A top x)).
Axiom thm_CONNECTED_QUASI_COMPONENT_OF : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@IN (A -> Prop) c (@connected_components_of A top)) = (@connected_in A top c).
Axiom thm_QUASI_COMPONENT_OF_CLOPEN_CASES : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, forall t : A -> Prop, ((@IN (A -> Prop) c (@quasi_components_of A top)) /\ ((@closed_in A top t) /\ (@open_in A top t))) -> (@subset A c t) \/ (@DISJOINT A c t).
Axiom thm_QUASI_COMPONENTS_OF_SET : forall {A : Type'}, forall top : Topology A, forall c : A -> Prop, (@IN (A -> Prop) c (@quasi_components_of A top)) -> (@INTERS A (@GSPEC (A -> Prop) (fun GEN_PVAR_1978 : A -> Prop => exists t : A -> Prop, @SETSPEC (A -> Prop) GEN_PVAR_1978 ((@closed_in A top t) /\ ((@open_in A top t) /\ (@subset A c t))) t))) = c.
