Axiom thm_HOMOTOPIC_WITH_TRANS : forall {A B : Type'}, forall P : (A -> B) -> Prop, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, forall h : A -> B, ((@homotopic_with B A P (@pair (Topology A) (Topology B) top top') f g) /\ (@homotopic_with B A P (@pair (Topology A) (Topology B) top top') g h)) -> @homotopic_with B A P (@pair (Topology A) (Topology B) top top') f h.
Axiom thm_HOMOTOPIC_WITH_COMPOSE_CONTINUOUS_MAP_LEFT : forall {A B C : Type'}, forall p : (A -> B) -> Prop, forall q : (A -> C) -> Prop, forall f : A -> B, forall g : A -> B, forall h : B -> C, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homotopic_with B A p (@pair (Topology A) (Topology B) top1 top2) f g) /\ ((@continuous_map B C (@pair (Topology B) (Topology C) top2 top3) h) /\ (forall j : A -> B, (p j) -> q (@o A B C h j)))) -> @homotopic_with C A q (@pair (Topology A) (Topology C) top1 top3) (@o A B C h f) (@o A B C h g).
Axiom thm_HOMOTOPIC_COMPOSE_CONTINUOUS_MAP_LEFT : forall {A B C : Type'}, forall f : A -> B, forall g : A -> B, forall h : B -> C, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homotopic_with B A (fun k : A -> B => True) (@pair (Topology A) (Topology B) top1 top2) f g) /\ (@continuous_map B C (@pair (Topology B) (Topology C) top2 top3) h)) -> @homotopic_with C A (fun k : A -> C => True) (@pair (Topology A) (Topology C) top1 top3) (@o A B C h f) (@o A B C h g).
Axiom thm_HOMOTOPIC_WITH_COMPOSE_CONTINUOUS_MAP_RIGHT : forall {A B C : Type'}, forall p : (B -> C) -> Prop, forall q : (A -> C) -> Prop, forall f : B -> C, forall g : B -> C, forall h : A -> B, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homotopic_with C B p (@pair (Topology B) (Topology C) top2 top3) f g) /\ ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) h) /\ (forall j : B -> C, (p j) -> q (@o A B C j h)))) -> @homotopic_with C A q (@pair (Topology A) (Topology C) top1 top3) (@o A B C f h) (@o A B C g h).
Axiom thm_HOMOTOPIC_COMPOSE_CONTINUOUS_MAP_RIGHT : forall {A B C : Type'}, forall f : B -> C, forall g : B -> C, forall h : A -> B, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homotopic_with C B (fun k : B -> C => True) (@pair (Topology B) (Topology C) top2 top3) f g) /\ (@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) h)) -> @homotopic_with C A (fun k : A -> C => True) (@pair (Topology A) (Topology C) top1 top3) (@o A B C f h) (@o A B C g h).
Axiom thm_HOMOTOPIC_FROM_SUBTOPOLOGY : forall {A B : Type'}, forall P : (A -> B) -> Prop, forall top : Topology A, forall top' : Topology B, forall s : A -> Prop, forall f : A -> B, forall g : A -> B, (@homotopic_with B A P (@pair (Topology A) (Topology B) top top') f g) -> @homotopic_with B A P (@pair (Topology A) (Topology B) (@subtopology A top s) top') f g.
Axiom thm_HOMOTOPIC_ON_EMPTY : forall {A B : Type'} (P : (A -> B) -> Prop), forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, ((@topspace A top) = (@set0 A)) -> (@homotopic_with B A P (@pair (Topology A) (Topology B) top top') f g) = ((P f) /\ (P g)).
Axiom thm_HOMOTOPIC_CONSTANT_MAPS : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall a : B, forall b : B, (@homotopic_with B A (fun x : A -> B => True) (@pair (Topology A) (Topology B) top top') (fun x : A => a) (fun x : A => b)) = (((@topspace A top) = (@set0 A)) \/ (@path_component_of B top' a b)).
Axiom thm_HOMOTOPIC_WITH_EQ : forall {A B : Type'}, forall P : (A -> B) -> Prop, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall g : A -> B, forall f' : A -> B, forall g' : A -> B, ((@homotopic_with B A P (@pair (Topology A) (Topology B) top top') f g) /\ ((forall x : A, (@IN A x (@topspace A top)) -> ((f' x) = (f x)) /\ ((g' x) = (g x))) /\ (forall h : A -> B, forall k : A -> B, (forall x : A, (@IN A x (@topspace A top)) -> (h x) = (k x)) -> (P h) = (P k)))) -> @homotopic_with B A P (@pair (Topology A) (Topology B) top top') f' g'.
Axiom thm_HOMOTOPIC_WITH_PROD_TOPOLOGY : forall {A B C D : Type'}, forall p : (A -> B) -> Prop, forall q : (C -> D) -> Prop, forall r : ((prod A C) -> prod B D) -> Prop, forall top1 : Topology A, forall top1' : Topology B, forall top2 : Topology C, forall top2' : Topology D, forall f : A -> B, forall g : C -> D, forall f' : A -> B, forall g' : C -> D, ((@homotopic_with B A p (@pair (Topology A) (Topology B) top1 top1') f f') /\ ((@homotopic_with D C q (@pair (Topology C) (Topology D) top2 top2') g g') /\ (forall i : A -> B, forall j : C -> D, ((p i) /\ (q j)) -> r (@ε ((prod A C) -> prod B D) (fun f'' : (prod A C) -> prod B D => forall x : A, forall y : C, @eq (prod B D) (f'' (@pair A C x y)) (@pair B D (i x) (j y))))))) -> @homotopic_with (prod B D) (prod A C) r (@pair (Topology (prod A C)) (Topology (prod B D)) (@prod_topology A C top1 top2) (@prod_topology B D top1' top2')) (fun z : prod A C => @pair B D (f (@fst A C z)) (g (@snd A C z))) (fun z : prod A C => @pair B D (f' (@fst A C z)) (g' (@snd A C z))).
Axiom thm_HOMOTOPIC_WITH_PRODUCT_TOPOLOGY : forall {A B K : Type'}, forall k : K -> Prop, forall tops : K -> Topology A, forall tops' : K -> Topology B, forall p : K -> (A -> B) -> Prop, forall q : ((K -> A) -> K -> B) -> Prop, forall f : K -> A -> B, forall g : K -> A -> B, ((forall i : K, (@IN K i k) -> @homotopic_with B A (p i) (@pair (Topology A) (Topology B) (tops i) (tops' i)) (f i) (g i)) /\ (forall h : K -> A -> B, (forall i : K, (@IN K i k) -> p i (h i)) -> q (fun x : K -> A => @RESTRICTION K B k (fun i : K => h i (x i))))) -> @homotopic_with (K -> B) (K -> A) q (@pair (Topology (K -> A)) (Topology (K -> B)) (@product_topology A K k tops) (@product_topology B K k tops')) (fun z : K -> A => @RESTRICTION K B k (fun i : K => f i (z i))) (fun z : K -> A => @RESTRICTION K B k (fun i : K => g i (z i))).
Axiom thm_homotopy_equivalent_space : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homotopy_equivalent_space A B top top') = (exists f : A -> B, exists g : B -> A, (@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@continuous_map B A (@pair (Topology B) (Topology A) top' top) g) /\ ((@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (@o A B A g f) (@I A)) /\ (@homotopic_with B B (fun x : B -> B => True) (@pair (Topology B) (Topology B) top' top') (@o B A B f g) (@I B))))).
Axiom thm_HOMEOMORPHIC_IMP_HOMOTOPY_EQUIVALENT_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> @homotopy_equivalent_space A B top top'.
Axiom thm_HOMOTOPY_EQUIVALENT_SPACE_REFL : forall {A : Type'}, forall top : Topology A, @homotopy_equivalent_space A A top top.
Axiom thm_HOMOTOPY_EQUIVALENT_SPACE_SYM : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homotopy_equivalent_space A B top top') = (@homotopy_equivalent_space B A top' top).
Axiom thm_HOMOTOPY_EQUIVALENT_SPACE_TRANS : forall {A B C : Type'}, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@homotopy_equivalent_space A B top1 top2) /\ (@homotopy_equivalent_space B C top2 top3)) -> @homotopy_equivalent_space A C top1 top3.
Axiom thm_DEFORMATION_RETRACTION_IMP_HOMOTOPY_EQUIVALENT_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, forall s : B -> A, ((@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (@o A B A s r) (@I A)) /\ (@retraction_maps A B (@pair (Topology A) (Topology B) top top') (@pair (A -> B) (B -> A) r s))) -> @homotopy_equivalent_space A B top top'.
Axiom thm_DEFORMATION_RETRACT_IMP_HOMOTOPY_EQUIVALENT_SPACE : forall {A : Type'}, forall top : Topology A, forall top' : Topology A, forall r : A -> A, ((@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) r (@I A)) /\ (@retraction_maps A A (@pair (Topology A) (Topology A) top top') (@pair (A -> A) (A -> A) r (@I A)))) -> @homotopy_equivalent_space A A top top'.
Axiom thm_DEFORMATION_RETRACT_OF_SPACE : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@subset A s (@topspace A top)) /\ (exists r : A -> A, (@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (@I A) r) /\ (@retraction_maps A A (@pair (Topology A) (Topology A) top (@subtopology A top s)) (@pair (A -> A) (A -> A) r (@I A))))) = ((@retract_of_space A s top) /\ (exists f : A -> A, (@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (@I A) f) /\ (@subset A (@IMAGE A A f (@topspace A top)) s))).
Axiom thm_contractible_space : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) = (exists a : A, @homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (fun x : A => x) (fun x : A => a)).
Axiom thm_CONTRACTIBLE_SPACE_EMPTY : forall {A : Type'}, forall top : Topology A, ((@topspace A top) = (@set0 A)) -> @contractible_space A top.
Axiom thm_CONTRACTIBLE_SPACE_SING : forall {A : Type'}, forall top : Topology A, forall a : A, ((@topspace A top) = (@INSERT A a (@set0 A))) -> @contractible_space A top.
Axiom thm_CONTRACTIBLE_SPACE_SUBSET_SING : forall {A : Type'}, forall top : Topology A, forall a : A, (@subset A (@topspace A top) (@INSERT A a (@set0 A))) -> @contractible_space A top.
Axiom thm_CONTRACTIBLE_SPACE_SUBTOPOLOGY_SING : forall {A : Type'}, forall top : Topology A, forall a : A, @contractible_space A (@subtopology A top (@INSERT A a (@set0 A))).
Axiom thm_CONTRACTIBLE_SPACE : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) = (((@topspace A top) = (@set0 A)) \/ (exists a : A, (@IN A a (@topspace A top)) /\ (@homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (fun x : A => x) (fun x : A => a)))).
Axiom thm_CONTRACTIBLE_IMP_PATH_CONNECTED_SPACE : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) -> @path_connected_space A top.
Axiom thm_CONTRACTIBLE_IMP_CONNECTED_SPACE : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) -> @connected_space A top.
Axiom thm_CONTRACTIBLE_SPACE_ALT : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) = (forall a : A, (@IN A a (@topspace A top)) -> @homotopic_with A A (fun x : A -> A => True) (@pair (Topology A) (Topology A) top top) (fun x : A => x) (fun x : A => a)).
Axiom thm_NULLHOMOTOPIC_THROUGH_CONTRACTIBLE_SPACE : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) f) /\ ((@continuous_map B C (@pair (Topology B) (Topology C) top2 top3) g) /\ (@contractible_space B top2))) -> exists c : C, @homotopic_with C A (fun h : A -> C => True) (@pair (Topology A) (Topology C) top1 top3) (@o A B C g f) (fun x : A => c).
Axiom thm_NULLHOMOTOPIC_INTO_CONTRACTIBLE_SPACE : forall {A B : Type'}, forall f : A -> B, forall top1 : Topology A, forall top2 : Topology B, ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) f) /\ (@contractible_space B top2)) -> exists c : B, @homotopic_with B A (fun h : A -> B => True) (@pair (Topology A) (Topology B) top1 top2) f (fun x : A => c).
Axiom thm_NULLHOMOTOPIC_FROM_CONTRACTIBLE_SPACE : forall {A B : Type'}, forall f : A -> B, forall top1 : Topology A, forall top2 : Topology B, ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) f) /\ (@contractible_space A top1)) -> exists c : B, @homotopic_with B A (fun h : A -> B => True) (@pair (Topology A) (Topology B) top1 top2) f (fun x : A => c).
Axiom thm_HOMOTOPIC_THROUGH_CONTRACTIBLE_SPACE : forall {A B C : Type'}, forall f : A -> B, forall g : B -> C, forall f' : A -> B, forall g' : B -> C, forall top1 : Topology A, forall top2 : Topology B, forall top3 : Topology C, ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) f) /\ ((@continuous_map A B (@pair (Topology A) (Topology B) top1 top2) f') /\ ((@continuous_map B C (@pair (Topology B) (Topology C) top2 top3) g) /\ ((@continuous_map B C (@pair (Topology B) (Topology C) top2 top3) g') /\ ((@contractible_space B top2) /\ (@path_connected_space C top3)))))) -> @homotopic_with C A (fun h : A -> C => True) (@pair (Topology A) (Topology C) top1 top3) (@o A B C g f) (@o A B C g' f').
Axiom thm_HOMOTOPIC_FROM_CONTRACTIBLE_SPACE : forall {A B : Type'}, forall f : A -> B, forall g : A -> B, forall top : Topology A, forall top' : Topology B, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@continuous_map A B (@pair (Topology A) (Topology B) top top') g) /\ ((@contractible_space A top) /\ (@path_connected_space B top')))) -> @homotopic_with B A (fun x : A -> B => True) (@pair (Topology A) (Topology B) top top') f g.
Axiom thm_HOMOTOPIC_INTO_CONTRACTIBLE_SPACE : forall {A B : Type'}, forall f : A -> B, forall g : A -> B, forall top : Topology A, forall top' : Topology B, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@continuous_map A B (@pair (Topology A) (Topology B) top top') g) /\ (@contractible_space B top'))) -> @homotopic_with B A (fun x : A -> B => True) (@pair (Topology A) (Topology B) top top') f g.
Axiom thm_HOMOTOPY_DOMINATED_CONTRACTIBILITY : forall {A B : Type'}, forall f : A -> B, forall g : B -> A, forall top : Topology A, forall top' : Topology B, ((@continuous_map A B (@pair (Topology A) (Topology B) top top') f) /\ ((@continuous_map B A (@pair (Topology B) (Topology A) top' top) g) /\ ((@homotopic_with B B (fun x : B -> B => True) (@pair (Topology B) (Topology B) top' top') (@o B A B f g) (@I B)) /\ (@contractible_space A top)))) -> @contractible_space B top'.
Axiom thm_HOMOTOPY_EQUIVALENT_SPACE_CONTRACTIBILITY : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homotopy_equivalent_space A B top top') -> (@contractible_space A top) = (@contractible_space B top').
Axiom thm_HOMEOMORPHIC_SPACE_CONTRACTIBILITY : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@contractible_space A top) = (@contractible_space B top').
Axiom thm_CONTRACTIBLE_EQ_HOMOTOPY_EQUIVALENT_SINGLETON_SUBTOPOLOGY : forall {A : Type'}, forall top : Topology A, (@contractible_space A top) = (((@topspace A top) = (@set0 A)) \/ (exists a : A, (@IN A a (@topspace A top)) /\ (@homotopy_equivalent_space A A top (@subtopology A top (@INSERT A a (@set0 A)))))).
Axiom thm_CONTRACTIBLE_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') f) /\ (@contractible_space A top)) -> @contractible_space B top'.
Axiom thm_CONTRACTIBLE_SPACE_PROD_TOPOLOGY : forall {A B : Type'}, forall top1 : Topology A, forall top2 : Topology B, (@contractible_space (prod A B) (@prod_topology A B top1 top2)) = (((@topspace A top1) = (@set0 A)) \/ (((@topspace B top2) = (@set0 B)) \/ ((@contractible_space A top1) /\ (@contractible_space B top2)))).
Axiom thm_CONTRACTIBLE_SPACE_PRODUCT_TOPOLOGY : forall {A K : Type'}, forall k : K -> Prop, forall tops : K -> Topology A, (@contractible_space (K -> A) (@product_topology A K k tops)) = (((@topspace (K -> A) (@product_topology A K k tops)) = (@set0 (K -> A))) \/ (forall i : K, (@IN K i k) -> @contractible_space A (tops i))).
Axiom thm_CONTRACTIBLE_SPACE_SUBTOPOLOGY_EUCLIDEANREAL : forall s : R -> Prop, (@contractible_space R (@subtopology R euclideanreal s)) = (is_realinterval s).
Axiom thm_CONTRACTIBLE_SPACE_EUCLIDEANREAL : @contractible_space R euclideanreal.
Axiom thm_completely_metrizable_space : forall {_490593 : Type'}, forall top : Topology _490593, (@completely_metrizable_space _490593 top) = (exists m : Metric _490593, (@mcomplete _490593 m) /\ (top = (@mtopology _490593 m))).
Axiom thm_COMPLETELY_METRIZABLE_IMP_METRIZABLE_SPACE : forall {A : Type'}, forall top : Topology A, (@completely_metrizable_space A top) -> @metrizable_space A top.
Axiom thm_FORALL_MCOMPLETE_TOPOLOGY : forall {A : Type'}, forall P : (Topology A) -> (A -> Prop) -> Prop, (forall m : Metric A, (@mcomplete A m) -> P (@mtopology A m) (@mspace A m)) = (forall top : Topology A, (@completely_metrizable_space A top) -> P top (@topspace A top)).
Axiom thm_FORALL_COMPLETELY_METRIZABLE_SPACE : forall {A : Type'} (P : (Topology A) -> (A -> Prop) -> Prop), (forall top : Topology A, (@completely_metrizable_space A top) -> P top (@topspace A top)) = (forall m : Metric A, (@mcomplete A m) -> P (@mtopology A m) (@mspace A m)).
Axiom thm_EXISTS_COMPLETELY_METRIZABLE_SPACE : forall {A : Type'}, forall P : (Topology A) -> (A -> Prop) -> Prop, (exists top : Topology A, (@completely_metrizable_space A top) /\ (P top (@topspace A top))) = (exists m : Metric A, (@mcomplete A m) /\ (P (@mtopology A m) (@mspace A m))).
Axiom thm_COMPLETELY_METRIZABLE_SPACE_MTOPOLOGY : forall {A : Type'}, forall m : Metric A, (@mcomplete A m) -> @completely_metrizable_space A (@mtopology A m).
Axiom thm_COMPLETELY_METRIZABLE_SPACE_DISCRETE_TOPOLOGY : forall {A : Type'}, forall u : A -> Prop, @completely_metrizable_space A (@discrete_topology A u).
Axiom thm_COMPLETELY_METRIZABLE_SPACE_EUCLIDEANREAL : @completely_metrizable_space R euclideanreal.
Axiom thm_COMPLETELY_METRIZABLE_SPACE_CLOSED_IN : forall {A : Type'}, forall top : Topology A, forall s : A -> Prop, ((@completely_metrizable_space A top) /\ (@closed_in A top s)) -> @completely_metrizable_space A (@subtopology A top s).
Axiom thm_HOMEOMORPHIC_COMPLETELY_METRIZABLE_SPACE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, (@homeomorphic_space A B top top') -> (@completely_metrizable_space A top) = (@completely_metrizable_space B top').
Axiom thm_COMPLETELY_METRIZABLE_SPACE_RETRACTION_MAP_IMAGE : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall r : A -> B, ((@retraction_map A B (@pair (Topology A) (Topology B) top top') r) /\ (@completely_metrizable_space A top)) -> @completely_metrizable_space B top'.
Axiom thm_prod_metric : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, (@prod_metric A B m1 m2) = (@metric (prod A B) (@pair ((prod A B) -> Prop) ((prod (prod A B) (prod A B)) -> R) (@CROSS A B (@mspace A m1) (@mspace B m2)) (@ε ((prod (prod A B) (prod A B)) -> R) (fun f : (prod (prod A B) (prod A B)) -> R => forall x : A, forall y : B, forall x' : A, forall y' : B, @eq R (f (@pair (prod A B) (prod A B) (@pair A B x y) (@pair A B x' y'))) (hol_sqrt (addr (expr (@mdist A m1 (@pair A A x x')) (NUMERAL (BIT0 (BIT1 O)))) (expr (@mdist B m2 (@pair B B y y')) (NUMERAL (BIT0 (BIT1 O)))))))))).
