Axiom thm_LIPSCHITZ_IMP_CAUCHY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, (@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f) -> @cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f.
Axiom thm_CONTINUOUS_IMP_CAUCHY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, ((@mcomplete A m1) /\ (@continuous_map A B (@pair (Topology A) (Topology B) (@mtopology A m1) (@mtopology B m2)) f)) -> @cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f.
Axiom thm_CAUCHY_IMP_UNIFORMLY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, ((@totally_bounded_in A m1 (@mspace A m1)) /\ (@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f)) -> @uniformly_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f.
Axiom thm_CONTINUOUS_IMP_UNIFORMLY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, ((@compact_space A (@mtopology A m1)) /\ (@continuous_map A B (@pair (Topology A) (Topology B) (@mtopology A m1) (@mtopology B m2)) f)) -> @uniformly_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f.
Axiom thm_CONTINUOUS_EQ_CAUCHY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, (@mcomplete A m1) -> (@continuous_map A B (@pair (Topology A) (Topology B) (@mtopology A m1) (@mtopology B m2)) f) = (@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f).
Axiom thm_CONTINUOUS_EQ_UNIFORMLY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, (@compact_space A (@mtopology A m1)) -> (@continuous_map A B (@pair (Topology A) (Topology B) (@mtopology A m1) (@mtopology B m2)) f) = (@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f).
Axiom thm_CAUCHY_EQ_UNIFORMLY_CONTINUOUS_MAP : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, (@totally_bounded_in A m1 (@mspace A m1)) -> (@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f) = (@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_PROJECTIONS : forall {A B : Type'}, (forall m1 : Metric A, forall m2 : Metric B, @lipschitz_continuous_map A (prod A B) (@pair (Metric (prod A B)) (Metric A) (@prod_metric A B m1 m2) m1) (@fst A B)) /\ (forall m1 : Metric A, forall m2 : Metric B, @lipschitz_continuous_map B (prod A B) (@pair (Metric (prod A B)) (Metric B) (@prod_metric A B m1 m2) m2) (@snd A B)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_PAIRWISE : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@lipschitz_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) = ((@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m m1) (@o A (prod B C) B (@fst B C) f)) /\ (@lipschitz_continuous_map C A (@pair (Metric A) (Metric C) m m2) (@o A (prod B C) C (@snd B C) f))).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_PAIRWISE : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@uniformly_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) = ((@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m m1) (@o A (prod B C) B (@fst B C) f)) /\ (@uniformly_continuous_map C A (@pair (Metric A) (Metric C) m m2) (@o A (prod B C) C (@snd B C) f))).
Axiom thm_CAUCHY_CONTINUOUS_MAP_PAIRWISE : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@cauchy_continuous_map A (prod B C) (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) = ((@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m m1) (@o A (prod B C) B (@fst B C) f)) /\ (@cauchy_continuous_map A C (@pair (Metric A) (Metric C) m m2) (@o A (prod B C) C (@snd B C) f))).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_PAIRED : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> B, forall g : A -> C, (@lipschitz_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) (fun x : A => @pair B C (f x) (g x))) = ((@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m m1) f) /\ (@lipschitz_continuous_map C A (@pair (Metric A) (Metric C) m m2) g)).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_PAIRED : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> B, forall g : A -> C, (@uniformly_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) (fun x : A => @pair B C (f x) (g x))) = ((@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m m1) f) /\ (@uniformly_continuous_map C A (@pair (Metric A) (Metric C) m m2) g)).
Axiom thm_CAUCHY_CONTINUOUS_MAP_PAIRED : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> B, forall g : A -> C, (@cauchy_continuous_map A (prod B C) (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) (fun x : A => @pair B C (f x) (g x))) = ((@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m m1) f) /\ (@cauchy_continuous_map A C (@pair (Metric A) (Metric C) m m2) g)).
Axiom thm_MBOUNDED_LIPSCHITZ_CONTINUOUS_IMAGE : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, forall s : A -> Prop, ((@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m1 m2) f) /\ (@mbounded A m1 s)) -> @mbounded B m2 (@IMAGE A B f s).
Axiom thm_TOTALLY_BOUNDED_IN_CAUCHY_CONTINUOUS_IMAGE : forall {A B : Type'}, forall m1 : Metric A, forall m2 : Metric B, forall f : A -> B, forall s : A -> Prop, ((@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m1 m2) f) /\ (@totally_bounded_in A m1 s)) -> @totally_bounded_in B m2 (@IMAGE A B f s).
Axiom thm_LIPSCHITZ_COEFFICIENT_POS : forall {A B : Type'}, forall m : Metric A, forall m' : Metric B, forall f : A -> B, forall k : R, ((forall x : A, (@IN A x (@mspace A m)) -> @IN B (f x) (@mspace B m')) /\ ((forall x : A, forall y : A, ((@IN A x (@mspace A m)) /\ (@IN A y (@mspace A m))) -> ler (@mdist B m' (@pair B B (f x) (f y))) (mulr k (@mdist A m (@pair A A x y)))) /\ (exists x : A, exists y : A, (@IN A x (@mspace A m)) /\ ((@IN A y (@mspace A m)) /\ (~ ((f x) = (f y))))))) -> ltr (R_of_nat (NUMERAL O)) k.
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_METRIC : forall {A : Type'}, forall m : Metric A, @lipschitz_continuous_map R (prod A A) (@pair (Metric (prod A A)) (Metric R) (@prod_metric A A m m) real_euclidean_metric) (@mdist A m).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_MDIST : forall {A B : Type'}, forall m : Metric A, forall m' : Metric B, forall f : A -> B, forall g : A -> B, ((@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m m') f) /\ (@lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m m') g)) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => @mdist B m' (@pair B B (f x) (g x))).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_MDIST : forall {A B : Type'}, forall m : Metric A, forall m' : Metric B, forall f : A -> B, forall g : A -> B, ((@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m m') f) /\ (@uniformly_continuous_map B A (@pair (Metric A) (Metric B) m m') g)) -> @uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => @mdist B m' (@pair B B (f x) (g x))).
Axiom thm_CAUCHY_CONTINUOUS_MAP_MDIST : forall {A B : Type'}, forall m : Metric A, forall m' : Metric B, forall f : A -> B, forall g : A -> B, ((@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m m') f) /\ (@cauchy_continuous_map A B (@pair (Metric A) (Metric B) m m') g)) -> @cauchy_continuous_map A R (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => @mdist B m' (@pair B B (f x) (g x))).
Axiom thm_CONTINUOUS_MAP_METRIC : forall {A : Type'}, forall m : Metric A, @continuous_map (prod A A) R (@pair (Topology (prod A A)) (Topology R) (@prod_topology A A (@mtopology A m) (@mtopology A m)) euclideanreal) (@mdist A m).
Axiom thm_CONTINUOUS_MAP_MDIST_ALT : forall {A B : Type'} (top : Topology A), forall m : Metric B, forall f : A -> prod B B, (@continuous_map A (prod B B) (@pair (Topology A) (Topology (prod B B)) top (@prod_topology B B (@mtopology B m) (@mtopology B m))) f) -> @continuous_map A R (@pair (Topology A) (Topology R) top euclideanreal) (fun x : A => @mdist B m (f x)).
Axiom thm_CONTINUOUS_MAP_MDIST : forall {A B : Type'}, forall top : Topology A, forall m : Metric B, forall f : A -> B, forall g : A -> B, ((@continuous_map A B (@pair (Topology A) (Topology B) top (@mtopology B m)) f) /\ (@continuous_map A B (@pair (Topology A) (Topology B) top (@mtopology B m)) g)) -> @continuous_map A R (@pair (Topology A) (Topology R) top euclideanreal) (fun x : A => @mdist B m (@pair B B (f x) (g x))).
Axiom thm_CONTINUOUS_ON_MDIST : forall {A : Type'}, forall m : Metric A, forall a : A, (@IN A a (@mspace A m)) -> @continuous_map A R (@pair (Topology A) (Topology R) (@mtopology A m) euclideanreal) (fun x : A => @mdist A m (@pair A A a x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_LEFT_MULTIPLICATION : forall c : R, @lipschitz_continuous_map R R (@pair (Metric R) (Metric R) real_euclidean_metric real_euclidean_metric) (fun x : R => mulr c x).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_RIGHT_MULTIPLICATION : forall c : R, @lipschitz_continuous_map R R (@pair (Metric R) (Metric R) real_euclidean_metric real_euclidean_metric) (fun x : R => mulr x c).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_NEGATION : @lipschitz_continuous_map R R (@pair (Metric R) (Metric R) real_euclidean_metric real_euclidean_metric) oppr.
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_ABSOLUTE_VALUE : @lipschitz_continuous_map R R (@pair (Metric R) (Metric R) real_euclidean_metric real_euclidean_metric) normr.
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_ADDITION : @lipschitz_continuous_map R (prod R R) (@pair (Metric (prod R R)) (Metric R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (addr x y))).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_SUBTRACTION : @lipschitz_continuous_map R (prod R R) (@pair (Metric (prod R R)) (Metric R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (subr x y))).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_MAXIMUM : @lipschitz_continuous_map R (prod R R) (@pair (Metric (prod R R)) (Metric R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (maxr x y))).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_MINIMUM : @lipschitz_continuous_map R (prod R R) (@pair (Metric (prod R R)) (Metric R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (minr x y))).
Axiom thm_LOCALLY_LIPSCHITZ_CONTINUOUS_MAP_REAL_MULTIPLICATION : forall s : (prod R R) -> Prop, (@mbounded (prod R R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) s) -> @lipschitz_continuous_map R (prod R R) (@pair (Metric (prod R R)) (Metric R) (@submetric (prod R R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) s) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (mulr x y))).
Axiom thm_CAUCHY_CONTINUOUS_MAP_REAL_MULTIPLICATION : @cauchy_continuous_map (prod R R) R (@pair (Metric (prod R R)) (Metric R) (@prod_metric R R real_euclidean_metric real_euclidean_metric) real_euclidean_metric) (@ε ((prod R R) -> R) (fun f : (prod R R) -> R => forall x : R, forall y : R, @eq R (f (@pair R R x y)) (mulr x y))).
Axiom thm_LOCALLY_LIPSCHITZ_CONTINUOUS_MAP_REAL_INVERSION : forall s : R -> Prop, (~ (@IN R (R_of_nat (NUMERAL O)) (@closure_of R euclideanreal s))) -> @lipschitz_continuous_map R R (@pair (Metric R) (Metric R) (@submetric R real_euclidean_metric s) real_euclidean_metric) invr.
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_FST : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@lipschitz_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) -> @lipschitz_continuous_map B A (@pair (Metric A) (Metric B) m m1) (fun x : A => @fst B C (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_SND : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@lipschitz_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) -> @lipschitz_continuous_map C A (@pair (Metric A) (Metric C) m m2) (fun x : A => @snd B C (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_LMUL : forall {A : Type'}, forall m : Metric A, forall c : R, forall f : A -> R, (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => mulr c (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_RMUL : forall {A : Type'}, forall m : Metric A, forall c : R, forall f : A -> R, (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => mulr (f x) c).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_NEG : forall {A : Type'}, forall m : Metric A, forall f : A -> R, (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => oppr (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_ABS : forall {A : Type'}, forall m : Metric A, forall f : A -> R, (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => normr (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_INV : forall {A : Type'}, forall m : Metric A, forall f : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ (~ (@IN R (R_of_nat (NUMERAL O)) (@closure_of R euclideanreal (@IMAGE A R f (@mspace A m)))))) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => invr (f x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_ADD : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g)) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => addr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_SUB : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g)) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => subr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_MAX : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g)) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => maxr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_MIN : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ (@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g)) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => minr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_MUL : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g) /\ ((real_bounded (@IMAGE A R f (@mspace A m))) /\ (real_bounded (@IMAGE A R g (@mspace A m)))))) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => mulr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_REAL_DIV : forall {A : Type'}, forall m : Metric A, forall f : A -> R, forall g : A -> R, ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) /\ ((@lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) g) /\ ((real_bounded (@IMAGE A R f (@mspace A m))) /\ (~ (@IN R (R_of_nat (NUMERAL O)) (@closure_of R euclideanreal (@IMAGE A R g (@mspace A m)))))))) -> @lipschitz_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => divr (f x) (g x)).
Axiom thm_LIPSCHITZ_CONTINUOUS_MAP_SUM : forall {A K : Type'}, forall m : Metric K, forall f : K -> A -> R, forall k : A -> Prop, ((@finite_set A k) /\ (forall i : A, (@IN A i k) -> @lipschitz_continuous_map R K (@pair (Metric K) (Metric R) m real_euclidean_metric) (fun x : K => f x i))) -> @lipschitz_continuous_map R K (@pair (Metric K) (Metric R) m real_euclidean_metric) (fun x : K => @sum A k (f x)).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_FST : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@uniformly_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) -> @uniformly_continuous_map B A (@pair (Metric A) (Metric B) m m1) (fun x : A => @fst B C (f x)).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_SND : forall {A B C : Type'}, forall m : Metric A, forall m1 : Metric B, forall m2 : Metric C, forall f : A -> prod B C, (@uniformly_continuous_map (prod B C) A (@pair (Metric A) (Metric (prod B C)) m (@prod_metric B C m1 m2)) f) -> @uniformly_continuous_map C A (@pair (Metric A) (Metric C) m m2) (fun x : A => @snd B C (f x)).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_REAL_LMUL : forall {A : Type'}, forall m : Metric A, forall c : R, forall f : A -> R, (@uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => mulr c (f x)).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_REAL_RMUL : forall {A : Type'}, forall m : Metric A, forall c : R, forall f : A -> R, (@uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => mulr (f x) c).
Axiom thm_UNIFORMLY_CONTINUOUS_MAP_REAL_NEG : forall {A : Type'}, forall m : Metric A, forall f : A -> R, (@uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) f) -> @uniformly_continuous_map R A (@pair (Metric A) (Metric R) m real_euclidean_metric) (fun x : A => oppr (f x)).
