Axiom thm_CONTINUOUS_MAP_ON_INTERMEDIATE_CLOSURE_OF : forall {A B : Type'}, forall top : Topology A, forall top' : Topology B, forall f : A -> B, forall s : A -> Prop, forall t : A -> Prop, ((@regular_space B top') /\ ((@subset A t (@closure_of A top s)) /\ (forall x : A, (@IN A x t) -> @limit A B top' f (f x) (@within A (@atpointof A top x) s)))) -> @continuous_map A B (@pair (Topology A) (Topology B) (@subtopology A top t) top') f.
