Axiom thm_REAL_DERIVATIVE_IVT_INCREASING : forall f : R -> R, forall f' : R -> R, forall a : R, forall b : R, ((ler a b) /\ (forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> has_real_derivative f (f' x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))))) -> forall t : R, ((ler (f' a) t) /\ (ler t (f' b))) -> exists x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ ((f' x) = t).
