Axiom thm_HAS_REAL_INTEGRAL_NEGLIGIBLE : forall f : R -> R, forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (f x) = (R_of_nat (NUMERAL O)))) -> has_real_integral f (R_of_nat (NUMERAL O)) t.
Axiom thm_HAS_REAL_INTEGRAL_SPIKE : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, forall y : R, ((real_negligible s) /\ ((forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x)) /\ (has_real_integral f y t))) -> has_real_integral g y t.
Axiom thm_HAS_REAL_INTEGRAL_SPIKE_EQ : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, forall y : R, ((real_negligible s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (has_real_integral f y t) = (has_real_integral g y t).
Axiom thm_REAL_INTEGRABLE_SPIKE : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (real_integrable_on f t) -> real_integrable_on g t.
Axiom thm_REAL_INTEGRABLE_SPIKE_EQ : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (real_integrable_on f t) = (real_integrable_on g t).
Axiom thm_REAL_INTEGRAL_SPIKE : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (real_integral t f) = (real_integral t g).
Axiom thm_REAL_NEGLIGIBLE_SUBSET : forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (@subset R t s)) -> real_negligible t.
Axiom thm_REAL_NEGLIGIBLE_DIFF : forall s : R -> Prop, forall t : R -> Prop, (real_negligible s) -> real_negligible (@setD R s t).
Axiom thm_REAL_NEGLIGIBLE_INTER : forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) \/ (real_negligible t)) -> real_negligible (@setI R s t).
Axiom thm_REAL_NEGLIGIBLE_UNION : forall s : R -> Prop, forall t : R -> Prop, ((real_negligible s) /\ (real_negligible t)) -> real_negligible (@setU R s t).
Axiom thm_REAL_NEGLIGIBLE_UNION_EQ : forall s : R -> Prop, forall t : R -> Prop, (real_negligible (@setU R s t)) = ((real_negligible s) /\ (real_negligible t)).
Axiom thm_REAL_NEGLIGIBLE_SING : forall a : R, real_negligible (@INSERT R a (@set0 R)).
Axiom thm_REAL_NEGLIGIBLE_INSERT : forall a : R, forall s : R -> Prop, (real_negligible (@INSERT R a s)) = (real_negligible s).
Axiom thm_REAL_NEGLIGIBLE_EMPTY : real_negligible (@set0 R).
Axiom thm_REAL_NEGLIGIBLE_FINITE : forall s : R -> Prop, (@finite_set R s) -> real_negligible s.
Axiom thm_REAL_NEGLIGIBLE_UNIONS : forall s : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) s) /\ (forall t : R -> Prop, (@IN (R -> Prop) t s) -> real_negligible t)) -> real_negligible (@UNIONS R s).
Axiom thm_REAL_OPEN_NOT_REAL_NEGLIGIBLE : forall s : R -> Prop, ((real_open s) /\ (~ (s = (@set0 R)))) -> ~ (real_negligible s).
Axiom thm_HAS_REAL_INTEGRAL_SPIKE_FINITE : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall t : R -> Prop, forall y : R, ((@finite_set R s) /\ ((forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x)) /\ (has_real_integral f y t))) -> has_real_integral g y t.
Axiom thm_HAS_REAL_INTEGRAL_SPIKE_FINITE_EQ : forall (t : R -> Prop), forall f : R -> R, forall g : R -> R, forall s : R -> Prop, forall y : R, ((@finite_set R s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (has_real_integral f y t) = (has_real_integral g y t).
Axiom thm_REAL_INTEGRABLE_SPIKE_FINITE : forall (t : R -> Prop), forall f : R -> R, forall g : R -> R, forall s : R -> Prop, ((@finite_set R s) /\ (forall x : R, (@IN R x (@setD R t s)) -> (g x) = (f x))) -> (real_integrable_on f t) -> real_integrable_on g t.
Axiom thm_REAL_NEGLIGIBLE_FRONTIER_INTERVAL : forall a : R, forall b : R, real_negligible (@setD R (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) (open_real_interval (@pair R R a b))).
Axiom thm_HAS_REAL_INTEGRAL_SPIKE_INTERIOR : forall f : R -> R, forall g : R -> R, forall a : R, forall b : R, forall y : R, ((forall x : R, (@IN R x (open_real_interval (@pair R R a b))) -> (g x) = (f x)) /\ (has_real_integral f y (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))))) -> has_real_integral g y (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_HAS_REAL_INTEGRAL_SPIKE_INTERIOR_EQ : forall f : R -> R, forall g : R -> R, forall a : R, forall b : R, forall y : R, (forall x : R, (@IN R x (open_real_interval (@pair R R a b))) -> (g x) = (f x)) -> (has_real_integral f y (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) = (has_real_integral g y (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRABLE_SPIKE_INTERIOR : forall f : R -> R, forall g : R -> R, forall a : R, forall b : R, (forall x : R, (@IN R x (open_real_interval (@pair R R a b))) -> (g x) = (f x)) -> (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> real_integrable_on g (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INTEGRAL_EQ : forall f : R -> R, forall g : R -> R, forall s : R -> Prop, (forall x : R, (@IN R x s) -> (f x) = (g x)) -> (real_integral s f) = (real_integral s g).
Axiom thm_REAL_INTEGRAL_EQ_0 : forall f : R -> R, forall s : R -> Prop, (forall x : R, (@IN R x s) -> (f x) = (R_of_nat (NUMERAL O))) -> (real_integral s f) = (R_of_nat (NUMERAL O)).
Axiom thm_REAL_INTEGRABLE_CONTINUOUS : forall f : R -> R, forall a : R, forall b : R, (real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS : forall f : R -> R, forall f' : R -> R, forall a : R, forall b : R, ((ler a b) /\ (forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> has_real_derivative f (f' x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))))) -> has_real_integral f' (subr (f b) (f a)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INTEGRABLE_SUBINTERVAL : forall f : R -> R, forall a : R, forall b : R, forall c : R, forall d : R, ((real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (@subset R (closed_real_interval (@cons (prod R R) (@pair R R c d) (@nil (prod R R)))) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))))) -> real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R c d) (@nil (prod R R)))).
Axiom thm_HAS_REAL_INTEGRAL_COMBINE : forall f : R -> R, forall i : R, forall j : R, forall a : R, forall b : R, forall c : R, ((ler a c) /\ ((ler c b) /\ ((has_real_integral f i (closed_real_interval (@cons (prod R R) (@pair R R a c) (@nil (prod R R))))) /\ (has_real_integral f j (closed_real_interval (@cons (prod R R) (@pair R R c b) (@nil (prod R R)))))))) -> has_real_integral f (addr i j) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INTEGRAL_COMBINE : forall f : R -> R, forall a : R, forall b : R, forall c : R, ((ler a c) /\ ((ler c b) /\ (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))))) -> (addr (real_integral (closed_real_interval (@cons (prod R R) (@pair R R a c) (@nil (prod R R)))) f) (real_integral (closed_real_interval (@cons (prod R R) (@pair R R c b) (@nil (prod R R)))) f)) = (real_integral (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) f).
Axiom thm_REAL_INTEGRABLE_COMBINE : forall f : R -> R, forall a : R, forall b : R, forall c : R, ((ler a c) /\ ((ler c b) /\ ((real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a c) (@nil (prod R R))))) /\ (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R c b) (@nil (prod R R)))))))) -> real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INTEGRABLE_ON_LITTLE_SUBINTERVALS : forall f : R -> R, forall a : R, forall b : R, (forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> exists d : R, (ltr (R_of_nat (NUMERAL O)) d) /\ (forall u : R, forall v : R, ((@IN R x (closed_real_interval (@cons (prod R R) (@pair R R u v) (@nil (prod R R))))) /\ (forall y : R, (@IN R y (closed_real_interval (@cons (prod R R) (@pair R R u v) (@nil (prod R R))))) -> (ltr (normr (subr y x)) d) /\ (@IN R y (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))))) -> real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R u v) (@nil (prod R R)))))) -> real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INTEGRAL_HAS_REAL_DERIVATIVE_POINTWISE : forall f : R -> R, forall a : R, forall b : R, forall x : R, ((real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ ((@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (@real_continuous R f (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))))))) -> has_real_derivative (fun u : R => real_integral (closed_real_interval (@cons (prod R R) (@pair R R a u) (@nil (prod R R)))) f) (f x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRAL_HAS_REAL_DERIVATIVE : forall f : R -> R, forall a : R, forall b : R, (real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> has_real_derivative (fun u : R => real_integral (closed_real_interval (@cons (prod R R) (@pair R R a u) (@nil (prod R R)))) f) (f x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_ANTIDERIVATIVE_CONTINUOUS : forall f : R -> R, forall a : R, forall b : R, (real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> exists g : R -> R, forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> has_real_derivative g (f x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_ANTIDERIVATIVE_INTEGRAL_CONTINUOUS : forall f : R -> R, forall a : R, forall b : R, (real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> exists g : R -> R, forall u : R, forall v : R, ((@IN R u (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ ((@IN R v (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (ler u v))) -> has_real_integral f (subr (g v) (g u)) (closed_real_interval (@cons (prod R R) (@pair R R u v) (@nil (prod R R)))).
Axiom thm_HAS_REAL_INTEGRAL_AFFINITY : forall f : R -> R, forall i : R, forall a : R, forall b : R, forall m : R, forall c : R, ((has_real_integral f i (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (~ (m = (R_of_nat (NUMERAL O))))) -> has_real_integral (fun x : R => f (addr (mulr m x) c)) (mulr (invr (normr m)) i) (@IMAGE R R (fun x : R => mulr (invr m) (subr x c)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRABLE_AFFINITY : forall f : R -> R, forall a : R, forall b : R, forall m : R, forall c : R, ((real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (~ (m = (R_of_nat (NUMERAL O))))) -> real_integrable_on (fun x : R => f (addr (mulr m x) c)) (@IMAGE R R (fun x : R => mulr (invr m) (subr x c)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_HAS_REAL_INTEGRAL_STRETCH : forall f : R -> R, forall i : R, forall a : R, forall b : R, forall m : R, ((has_real_integral f i (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (~ (m = (R_of_nat (NUMERAL O))))) -> has_real_integral (fun x : R => f (mulr m x)) (mulr (invr (normr m)) i) (@IMAGE R R (fun x : R => mulr (invr m) x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRABLE_STRETCH : forall f : R -> R, forall a : R, forall b : R, forall m : R, ((real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (~ (m = (R_of_nat (NUMERAL O))))) -> real_integrable_on (fun x : R => f (mulr m x)) (@IMAGE R R (fun x : R => mulr (invr m) x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_HAS_REAL_INTEGRAL_REFLECT_LEMMA : forall f : R -> R, forall i : R, forall a : R, forall b : R, (has_real_integral f i (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> has_real_integral (fun x : R => f (oppr x)) i (closed_real_interval (@cons (prod R R) (@pair R R (oppr b) (oppr a)) (@nil (prod R R)))).
Axiom thm_HAS_REAL_INTEGRAL_REFLECT : forall f : R -> R, forall i : R, forall a : R, forall b : R, (has_real_integral (fun x : R => f (oppr x)) i (closed_real_interval (@cons (prod R R) (@pair R R (oppr b) (oppr a)) (@nil (prod R R))))) = (has_real_integral f i (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRABLE_REFLECT : forall f : R -> R, forall a : R, forall b : R, (real_integrable_on (fun x : R => f (oppr x)) (closed_real_interval (@cons (prod R R) (@pair R R (oppr b) (oppr a)) (@nil (prod R R))))) = (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))).
Axiom thm_REAL_INTEGRAL_REFLECT : forall f : R -> R, forall a : R, forall b : R, (real_integral (closed_real_interval (@cons (prod R R) (@pair R R (oppr b) (oppr a)) (@nil (prod R R)))) (fun x : R => f (oppr x))) = (real_integral (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) f).
Axiom thm_HAS_REAL_INTEGRAL_REFLECT_GEN : forall f : R -> R, forall i : R, forall s : R -> Prop, (has_real_integral (fun x : R => f (oppr x)) i s) = (has_real_integral f i (@IMAGE R R oppr s)).
Axiom thm_REAL_INTEGRABLE_REFLECT_GEN : forall f : R -> R, forall s : R -> Prop, (real_integrable_on (fun x : R => f (oppr x)) s) = (real_integrable_on f (@IMAGE R R oppr s)).
Axiom thm_REAL_INTEGRAL_REFLECT_GEN : forall f : R -> R, forall s : R -> Prop, (real_integral s (fun x : R => f (oppr x))) = (real_integral (@IMAGE R R oppr s) f).
Axiom thm_REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS_INTERIOR : forall f : R -> R, forall f' : R -> R, forall a : R, forall b : R, ((ler a b) /\ ((real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (forall x : R, (@IN R x (open_real_interval (@pair R R a b))) -> has_real_derivative f (f' x) (atreal x)))) -> has_real_integral f' (subr (f b) (f a)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS_INTERIOR_STRONG : forall f : R -> R, forall f' : R -> R, forall s : R -> Prop, forall a : R, forall b : R, ((@COUNTABLE R s) /\ ((ler a b) /\ ((real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (forall x : R, (@IN R x (@setD R (open_real_interval (@pair R R a b)) s)) -> has_real_derivative f (f' x) (atreal x))))) -> has_real_integral f' (subr (f b) (f a)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_FUNDAMENTAL_THEOREM_OF_CALCULUS_STRONG : forall f : R -> R, forall f' : R -> R, forall s : R -> Prop, forall a : R, forall b : R, ((@COUNTABLE R s) /\ ((ler a b) /\ ((real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (forall x : R, (@IN R x (@setD R (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) s)) -> has_real_derivative f (f' x) (atreal x))))) -> has_real_integral f' (subr (f b) (f a)) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INDEFINITE_INTEGRAL_CONTINUOUS_RIGHT : forall f : R -> R, forall a : R, forall b : R, (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> real_continuous_on (fun x : R => real_integral (closed_real_interval (@cons (prod R R) (@pair R R a x) (@nil (prod R R)))) f) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_REAL_INDEFINITE_INTEGRAL_CONTINUOUS_LEFT : forall f : R -> R, forall a : R, forall b : R, (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> real_continuous_on (fun x : R => real_integral (closed_real_interval (@cons (prod R R) (@pair R R x b) (@nil (prod R R)))) f) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))).
Axiom thm_HAS_REAL_DERIVATIVE_ZERO_UNIQUE_STRONG_INTERVAL : forall f : R -> R, forall a : R, forall b : R, forall k : R -> Prop, forall y : R, ((@COUNTABLE R k) /\ ((real_continuous_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (((f a) = y) /\ (forall x : R, (@IN R x (@setD R (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) k)) -> has_real_derivative f (R_of_nat (NUMERAL O)) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))))))) -> forall x : R, (@IN R x (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> (f x) = y.
Axiom thm_HAS_REAL_DERIVATIVE_ZERO_UNIQUE_STRONG_CONVEX : forall f : R -> R, forall s : R -> Prop, forall k : R -> Prop, forall c : R, forall y : R, ((is_realinterval s) /\ ((@COUNTABLE R k) /\ ((real_continuous_on f s) /\ ((@IN R c s) /\ (((f c) = y) /\ (forall x : R, (@IN R x (@setD R s k)) -> has_real_derivative f (R_of_nat (NUMERAL O)) (@within R (atreal x) s))))))) -> forall x : R, (@IN R x s) -> (f x) = y.
Axiom thm_HAS_REAL_DERIVATIVE_INDEFINITE_INTEGRAL : forall f : R -> R, forall a : R, forall b : R, (real_integrable_on f (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) -> exists k : R -> Prop, (real_negligible k) /\ (forall x : R, (@IN R x (@setD R (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) k)) -> has_real_derivative (fun x' : R => real_integral (closed_real_interval (@cons (prod R R) (@pair R R a x') (@nil (prod R R)))) f) (f x) (@within R (atreal x) (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))))).
