Axiom thm_ABSOLUTELY_REAL_INTEGRABLE_INF : forall {A : Type'}, forall fs : R -> A -> R, forall s : R -> Prop, forall k : A -> Prop, ((@finite_set A k) /\ ((~ (k = (@set0 A))) /\ (forall i : A, (@IN A i k) -> absolutely_real_integrable_on (fun x : R => fs x i) s))) -> absolutely_real_integrable_on (fun x : R => inf (@IMAGE A R (fs x) k)) s.
