Axiom thm_REAL_DOMINATED_CONVERGENCE : forall f : nat -> R -> R, forall g : R -> R, forall h : R -> R, forall s : R -> Prop, ((forall k : nat, real_integrable_on (f k) s) /\ ((real_integrable_on h s) /\ ((forall k : nat, forall x : R, (@IN R x s) -> ler (normr (f k x)) (h x)) /\ (forall x : R, (@IN R x s) -> @longarrow nat (fun k : nat => f k x) (g x) sequentially)))) -> (real_integrable_on g s) /\ (@longarrow nat (fun k : nat => real_integral s (f k)) (real_integral s g) sequentially).
Axiom thm_HAS_REAL_MEASURE_HAS_MEASURE : forall s : R -> Prop, forall m : R, (has_real_measure s m) = (@has_measure unit (@IMAGE R (cart R unit) lift s) m).
Axiom thm_REAL_MEASURABLE_MEASURABLE : forall s : R -> Prop, (real_measurable s) = (@measurable unit (@IMAGE R (cart R unit) lift s)).
Axiom thm_REAL_MEASURE_MEASURE : forall s : R -> Prop, (real_measure s) = (@measure unit (@IMAGE R (cart R unit) lift s)).
Axiom thm_HAS_REAL_MEASURE_MEASURE : forall s : R -> Prop, (real_measurable s) = (has_real_measure s (real_measure s)).
Axiom thm_HAS_REAL_MEASURE_UNIQUE : forall s : R -> Prop, forall m1 : R, forall m2 : R, ((has_real_measure s m1) /\ (has_real_measure s m2)) -> m1 = m2.
Axiom thm_REAL_MEASURE_UNIQUE : forall s : R -> Prop, forall m : R, (has_real_measure s m) -> (real_measure s) = m.
Axiom thm_HAS_REAL_MEASURE_REAL_MEASURABLE_REAL_MEASURE : forall s : R -> Prop, forall m : R, (has_real_measure s m) = ((real_measurable s) /\ ((real_measure s) = m)).
Axiom thm_HAS_REAL_MEASURE_IMP_REAL_MEASURABLE : forall s : R -> Prop, forall m : R, (has_real_measure s m) -> real_measurable s.
Axiom thm_HAS_REAL_MEASURE : forall s : R -> Prop, forall m : R, (has_real_measure s m) = (has_real_integral (fun x : R => @COND R (@IN R x s) (R_of_nat (NUMERAL (BIT1 O))) (R_of_nat (NUMERAL O))) m (@setT R)).
Axiom thm_REAL_MEASURABLE : forall s : R -> Prop, (real_measurable s) = (real_integrable_on (fun x : R => R_of_nat (NUMERAL (BIT1 O))) s).
Axiom thm_REAL_MEASURABLE_REAL_INTEGRABLE : forall (s : R -> Prop), (real_measurable s) = (real_integrable_on (fun x : R => @COND R (@IN R x s) (R_of_nat (NUMERAL (BIT1 O))) (R_of_nat (NUMERAL O))) (@setT R)).
Axiom thm_REAL_MEASURE_REAL_INTEGRAL : forall s : R -> Prop, (real_measurable s) -> (real_measure s) = (real_integral s (fun x : R => R_of_nat (NUMERAL (BIT1 O)))).
Axiom thm_REAL_MEASURE_REAL_INTEGRAL_UNIV : forall s : R -> Prop, (real_measurable s) -> (real_measure s) = (real_integral (@setT R) (fun x : R => @COND R (@IN R x s) (R_of_nat (NUMERAL (BIT1 O))) (R_of_nat (NUMERAL O)))).
Axiom thm_REAL_INTEGRAL_REAL_MEASURE : forall s : R -> Prop, (real_measurable s) -> (real_integral s (fun x : R => R_of_nat (NUMERAL (BIT1 O)))) = (real_measure s).
Axiom thm_REAL_INTEGRAL_REAL_MEASURE_UNIV : forall s : R -> Prop, (real_measurable s) -> (real_integral (@setT R) (fun x : R => @COND R (@IN R x s) (R_of_nat (NUMERAL (BIT1 O))) (R_of_nat (NUMERAL O)))) = (real_measure s).
Axiom thm_HAS_REAL_MEASURE_REAL_INTERVAL : (forall a : R, forall b : R, has_real_measure (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R)))) (maxr (subr b a) (R_of_nat (NUMERAL O)))) /\ (forall a : R, forall b : R, has_real_measure (open_real_interval (@pair R R a b)) (maxr (subr b a) (R_of_nat (NUMERAL O)))).
Axiom thm_REAL_MEASURABLE_REAL_INTERVAL : (forall a : R, forall b : R, real_measurable (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (forall a : R, forall b : R, real_measurable (open_real_interval (@pair R R a b))).
Axiom thm_REAL_MEASURE_REAL_INTERVAL : (forall a : R, forall b : R, (real_measure (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) = (maxr (subr b a) (R_of_nat (NUMERAL O)))) /\ (forall a : R, forall b : R, (real_measure (open_real_interval (@pair R R a b))) = (maxr (subr b a) (R_of_nat (NUMERAL O)))).
Axiom thm_REAL_MEASURABLE_REAL_SEGMENT : (forall a : R, forall b : R, real_measurable (closed_real_segment (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) /\ (forall a : R, forall b : R, real_measurable (open_real_segment (@pair R R a b))).
Axiom thm_REAL_MEASURE_REAL_SEGMENT : (forall a : R, forall b : R, (real_measure (closed_real_segment (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) = (normr (subr b a))) /\ (forall a : R, forall b : R, (real_measure (open_real_segment (@pair R R a b))) = (normr (subr b a))).
Axiom thm_REAL_MEASURABLE_INTER : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_measurable t)) -> real_measurable (@setI R s t).
Axiom thm_REAL_MEASURABLE_UNION : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_measurable t)) -> real_measurable (@setU R s t).
Axiom thm_HAS_REAL_MEASURE_DISJOINT_UNION : forall s1 : R -> Prop, forall s2 : R -> Prop, forall m1 : R, forall m2 : R, ((has_real_measure s1 m1) /\ ((has_real_measure s2 m2) /\ (@DISJOINT R s1 s2))) -> has_real_measure (@setU R s1 s2) (addr m1 m2).
Axiom thm_REAL_MEASURE_DISJOINT_UNION : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ ((real_measurable t) /\ (@DISJOINT R s t))) -> (real_measure (@setU R s t)) = (addr (real_measure s) (real_measure t)).
Axiom thm_HAS_REAL_MEASURE_POS_LE : forall m : R, forall s : R -> Prop, (has_real_measure s m) -> ler (R_of_nat (NUMERAL O)) m.
Axiom thm_REAL_MEASURE_POS_LE : forall s : R -> Prop, (real_measurable s) -> ler (R_of_nat (NUMERAL O)) (real_measure s).
Axiom thm_HAS_REAL_MEASURE_SUBSET : forall s1 : R -> Prop, forall s2 : R -> Prop, forall m1 : R, forall m2 : R, ((has_real_measure s1 m1) /\ ((has_real_measure s2 m2) /\ (@subset R s1 s2))) -> ler m1 m2.
Axiom thm_REAL_MEASURE_SUBSET : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ ((real_measurable t) /\ (@subset R s t))) -> ler (real_measure s) (real_measure t).
Axiom thm_HAS_REAL_MEASURE_0 : forall s : R -> Prop, (has_real_measure s (R_of_nat (NUMERAL O))) = (real_negligible s).
Axiom thm_REAL_MEASURE_EQ_0 : forall s : R -> Prop, (real_negligible s) -> (real_measure s) = (R_of_nat (NUMERAL O)).
Axiom thm_HAS_REAL_MEASURE_EMPTY : has_real_measure (@set0 R) (R_of_nat (NUMERAL O)).
Axiom thm_REAL_MEASURE_EMPTY : (real_measure (@set0 R)) = (R_of_nat (NUMERAL O)).
Axiom thm_REAL_MEASURABLE_EMPTY : real_measurable (@set0 R).
Axiom thm_REAL_MEASURABLE_REAL_MEASURE_EQ_0 : forall s : R -> Prop, (real_measurable s) -> ((real_measure s) = (R_of_nat (NUMERAL O))) = (real_negligible s).
Axiom thm_REAL_MEASURABLE_REAL_MEASURE_POS_LT : forall s : R -> Prop, (real_measurable s) -> (ltr (R_of_nat (NUMERAL O)) (real_measure s)) = (~ (real_negligible s)).
Axiom thm_REAL_NEGLIGIBLE_REAL_INTERVAL : (forall a : R, forall b : R, (real_negligible (closed_real_interval (@cons (prod R R) (@pair R R a b) (@nil (prod R R))))) = ((open_real_interval (@pair R R a b)) = (@set0 R))) /\ (forall a : R, forall b : R, (real_negligible (open_real_interval (@pair R R a b))) = ((open_real_interval (@pair R R a b)) = (@set0 R))).
Axiom thm_REAL_MEASURABLE_UNIONS : forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ (forall s : R -> Prop, (@IN (R -> Prop) s f) -> real_measurable s)) -> real_measurable (@UNIONS R f).
Axiom thm_HAS_REAL_MEASURE_DIFF_SUBSET : forall s1 : R -> Prop, forall s2 : R -> Prop, forall m1 : R, forall m2 : R, ((has_real_measure s1 m1) /\ ((has_real_measure s2 m2) /\ (@subset R s2 s1))) -> has_real_measure (@setD R s1 s2) (subr m1 m2).
Axiom thm_REAL_MEASURABLE_DIFF : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_measurable t)) -> real_measurable (@setD R s t).
Axiom thm_REAL_MEASURE_DIFF_SUBSET : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ ((real_measurable t) /\ (@subset R t s))) -> (real_measure (@setD R s t)) = (subr (real_measure s) (real_measure t)).
Axiom thm_HAS_REAL_MEASURE_UNION_REAL_NEGLIGIBLE : forall s : R -> Prop, forall t : R -> Prop, forall m : R, ((has_real_measure s m) /\ (real_negligible t)) -> has_real_measure (@setU R s t) m.
Axiom thm_HAS_REAL_MEASURE_DIFF_REAL_NEGLIGIBLE : forall s : R -> Prop, forall t : R -> Prop, forall m : R, ((has_real_measure s m) /\ (real_negligible t)) -> has_real_measure (@setD R s t) m.
Axiom thm_HAS_REAL_MEASURE_UNION_REAL_NEGLIGIBLE_EQ : forall s : R -> Prop, forall t : R -> Prop, forall m : R, (real_negligible t) -> (has_real_measure (@setU R s t) m) = (has_real_measure s m).
Axiom thm_HAS_REAL_MEASURE_DIFF_REAL_NEGLIGIBLE_EQ : forall s : R -> Prop, forall t : R -> Prop, forall m : R, (real_negligible t) -> (has_real_measure (@setD R s t) m) = (has_real_measure s m).
Axiom thm_HAS_REAL_MEASURE_ALMOST : forall s : R -> Prop, forall s' : R -> Prop, forall t : R -> Prop, forall m : R, ((has_real_measure s m) /\ ((real_negligible t) /\ ((@setU R s t) = (@setU R s' t)))) -> has_real_measure s' m.
Axiom thm_HAS_REAL_MEASURE_ALMOST_EQ : forall (m : R), forall s : R -> Prop, forall s' : R -> Prop, forall t : R -> Prop, ((real_negligible t) /\ ((@setU R s t) = (@setU R s' t))) -> (has_real_measure s m) = (has_real_measure s' m).
Axiom thm_REAL_MEASURABLE_ALMOST : forall s : R -> Prop, forall s' : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ ((real_negligible t) /\ ((@setU R s t) = (@setU R s' t)))) -> real_measurable s'.
Axiom thm_HAS_REAL_MEASURE_REAL_NEGLIGIBLE_UNION : forall s1 : R -> Prop, forall s2 : R -> Prop, forall m1 : R, forall m2 : R, ((has_real_measure s1 m1) /\ ((has_real_measure s2 m2) /\ (real_negligible (@setI R s1 s2)))) -> has_real_measure (@setU R s1 s2) (addr m1 m2).
Axiom thm_REAL_MEASURE_REAL_NEGLIGIBLE_UNION : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ ((real_measurable t) /\ (real_negligible (@setI R s t)))) -> (real_measure (@setU R s t)) = (addr (real_measure s) (real_measure t)).
Axiom thm_HAS_REAL_MEASURE_REAL_NEGLIGIBLE_SYMDIFF : forall s : R -> Prop, forall t : R -> Prop, forall m : R, ((has_real_measure s m) /\ (real_negligible (@setU R (@setD R s t) (@setD R t s)))) -> has_real_measure t m.
Axiom thm_REAL_MEASURABLE_REAL_NEGLIGIBLE_SYMDIFF : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_negligible (@setU R (@setD R s t) (@setD R t s)))) -> real_measurable t.
Axiom thm_REAL_MEASURE_REAL_NEGLIGIBLE_SYMDIFF : forall s : R -> Prop, forall t : R -> Prop, (((real_measurable s) \/ (real_measurable t)) /\ (real_negligible (@setU R (@setD R s t) (@setD R t s)))) -> (real_measure s) = (real_measure t).
Axiom thm_HAS_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS : forall m : (R -> Prop) -> R, forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ ((forall s : R -> Prop, (@IN (R -> Prop) s f) -> has_real_measure s (m s)) /\ (forall s : R -> Prop, forall t : R -> Prop, ((@IN (R -> Prop) s f) /\ ((@IN (R -> Prop) t f) /\ (~ (s = t)))) -> real_negligible (@setI R s t)))) -> has_real_measure (@UNIONS R f) (@sum (R -> Prop) f m).
Axiom thm_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS : forall m : (R -> Prop) -> R, forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ ((forall s : R -> Prop, (@IN (R -> Prop) s f) -> has_real_measure s (m s)) /\ (forall s : R -> Prop, forall t : R -> Prop, ((@IN (R -> Prop) s f) /\ ((@IN (R -> Prop) t f) /\ (~ (s = t)))) -> real_negligible (@setI R s t)))) -> (real_measure (@UNIONS R f)) = (@sum (R -> Prop) f m).
Axiom thm_HAS_REAL_MEASURE_DISJOINT_UNIONS : forall m : (R -> Prop) -> R, forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ ((forall s : R -> Prop, (@IN (R -> Prop) s f) -> has_real_measure s (m s)) /\ (forall s : R -> Prop, forall t : R -> Prop, ((@IN (R -> Prop) s f) /\ ((@IN (R -> Prop) t f) /\ (~ (s = t)))) -> @DISJOINT R s t))) -> has_real_measure (@UNIONS R f) (@sum (R -> Prop) f m).
Axiom thm_REAL_MEASURE_DISJOINT_UNIONS : forall m : (R -> Prop) -> R, forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ ((forall s : R -> Prop, (@IN (R -> Prop) s f) -> has_real_measure s (m s)) /\ (forall s : R -> Prop, forall t : R -> Prop, ((@IN (R -> Prop) s f) /\ ((@IN (R -> Prop) t f) /\ (~ (s = t)))) -> @DISJOINT R s t))) -> (real_measure (@UNIONS R f)) = (@sum (R -> Prop) f m).
Axiom thm_HAS_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS_IMAGE : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A s) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> real_negligible (@setI R (f x) (f y))))) -> has_real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s)) (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS_IMAGE : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A s) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> real_negligible (@setI R (f x) (f y))))) -> (real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s))) = (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_HAS_REAL_MEASURE_DISJOINT_UNIONS_IMAGE : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A s) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> @DISJOINT R (f x) (f y)))) -> has_real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s)) (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_REAL_MEASURE_DISJOINT_UNIONS_IMAGE : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A s) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> @DISJOINT R (f x) (f y)))) -> (real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s))) = (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_HAS_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS_IMAGE_STRONG : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A (@GSPEC A (fun GEN_PVAR_8508 : A => exists x : A, @SETSPEC A GEN_PVAR_8508 ((@IN A x s) /\ (~ ((f x) = (@set0 R)))) x))) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> real_negligible (@setI R (f x) (f y))))) -> has_real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s)) (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_REAL_MEASURE_REAL_NEGLIGIBLE_UNIONS_IMAGE_STRONG : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A (@GSPEC A (fun GEN_PVAR_8509 : A => exists x : A, @SETSPEC A GEN_PVAR_8509 ((@IN A x s) /\ (~ ((f x) = (@set0 R)))) x))) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> real_negligible (@setI R (f x) (f y))))) -> (real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s))) = (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_HAS_REAL_MEASURE_DISJOINT_UNIONS_IMAGE_STRONG : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A (@GSPEC A (fun GEN_PVAR_8510 : A => exists x : A, @SETSPEC A GEN_PVAR_8510 ((@IN A x s) /\ (~ ((f x) = (@set0 R)))) x))) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> @DISJOINT R (f x) (f y)))) -> has_real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s)) (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_REAL_MEASURE_DISJOINT_UNIONS_IMAGE_STRONG : forall {A : Type'}, forall f : A -> R -> Prop, forall s : A -> Prop, ((@finite_set A (@GSPEC A (fun GEN_PVAR_8511 : A => exists x : A, @SETSPEC A GEN_PVAR_8511 ((@IN A x s) /\ (~ ((f x) = (@set0 R)))) x))) /\ ((forall x : A, (@IN A x s) -> real_measurable (f x)) /\ (forall x : A, forall y : A, ((@IN A x s) /\ ((@IN A y s) /\ (~ (x = y)))) -> @DISJOINT R (f x) (f y)))) -> (real_measure (@UNIONS R (@IMAGE A (R -> Prop) f s))) = (@sum A s (fun x : A => real_measure (f x))).
Axiom thm_REAL_MEASURE_UNION : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_measurable t)) -> (real_measure (@setU R s t)) = (addr (real_measure s) (subr (real_measure t) (real_measure (@setI R s t)))).
Axiom thm_REAL_MEASURE_UNION_LE : forall s : R -> Prop, forall t : R -> Prop, ((real_measurable s) /\ (real_measurable t)) -> ler (real_measure (@setU R s t)) (addr (real_measure s) (real_measure t)).
Axiom thm_REAL_MEASURE_UNIONS_LE : forall f : (R -> Prop) -> Prop, ((@finite_set (R -> Prop) f) /\ (forall s : R -> Prop, (@IN (R -> Prop) s f) -> real_measurable s)) -> ler (real_measure (@UNIONS R f)) (@sum (R -> Prop) f (fun s : R -> Prop => real_measure s)).
Axiom thm_REAL_MEASURE_UNIONS_LE_IMAGE : forall {A : Type'}, forall f : A -> Prop, forall s : A -> R -> Prop, ((@finite_set A f) /\ (forall a : A, (@IN A a f) -> real_measurable (s a))) -> ler (real_measure (@UNIONS R (@IMAGE A (R -> Prop) s f))) (@sum A f (fun a : A => real_measure (s a))).
Axiom thm_REAL_NEGLIGIBLE_OUTER : forall s : R -> Prop, (real_negligible s) = (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists t : R -> Prop, (@subset R s t) /\ ((real_measurable t) /\ (ltr (real_measure t) e))).
Axiom thm_REAL_NEGLIGIBLE_OUTER_LE : forall s : R -> Prop, (real_negligible s) = (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists t : R -> Prop, (@subset R s t) /\ ((real_measurable t) /\ (ler (real_measure t) e))).
Axiom thm_REAL_MEASURABLE_INNER_OUTER : forall s : R -> Prop, (real_measurable s) = (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists t : R -> Prop, exists u : R -> Prop, (@subset R t s) /\ ((@subset R s u) /\ ((real_measurable t) /\ ((real_measurable u) /\ (ltr (normr (subr (real_measure t) (real_measure u))) e))))).
Axiom thm_HAS_REAL_MEASURE_INNER_OUTER : forall s : R -> Prop, forall m : R, (has_real_measure s m) = ((forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists t : R -> Prop, (@subset R t s) /\ ((real_measurable t) /\ (ltr (subr m e) (real_measure t)))) /\ (forall e : R, (ltr (R_of_nat (NUMERAL O)) e) -> exists u : R -> Prop, (@subset R s u) /\ ((real_measurable u) /\ (ltr (real_measure u) (addr m e))))).
